// ─────────────────────────────────────────────────────────────────────────────
// FunctionNameGenerator
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Default, Clone)]
pub struct FunctionNameGenerator {
    counter: u64,
}

impl FunctionNameGenerator {
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    #[must_use]
    pub fn name_for(&mut self, address: u64, hint: Option<&str>) -> String {
        if let Some(h) = hint
            && !h.is_empty() {
                return sanitize_c_identifier(h);
            }
        let name = format!("sub_{address:x}");
        self.counter += 1;
        name
    }

    #[must_use]
    pub const fn count(&self) -> u64 {
        self.counter
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// DecompilationResult
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum DecompilationResult {
    Success(DecompiledFunction),
    Failure { address: u64, message: String },
}

impl DecompilationResult {
    #[must_use]
    pub const fn is_success(&self) -> bool {
        matches!(self, Self::Success(_))
    }

    #[must_use]
    /// # Panics
    ///
    /// Panics if this result is a `Failure`.
    pub fn unwrap_function(self) -> DecompiledFunction {
        match self {
            Self::Success(f) => f,
            Self::Failure { address, message } => {
                panic!("decompilation of {address:#x} failed: {message}")
            }
        }
    }
}

