    #[test]
    fn unused_params_counts_only_never_referenced_ones() {
        let code = "__int64 __fastcall f(int a1, __int64 a2, char *a3) {\n    return a1 + a2;\n}\n";
        // a1/a2 are used; a3 is declared and never referenced.
        assert_eq!(count_unused_params(code), 1);
    }

    #[test]
    fn unused_params_ignores_control_flow_headers() {
        // The signature matcher must not latch onto `while (…) {`. If it did,
        // it would parse `v1 < 10` as a parameter list.
        let code = "void f(void) {\n    while (v1 < 10) {\n        v1++;\n    }\n}\n";
        assert_eq!(count_unused_params(code), 0);
    }

    #[test]
    fn unused_params_not_fooled_by_substring_matches() {
        // `a1` must not be counted as "used" by `a10` or `xa1`.
        let code = "int f(int a1) {\n    return a10 + xa1;\n}\n";
        assert_eq!(count_unused_params(code), 1);
    }

    #[test]
    fn phantom_params_lower_confidence_below_a_clean_body() {
        let clean = "__int64 f(int a1) {\n    return a1;\n}\n";
        let phantom = "__int64 f(int a1, int a2, int a3, int a4) {\n    return a1;\n}\n";
        // Both are syntactically perfect and both compile — only the phantom
        // signal can tell them apart.
        assert!(
            score_confidence(phantom) < score_confidence(clean),
            "phantom params must lower confidence: {} vs {}",
            score_confidence(phantom),
            score_confidence(clean)
        );
    }

    // ── IlAnalysisPass ───────────────────────────────────────────────────────

    #[test]
    fn il_analysis_pass_records_full_coverage() {
        // `push rbp` (0x55) ; `ret` (0xc3) — both real, fully-supported
        // encodings, contiguous addresses, real byte payloads.
        let insns = vec![
            Instruction::new(rustre_core::address::Address::new(0x1000), 1, "push", vec![0x55]),
            Instruction::new(rustre_core::address::Address::new(0x1001), 1, "ret", vec![0xc3]),
        ];
        let mut ctx = DecompilerContext::new(0x1000, "f", DecompOptions::default());
        let pass = IlAnalysisPass;
        pass.run(&mut ctx, 0x1000, &insns).unwrap();
        assert_eq!(ctx.annotation("il_instr_count"), Some("2"));
        assert_eq!(ctx.annotation("il_coverage_pct"), Some("100.0"));
        assert_eq!(ctx.annotation("il_unimplemented_mnemonics"), None);
        // Gate default OFF ⇒ the rustre-il tier annotation is absent, which is
        // what keeps path A byte-identical (REGOLA #28).
        assert_eq!(ctx.annotation("il_tier"), None);
    }

    #[test]
    fn il_tier_annotation_is_gated_and_comes_from_rustre_il() {
        // The gate itself: unset and falsy values must stay OFF.
        assert!(!il_tier_annot_opt_in(None));
        for v in ["0", "", "false", "no", "off", " OFF "] {
            assert!(!il_tier_annot_opt_in(Some(v)), "{v:?} must be OFF");
        }
        assert!(il_tier_annot_opt_in(Some("1")));

        // SAFETY: single-threaded test body; the gate is a plain env read.
        unsafe { std::env::set_var("RUSTRE_IL_TIER_ANNOT", "1") };
        let insns = vec![
            Instruction::new(rustre_core::address::Address::new(0x1000), 1, "push", vec![0x55]),
            Instruction::new(rustre_core::address::Address::new(0x1001), 1, "ret", vec![0xc3]),
        ];
        let mut ctx = DecompilerContext::new(0x1000, "f", DecompOptions::default());
        let res = IlAnalysisPass.run(&mut ctx, 0x1000, &insns);
        // Restore before asserting so a failure cannot leak the env var.
        unsafe { std::env::remove_var("RUSTRE_IL_TIER_ANNOT") };
        res.unwrap();

        // The value is `rustre_il::IlTier::Llil.tag()`, not a local literal.
        assert_eq!(ctx.annotation("il_tier"), Some("llil"));
        assert_eq!(ctx.annotation("il_tier"), Some(rustre_il::IlTier::Llil.tag()));
    }

    #[test]
    fn il_analysis_pass_skips_non_contiguous_gap() {
        // Second instruction's address doesn't follow the first's
        // end-of-bytes — must stop at the contiguous prefix, not splice.
        let insns = vec![
            Instruction::new(rustre_core::address::Address::new(0x1000), 1, "push", vec![0x55]),
            Instruction::new(rustre_core::address::Address::new(0x2000), 1, "ret", vec![0xc3]),
        ];
        let mut ctx = DecompilerContext::new(0x1000, "f", DecompOptions::default());
        let pass = IlAnalysisPass;
        pass.run(&mut ctx, 0x1000, &insns).unwrap();
        // Only the first (contiguous prefix) instruction gets lifted.
        assert_eq!(ctx.annotation("il_instr_count"), Some("1"));
    }

