    /// Minimal self-contained LCG — no external RNG dependency needed,
    /// mirrors the same pattern already used for `rustre-arch-x86`'s own
    /// `fuzz_decode_disasm_lift_never_panics_*` tests.
    struct Lcg(u64);
    impl Lcg {
        fn next(&mut self) -> u64 {
            self.0 = self.0.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
            self.0
        }
    }

    #[test]
    fn il_analysis_pass_hlil_experimental_never_panics_on_random_bytes() {
        // Stress-test the new LLIL->MLIL->HLIL->print path (added for the
        // "feed LLIL through MLIL/HLIL into the real pipeline" integration
        // step) against arbitrary byte sequences, not just the two
        // hand-crafted push/ret instructions the other unit tests use.
        // Random fuzzing exercises more of iced's decode surface (and thus
        // more LLIL/MLIL/HLIL construction paths) than a handful of curated
        // real-world samples would in the same amount of test code.
        let mut opts = DecompOptions::default();
        opts.passes.hlil_experimental = true;

        let prev = std::panic::take_hook();
        std::panic::set_hook(Box::new(|_| {}));
        let mut rng = Lcg(0xabad_1dea_dead_beef);
        let mut first_panic: Option<Vec<u8>> = None;
        for _ in 0..2000 {
            let len = 1 + (rng.next() % 32) as usize;
            let bytes: Vec<u8> = (0..len).map(|_| (rng.next() >> 24) as u8).collect();
            let insns = vec![Instruction::new(
                rustre_core::address::Address::new(0x1000),
                bytes.len(),
                "?",
                bytes.clone(),
            )];
            let mut ctx = DecompilerContext::new(0x1000, "f", opts.clone());
            let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let _ = IlAnalysisPass.run(&mut ctx, 0x1000, &insns);
            }));
            if r.is_err() {
                first_panic = Some(bytes);
                break;
            }
        }
        std::panic::set_hook(prev);
        assert!(first_panic.is_none(), "panicked on bytes={first_panic:02x?}");
    }

