    #[test]
    fn rename_locals_unifies_register_width_aliases() {
        // 32-bit-only code: eax and its family must collapse to one vN, and
        // no raw register name should survive.
        let out = rename_locals_v1_vn("eax = ecx;\neax = eax + edx;\nreturn eax;");
        assert!(!out.contains("eax"), "eax should be renamed: {out}");
        assert!(!out.contains("ecx"), "ecx should be renamed: {out}");
        // rax and eax are the same family -> same vN.
        let mixed = rename_locals_v1_vn("rax = 0x1;\neax = eax + 0x2;");
        assert!(!mixed.contains("rax") && !mixed.contains("eax"));
        assert!(mixed.contains("v1"));
    }

    #[test]
    fn dangling_goto_tailcall_and_label_conversion() {
        // `goto loc_X` with no label → tail call; `goto label_N` with no label
        // → return (structurer exit artifact); an in-body label is untouched.
        let code = "int f() {\n    if (c) {\n        goto loc_2000;\n    }\n    goto label_9;\n    goto label_3;\nlabel_3:\n    return x;\n}";
        let out = rewrite_dangling_goto_tailcall(code);
        assert!(out.contains("return sub_2000();"), "{out}");
        assert!(out.contains("return;"), "{out}");            // label_9 dangling
        assert!(out.contains("goto label_3;"), "{out}");       // label_3 exists → kept
        assert_eq!(out.matches("goto ").count(), 1, "only the resolvable goto remains: {out}");
    }

    #[test]
    fn tail_call_rewrites_all_dangling_gotos_not_just_last() {
        use std::collections::HashSet;
        let mut labels = HashSet::new();
        labels.insert(0x1002u64); // an intra-function label
        let mut stmts = vec![
            CfsStatement::Raw("goto loc_2000;".into()), // dangling → tail call
            CfsStatement::Raw("goto loc_1002;".into()), // intra → kept
            CfsStatement::Raw("goto loc_3000;".into()), // dangling → tail call
        ];
        rewrite_tail_call(&mut stmts, &labels);
        assert!(matches!(&stmts[0], CfsStatement::Return(Some(s)) if s == "sub_2000()"));
        assert!(matches!(&stmts[1], CfsStatement::Raw(s) if s == "goto loc_1002;"));
        assert!(matches!(&stmts[2], CfsStatement::Return(Some(s)) if s == "sub_3000()"));
    }

    #[test]
    fn indirect_jumpout_raised_to_tail_call_for_identifiers_and_memory() {
        // Questo test asseriva che la forma di MEMORIA restasse grezza, e
        // contraddiceva il codice di #6620, che la solleva (`plain || mem`).
        // Contraddizione interna a HEAD, non introdotta da una modifica: il
        // test codificava l'intento piu' stretto della prima stesura.
        //
        // Vince il codice, per due ragioni:
        // * semantica — `jmp [rax]` E' una chiamata di coda indiretta, e
        //   `return (*rax)();` ne e' la resa esatta: si salta alla funzione il
        //   cui indirizzo sta in memoria all'indirizzo in `rax`;
        // * misura — il ramo di memoria e' cio' che porta i `JUMPOUT` emessi
        //   da 18 a 0. Toglierlo li rifa' comparire.
        //
        // Resta grezzo `off_…`: la' l'operando e' un simbolo di DATO, e
        // chiamarlo produrrebbe una dichiarazione implicita.
        use std::collections::HashSet;
        let labels = HashSet::new();
        let mut stmts = vec![
            CfsStatement::Raw("JUMPOUT(v1);".into()),    // registro/locale → chiamata
            CfsStatement::Raw("JUMPOUT(*rax);".into()),  // memoria → chiamata indiretta
            CfsStatement::Raw("JUMPOUT(off_140003000);".into()), // simbolo di dato → intatto
        ];
        rewrite_tail_call(&mut stmts, &labels);
        assert!(matches!(&stmts[0], CfsStatement::Return(Some(s)) if s == "v1()"), "{stmts:?}");
        assert!(
            matches!(&stmts[1], CfsStatement::Return(Some(s)) if s == "(*rax)()"),
            "{stmts:?}"
        );
        assert!(matches!(&stmts[2], CfsStatement::Raw(s) if s == "JUMPOUT(off_140003000);"));
    }

    #[test]
    fn alu_flag_branch_fuses_condition_against_zero() {
        // `x = x & 1; (flags !=) goto` → `if (x != 0) goto`.
        let mut s = vec![
            CfsStatement::Assign { lhs: "x".into(), rhs: "x & 1".into() },
            CfsStatement::Branch("(flags !=) goto loc_10".into()),
        ];
        fuse_alu_flag_branch(&mut s);
        match &s[1] {
            CfsStatement::Branch(b) => assert_eq!(b, "(x != 0) goto loc_10"),
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn alu_flag_branch_sign_test_and_lea_guard() {
        // `y = y - z; (flags <) goto` → signed `y < 0`.
        let mut s = vec![
            CfsStatement::Assign { lhs: "y".into(), rhs: "y - z".into() },
            CfsStatement::Branch("(flags <) goto loc_20".into()),
        ];
        fuse_alu_flag_branch(&mut s);
        match &s[1] {
            CfsStatement::Branch(b) => assert_eq!(b, "(y < 0) goto loc_20"),
            other => panic!("{other:?}"),
        }
        // A `lea`-style non-self-referential add does NOT set flags → no fusion.
        let mut s2 = vec![
            CfsStatement::Assign { lhs: "p".into(), rhs: "base + 0x8".into() },
            CfsStatement::Branch("(flags !=) goto loc_30".into()),
        ];
        fuse_alu_flag_branch(&mut s2);
        match &s2[1] {
            CfsStatement::Branch(b) => assert_eq!(b, "(flags !=) goto loc_30"),
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn alu_flag_branch_fuses_setcc_after_alu() {
        // `a1 = a1 + a2; i = (flags <) ? 1 : 0` — a setcc (Assign form) following
        // an ALU op must fuse to the signed sign test `a1 < 0`.
        let mut s = vec![
            CfsStatement::Assign { lhs: "a1".into(), rhs: "a1 + a2".into() },
            CfsStatement::Assign { lhs: "i".into(), rhs: "(flags <) ? 1 : 0".into() },
        ];
        fuse_alu_flag_branch(&mut s);
        match &s[1] {
            CfsStatement::Assign { lhs, rhs } => {
                assert_eq!(lhs, "i");
                assert_eq!(rhs, "(a1 < 0) ? 1 : 0");
            }
            other => panic!("{other:?}"),
        }
        // Staleness guard still applies: if the ALU result is clobbered before
        // the setcc, no fusion.
        let mut s2 = vec![
            CfsStatement::Assign { lhs: "a1".into(), rhs: "a1 + a2".into() },
            CfsStatement::Assign { lhs: "a1".into(), rhs: "5".into() },
            CfsStatement::Assign { lhs: "i".into(), rhs: "(flags <) ? 1 : 0".into() },
        ];
        fuse_alu_flag_branch(&mut s2);
        match &s2[2] {
            CfsStatement::Assign { rhs, .. } => assert_eq!(rhs, "(flags <) ? 1 : 0"),
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn alu_flag_branch_names_overflow_check() {
        // `i = i * v6; (flags OF) goto` (jo after a checked multiply) keeps the
        // decorative `0` but names the overflowing operation in the comment.
        let mut s = vec![
            CfsStatement::Assign { lhs: "i".into(), rhs: "i * v6".into() },
            CfsStatement::Branch("(flags OF) goto loc_10".into()),
        ];
        fuse_alu_flag_branch(&mut s);
        match &s[1] {
            CfsStatement::Branch(b) => {
                assert_eq!(b, "(0 /* overflow check on (i * v6) */) goto loc_10")
            }
            other => panic!("{other:?}"),
        }
        // No recoverable ALU op before the overflow branch → left untouched for
        // the later neutralize pass.
        let mut s2 = vec![
            CfsStatement::Raw("sub_10();".into()),
            CfsStatement::Branch("(flags OF) goto loc_20".into()),
        ];
        fuse_alu_flag_branch(&mut s2);
        match &s2[1] {
            CfsStatement::Branch(b) => assert_eq!(b, "(flags OF) goto loc_20"),
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn alu_flag_branch_aborts_when_result_clobbered() {
        // `x = x & 1; x = z; (flags !=)` — x overwritten before the branch, so
        // the flags are stale and no fusion may happen.
        let mut s = vec![
            CfsStatement::Assign { lhs: "x".into(), rhs: "x & 1".into() },
            CfsStatement::Assign { lhs: "x".into(), rhs: "z".into() },
            CfsStatement::Branch("(flags !=) goto loc_10".into()),
        ];
        fuse_alu_flag_branch(&mut s);
        match &s[2] {
            CfsStatement::Branch(b) => assert_eq!(b, "(flags !=) goto loc_10"),
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn scalar_sse_compare_emits_cmp_placeholder() {
        // `ucomisd %xmm2, %xmm0` sets flags like `cmp xmm0, xmm2` — emit the
        // cmp placeholder so branch fusion/recovery reconstruct the relation.
        let s = lift_instruction_to_statement(&make_instr(0x1000, "ucomisd", "%xmm2, %xmm0"), None);
        assert!(matches!(s, Some(CfsStatement::Raw(ref r)) if r == "/* cmp xmm0 , xmm2 */"), "{s:?}");
        let s2 = lift_instruction_to_statement(&make_instr(0x1000, "comiss", "%xmm1, %xmm3"), None);
        assert!(matches!(s2, Some(CfsStatement::Raw(ref r)) if r == "/* cmp xmm3 , xmm1 */"), "{s2:?}");
    }

    #[test]
    fn rep_movs_becomes_memcpy() {
        // `ecx = 6; rep movsq (%rsi),(%rdi)` → `memcpy(rdi, rsi, 48)`.
        let mut s = vec![
            CfsStatement::Assign { lhs: "ecx".into(), rhs: "6".into() },
            CfsStatement::Raw("/* rep movsq (%rsi), (%rdi) */".into()),
        ];
        lift_rep_movs(&mut s);
        // The count assign is consumed (dropped), leaving just the memcpy.
        assert_eq!(s.len(), 1, "{s:?}");
        assert!(matches!(&s[0], CfsStatement::Raw(r) if r == "memcpy(rdi, rsi, 48);"), "{:?}", s[0]);
        // Byte copy with a variable count keeps the count as-is.
        let mut sb = vec![
            CfsStatement::Assign { lhs: "rcx".into(), rhs: "v5".into() },
            CfsStatement::Raw("/* rep movsb (%rsi), (%rdi) */".into()),
        ];
        lift_rep_movs(&mut sb);
        assert!(matches!(&sb[0], CfsStatement::Raw(r) if r == "memcpy(rdi, rsi, v5);"), "{:?}", sb[0]);
        // No count in the block → comment left untouched.
        let mut sc = vec![CfsStatement::Raw("/* rep movsq (%rsi), (%rdi) */".into())];
        lift_rep_movs(&mut sc);
        assert!(matches!(&sc[0], CfsStatement::Raw(r) if r.starts_with("/* rep movsq")), "{:?}", sc[0]);
    }

    #[test]
    fn rep_stos_becomes_memset_only_when_zero_fill() {
        // `rax = 0; ecx = 0x96; rep stos %rax,(%rdi)` → `memset(rdi, 0, 1200)`.
        let mut s = vec![
            CfsStatement::Assign { lhs: "rax".into(), rhs: "0".into() },
            CfsStatement::Assign { lhs: "ecx".into(), rhs: "0x96".into() },
            CfsStatement::Raw("/* rep stos %rax, (%rdi) */".into()),
        ];
        lift_rep_movs(&mut s);
        assert!(s.iter().any(|st| matches!(st, CfsStatement::Raw(r) if r == "memset(rdi, 0, 1200);")), "{s:?}");
        // Non-zero fill (pattern store) is NOT memset — comment left as-is.
        let mut nz = vec![
            CfsStatement::Assign { lhs: "rax".into(), rhs: "7".into() },
            CfsStatement::Assign { lhs: "ecx".into(), rhs: "4".into() },
            CfsStatement::Raw("/* rep stos %rax, (%rdi) */".into()),
        ];
        lift_rep_movs(&mut nz);
        assert!(nz.iter().any(|st| matches!(st, CfsStatement::Raw(r) if r.starts_with("/* rep stos"))), "{nz:?}");
    }

    #[test]
    fn segment_relative_access_becomes_tls_intrinsic() {
        // `mov %gs:(%eax), %rax` source operand → `__readgsqword(eax)`, not the
        // invalid `*(eax + %gs:)` leak. Register-offset, immediate, and
        // disp+base forms all covered; fs maps to the dword intrinsic.
        assert_eq!(clean_operand("%gs:(%eax)"), "__readgsqword(eax)");
        assert_eq!(clean_operand("%gs:0x30"), "__readgsqword(0x30)");
        assert_eq!(clean_operand("%gs:0x30(%rax)"), "__readgsqword(rax + 0x30)");
        assert_eq!(clean_operand("%fs:0x18"), "__readfsdword(0x18)");
        // No segment prefix → untouched behaviour.
        assert_eq!(clean_operand("%rax"), "rax");
    }

    #[test]
    fn base_less_sib_addressing_has_no_dangling_leading_operator() {
        // AT&T SIB addressing with an OMITTED base register (scale-index-only,
        // e.g. `4(,%rax,8)`) left `base` empty, and the old code unconditionally
        // prefixed the index/disp terms with " + " — producing a dangling
        // `*( + rax*8 + 4)` (invalid C: unary `*` on an expression starting with
        // a binary `+`). The base-less case must drop the leading operator.
        assert_eq!(clean_operand("4(,%rax,8)"), "*(rax*8 + 4)");
        assert_eq!(clean_operand("(,%rax,8)"), "*(rax*8)");
        assert_eq!(clean_operand("4(,%rax,1)"), "*(rax + 4)");
        // A normal base+index+disp form is unaffected.
        assert_eq!(clean_operand("4(%rcx,%rax,8)"), "*(rcx + rax*8 + 4)");
        // Base-only (no index) is unaffected (pre-existing behaviour).
        assert_eq!(clean_operand("(%rax)"), "*rax");
    }

    #[test]
    fn att_scalar_movs_lift_to_assignments() {
        let lifted = |m: &str, o: &str| -> Option<CfsStatement> {
            match lift_data_move_stmt(m, o) {
                InstrLift::Handled(s) => s,
                InstrLift::Skip => None,
            }
        };
        // AT&T immediate load, order is `src, dst`.
        match lifted("movabs", "$0x10, %a2") {
            Some(CfsStatement::Assign { lhs, rhs }) => {
                assert_eq!(lhs, "a2");
                assert_eq!(rhs, "0x10");
            }
            other => panic!("movabs: {other:?}"),
        }
        // Zero-extend byte load from a based memory operand.
        match lifted("movzbl", "40(%ptr), %v2") {
            Some(CfsStatement::Assign { lhs, rhs }) => {
                assert_eq!(lhs, "v2");
                assert_eq!(rhs, "*(ptr + 40)");
            }
            other => panic!("movzbl: {other:?}"),
        }
        // Division sign-fill setup is silent — Intel and AT&T spellings.
        for m in ["cqo", "cqto", "cltd", "cdq", "cwd"] {
            assert!(matches!(lift_data_move_stmt(m, ""), InstrLift::Handled(None)), "{m}");
        }
    }

    /// D20: an accumulator sign-extension must materialise a CAST. Dropping it
    /// let a 32-bit signed product be re-read as a 64-bit value whose high half
    /// was garbage, so results came out off by an exact multiple of 2^32.
    #[test]
    fn accumulator_sign_extension_materialises_a_cast() {
        let lift = |m: &str| match lift_data_move_stmt(m, "") {
            InstrLift::Handled(Some(CfsStatement::Assign { lhs, rhs })) => (lhs, rhs),
            _ => panic!("{m}"),
        };
        // eax -> rax (both spellings).
        for m in ["cltq", "cdqe"] {
            let (lhs, rhs) = lift(m);
            assert_eq!(lhs, "rax", "{m}");
            assert_eq!(rhs, "(int)eax", "{m}");
        }
        // ax -> eax and al -> ax extend the narrower halves.
        for (m, d, s, ty) in [
            ("cwtl", "eax", "ax", "short"),
            ("cwde", "eax", "ax", "short"),
            ("cbtw", "ax", "al", "char"),
            ("cbw", "ax", "al", "char"),
        ] {
            let (lhs, rhs) = lift(m);
            assert_eq!(lhs, d, "{m}");
            assert_eq!(rhs, format!("({ty}){s}"), "{m}");
        }
        // A cast, never a mask: masking would clear the sign fill instead of
        // replicating it, which is why D13's zero-extend helper is not reused.
        assert!(!lift("cltq").1.contains('&'));
    }

    /// D20 end-to-end shape: `imul $-10,%eax; cltq` must not leave the negative
    /// 32-bit product widened as the unsigned constant 0xFFFFFFF6.
    #[test]
    fn signed_32bit_product_is_sign_extended_before_64bit_accumulation() {
        let InstrLift::Handled(Some(CfsStatement::Assign { lhs, rhs })) =
            lift_alu_stmt("imul", "$0xFFFFFFF6, %eax")
        else {
            panic!("imul not lifted");
        };
        assert_eq!(lhs, "eax");
        // The multiply itself stays 32-bit-shaped …
        assert!(rhs.contains('*'), "{rhs}");
        // … and the following cltq is what re-narrows and sign-extends it.
        let (d, ext) = match lift_data_move_stmt("cltq", "") {
            InstrLift::Handled(Some(CfsStatement::Assign { lhs, rhs })) => (lhs, rhs),
            _ => panic!("cltq"),
        };
        assert_eq!(d, "rax");
        assert_eq!(ext, "(int)eax");
    }

    /// A genuinely 64-bit operand must be left untouched: `cqo` (rax -> rdx:rax)
    /// widens nothing readable and must still lift to no statement.
    #[test]
    fn sixty_four_bit_accumulator_is_not_re_extended() {
        assert!(matches!(lift_data_move_stmt("cqo", ""), InstrLift::Handled(None)));
        assert!(matches!(lift_data_move_stmt("cqto", ""), InstrLift::Handled(None)));
    }

    #[test]
    fn subregister_write_materialises_its_truncation() {
        // D13: `uint16_t u = ...; u = (uint16_t)(u >> 5);` lowers to
        // `shr $0x5,%cx` + `movzwl %cx,%eax`. Both operands are sub-registers of
        // families that lower to a FULL-WIDTH local, so the narrowing the
        // hardware performs must be materialised or the value comes out
        // untruncated (and the shift signed).
        let alu = |m: &str, o: &str| -> Option<CfsStatement> {
            match lift_alu_stmt(m, o) {
                InstrLift::Handled(s) => s,
                InstrLift::Skip => None,
            }
        };
        let mov = |m: &str, o: &str| -> Option<CfsStatement> {
            match lift_data_move_stmt(m, o) {
                InstrLift::Handled(s) => s,
                InstrLift::Skip => None,
            }
        };

        // (a) 16-bit shift destination: masked, and LOGICAL (`(cx & 0xFFFF) >> 5`,
        // never a bare signed `cx >> 5`).
        match alu("shr", "$0x5, %cx") {
            Some(CfsStatement::Assign { lhs, rhs }) => {
                assert_eq!(lhs, "cx");
                assert_eq!(rhs, "(cx & ~0xFFFF) | ((cx & 0xFFFF) >> 0x5)");
            }
            other => panic!("shr cx: {other:?}"),
        }
        // (b) 8-bit shift destination masks to 0xFF; left shift also masks the
        // RESULT so bits cannot climb out of the narrow field.
        match alu("shl", "$0x3, %dl") {
            Some(CfsStatement::Assign { rhs, .. }) => {
                assert_eq!(rhs, "(dl & ~0xFF) | (((dl & 0xFF) << 0x3) & 0xFF)");
            }
            other => panic!("shl dl: {other:?}"),
        }
        // (c) GUARD RAIL: a FULL-WIDTH destination is never masked. 32- and
        // 64-bit shift dsts keep the plain compound form.
        for (d, expect) in [("%ecx", "ecx >> 0x5"), ("%rcx", "rcx >> 0x5")] {
            match alu("shr", &format!("$0x5, {d}")) {
                Some(CfsStatement::Assign { rhs, .. }) => assert_eq!(rhs, expect, "{d}"),
                other => panic!("shr {d}: {other:?}"),
            }
        }
        // (d) Non-shift ALU ops on a narrow dst are untouched by this gate.
        match alu("add", "$0x1, %cx") {
            Some(CfsStatement::Assign { rhs, .. }) => assert_eq!(rhs, "cx + 0x1"),
            other => panic!("add cx: {other:?}"),
        }

        // (e) Zero-extend from a narrow register SOURCE materialises the mask —
        // this is the widened USE that made the dropped truncation observable.
        match mov("movzwl", "%cx, %eax") {
            Some(CfsStatement::Assign { lhs, rhs }) => {
                assert_eq!(lhs, "eax");
                assert_eq!(rhs, "cx & 0xFFFF");
            }
            other => panic!("movzwl cx: {other:?}"),
        }
        match mov("movzbl", "%dl, %eax") {
            Some(CfsStatement::Assign { rhs, .. }) => assert_eq!(rhs, "dl & 0xFF"),
            other => panic!("movzbl dl: {other:?}"),
        }
        // (f) GUARD RAIL: full-width and non-register sources are unchanged, and
        // SIGN-extends are left to the cast path rather than masked.
        match mov("movzwl", "40(%ptr), %v2") {
            Some(CfsStatement::Assign { rhs, .. }) => assert_eq!(rhs, "*(ptr + 40)"),
            other => panic!("movzwl mem: {other:?}"),
        }
        match mov("movswl", "%cx, %eax") {
            Some(CfsStatement::Assign { rhs, .. }) => assert_eq!(rhs, "cx"),
            other => panic!("movswl: {other:?}"),
        }
        match mov("mov", "%ecx, %eax") {
            Some(CfsStatement::Assign { rhs, .. }) => assert_eq!(rhs, "ecx"),
            other => panic!("mov: {other:?}"),
        }
    }

    #[test]
    fn infer_call_arguments_binds_args_after_captured_call() {
        // __report_error shape: a captured call (`rax = f(2);`) precedes the
        // arg setup of the NEXT call (`lea rdx, str; mov rcx, rax; call g`).
        // g must get both args (witness: sample6 emitted `fprintf();`).
        let mut stmts = vec![
            CfsStatement::Raw("rax = __acrt_iob_func(2);".into()),
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "\"msg\"".into() },
            CfsStatement::Assign { lhs: "rcx".into(), rhs: "rax".into() },
            CfsStatement::Raw("sub_1400028B0();".into()),
        ];
        infer_call_arguments(&mut stmts);
        let call = stmts
            .iter()
            .find_map(|s| match s {
                CfsStatement::Raw(r) if r.contains("sub_1400028B0") => Some(r.clone()),
                _ => None,
            })
            .expect("call survives");
        assert!(!call.contains("sub_1400028B0();"), "args lost: {stmts:?}");

        // Real pipeline order: propagate_register_copies runs BEFORE infer.
        // The arg-reg copies (`rcx = rax`, `rdx = &off`) must not be dropped
        // as dead just because the following call's use of them is implicit.
        let mut pipe = vec![
            CfsStatement::Raw("sub_140002830();".into()),
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "&off_140003FE0".into() },
            CfsStatement::Assign { lhs: "rcx".into(), rhs: "rax".into() },
            CfsStatement::Raw("sub_1400028B0();".into()),
        ];
        propagate_register_copies(&mut pipe);
        infer_call_arguments(&mut pipe);
        let call2 = pipe
            .iter()
            .find_map(|s| match s {
                CfsStatement::Raw(r) if r.contains("sub_1400028B0") => Some(r.clone()),
                _ => None,
            })
            .expect("call survives");
        assert!(!call2.contains("sub_1400028B0();"), "args lost after propagate: {pipe:?}");
    }

    #[test]
    fn bare_return_fill_tracks_compound_assignments() {
        // sample6 classify case 7: `v4 = a2; v4 <<= a3; return;` filled with
        // a STALE `result` from an earlier switch case because `v4 <<= a3`
        // (compound assign) was not recognised as assigning v4. Comparisons
        // must still not count as assignments.
        let code = "__int64 __fastcall f(int a2, int a3) {\n    int v4;\n    result = a2;\n    v4 <<= a3;\n    return;\n}";
        let out = fix_return_statement_consistency(code);
        assert!(out.contains("return v4;"), "{out}");
        let cmp = "__int64 __fastcall f(int a2) {\n    v1 = a2;\n    a2 == v9;\n    return;\n}";
        let cout = fix_return_statement_consistency(cmp);
        assert!(cout.contains("return v1;"), "{cout}");
    }

    #[test]
    fn bare_return_fill_uses_last_assignment_of_multi_stmt_line() {
        // A div lift line packs several `;`-separated assignments into one
        // Raw line. The bare-`return;` filler must take the LAST assignment
        // of that line (the quotient, emitted last on purpose), not the
        // first (`__rdx_rax = …`, the dividend capture) — sample6 classify
        // case 3 returned the dividend instead of the quotient.
        let code = "__int64 __fastcall f(__int64 a1) {\n    __int64 v6;\n    __rdx_rax = v6; v2 = __rdx_rax % a1; v6 = __rdx_rax / a1; /* signed */;\n    return;\n}";
        let out = fix_return_statement_consistency(code);
        assert!(out.contains("return v6;"), "{out}");
    }

    #[test]
    fn div_lift_captures_dividend() {
        // The 1-operand divide reads the implicit rdx:rax dividend. The lift
        // must DEFINE `__rdx_rax` from rax before the divide — otherwise every
        // division reads an uninitialised pseudo-variable (sample6 `classify`
        // case 3 emitted `v7 = __rdx_rax / a3;` with `__rdx_rax` never
        // assigned). In compiler output rdx is always the sign/zero extension
        // of rax at this point, so `__rdx_rax = rax` is the dividend.
        for m in ["idiv", "div", "idivl", "divq"] {
            let InstrLift::Handled(Some(CfsStatement::Raw(s))) = lift_alu_stmt(m, "%ecx") else {
                panic!("{m} should lift to a Raw statement");
            };
            assert!(s.contains("__rdx_rax = rax;"), "{m}: {s}");
            assert!(
                s.find("__rdx_rax = rax;").unwrap() < s.find(" / ").unwrap(),
                "capture must precede first use: {m}: {s}"
            );
        }
    }

    #[test]
    fn cmpxchg_lift_captures_both_effects_for_register_dst() {
        // `cmpxchg %ecx, %edx` — REGISTER destination, the case where BOTH
        // real effects (dst write on success, accumulator write on failure)
        // are safe to emit: register locals stay scalar in this emitter's
        // convention, so `edx` can never later get promoted to a struct
        // type the way a memory dereference can (see the memory-dst test
        // below for that hazard). Both effects must be keyed off the SAME
        // captured pre-value.
        let InstrLift::Handled(Some(CfsStatement::Raw(s))) =
            lift_alu_stmt("cmpxchg", "%ecx, %edx")
        else {
            panic!("cmpxchg should lift to a Raw statement");
        };
        assert!(s.contains("__cmpxchg_old = "), "{s}");
        let capture_pos = s.find("__cmpxchg_old = ").unwrap();
        let uses: Vec<_> = s.match_indices("__cmpxchg_old").map(|(i, _)| i).collect();
        assert!(uses.len() >= 3, "capture + 2 real uses expected: {s}"); // decl + 2 reads
        assert!(uses.iter().skip(1).all(|&i| i > capture_pos), "{s}");
        // An `if`/`else` (not a `?:` ternary) is required: a ternary needs
        // its two branches to share one type, which breaks once a MEMORY
        // dst gets promoted to a struct-typed dereference by a later pass
        // while `src` stays a plain scalar/pointer (real corpus regression
        // this class of test guards against — see the fix's own comment).
        assert!(s.contains("if (eax == __cmpxchg_old)"), "{s}");
        assert!(s.contains("{ eax = __cmpxchg_old; }"), "{s}");
        assert!(s.contains("{ edx = ecx; }"), "{s}");
        assert!(!s.contains('?'), "must not use a ternary: {s}");
    }

    #[test]
    fn cmpxchg_lift_memory_dst_keeps_store_via_scalar_pinned_cast() {
        // `cmpxchg %ecx, (%rax)` — MEMORY destination. A later type-recovery
        // pass can promote `*rax` into a struct-typed access; the historical
        // accumulator-only fallback avoided the resulting "incompatible
        // types" error by DROPPING the atomic store entirely (silent wrong
        // code). The current form keeps BOTH effects but routes every memory
        // access through a `*(__intN *)addr` cast, which stays scalar no
        // matter what type the pointee is later promoted to — fixing the
        // sample4_go regression class without losing the write.
        let InstrLift::Handled(Some(CfsStatement::Raw(s))) =
            lift_alu_stmt("cmpxchg", "%ecx, (%rax)")
        else {
            panic!("cmpxchg should lift to a Raw statement");
        };
        assert!(s.contains("__cmpxchg_old = *(__int32 *)rax"), "{s}");
        assert!(s.contains("if (eax == __cmpxchg_old)"), "{s}");
        // The store survives, scalar-pinned on both the address and the src.
        assert!(s.contains("*(__int32 *)rax = (__int32)ecx"), "{s}");
        assert!(s.contains("else { eax = __cmpxchg_old; }"), "{s}");
        // No unpinned deref remains for struct promotion to break.
        assert!(!s.contains("*rax"), "every access must go through the cast: {s}");
    }

    #[test]
    fn cmpxchg_lift_picks_accumulator_width_from_operand() {
        // 8-bit form: `al`, not `eax`/`rax`.
        let InstrLift::Handled(Some(CfsStatement::Raw(s8))) =
            lift_alu_stmt("cmpxchg", "%cl, (%rax)")
        else {
            panic!("cmpxchg (8-bit) should lift to a Raw statement");
        };
        assert!(s8.contains("al == __cmpxchg_old"), "{s8}");
        // 64-bit form via the `q` mnemonic suffix.
        let InstrLift::Handled(Some(CfsStatement::Raw(s64))) =
            lift_alu_stmt("cmpxchgq", "%rcx, (%rax)")
        else {
            panic!("cmpxchgq should lift to a Raw statement");
        };
        assert!(s64.contains("rax == __cmpxchg_old"), "{s64}");
    }

    /// Test helper: unwrap `lift_sse_stmt` to the produced statement.
    fn lifted_sse(m: &str, o: &str) -> Option<CfsStatement> {
        match lift_sse_stmt(m, o) {
            InstrLift::Handled(s) => s,
            InstrLift::Skip => None,
        }
    }

    #[track_caller]
    fn assert_sse_assign(m: &str, o: &str, want_lhs: &str, want_rhs: &str) {
        match lifted_sse(m, o) {
            Some(CfsStatement::Assign { lhs, rhs }) => {
                assert_eq!(lhs, want_lhs, "{m} {o}");
                assert_eq!(rhs, want_rhs, "{m} {o}");
            }
            other => panic!("{m} {o}: {other:?}"),
        }
    }

    #[test]
    fn sse_imm8_shifts_lift_destructively_register_count_stays_comment() {
        // The horizontal-add idiom depends on this: dropping `psrldq $8` to a
        // comment silently turned lo+hi into lo+lo (sample1 accumulate).
        assert_sse_assign("psrldq", "$8, %xmm1", "xmm1", "_mm_srli_si128(xmm1, 8)");
        assert_sse_assign("pslldq", "$4, %xmm0", "xmm0", "_mm_slli_si128(xmm0, 4)");
        assert_sse_assign("psrlq", "$32, %xmm2", "xmm2", "_mm_srli_epi64(xmm2, 32)");
        assert_sse_assign("psrad", "$16, %xmm3", "xmm3", "_mm_srai_epi32(xmm3, 16)");
        // Register-count form is the non-imm intrinsic family (sse_shift_intrinsics).
        assert_sse_assign("psrlq", "%xmm2, %xmm1", "xmm1", "_mm_srl_epi64(xmm1, xmm2)");
    }

    #[test]
    fn sse_moves_lift_to_assignments() {
        // AT&T: a 128-bit memory LOAD → typed load intrinsic (unaligned movups),
        // the pointer de-referenced back from `*rcx` to `rcx`.
        assert_sse_assign("movups", "(%rcx), %xmm0", "xmm0", "_mm_loadu_si128((__m128i *)rcx)");
        // A 128-bit STORE → typed store intrinsic (Raw). The compound address is
        // PARENTHESISED so the cast doesn't bind before the `+`.
        match lifted_sse("movups", "%xmm0, 0x10(%rcx)") {
            Some(CfsStatement::Raw(r)) => {
                assert_eq!(r, "_mm_storeu_si128((__m128i *)(rcx + 0x10), xmm0);");
            }
            other => panic!("store: {other:?}"),
        }
        // Register↔register move is unchanged.
        assert_sse_assign("movdqu", "%xmm1, %xmm2", "xmm2", "xmm1");
        // Intel size-prefixed aligned load → `_mm_load_si128`.
        assert_sse_assign("movdqa", "xmm1, xmmword ptr [rax]", "xmm1", "_mm_load_si128((__m128i *)rax)");
        // A stack-slot load keeps `*(rsp+K)` visible for naming (→ `&var_K`).
        assert_sse_assign("movdqa", "xmm0, xmmword ptr [rsp + 0x20]", "xmm0", "_mm_load_si128((__m128i *)&*(rsp + 0x20))");
        let named = name_stack_slots("void f() {\n    xmm0 = _mm_load_si128((__m128i *)&*(rsp + 0x20));\n}");
        assert!(named.contains("(__m128i *)&var_20") && !named.contains("rsp"), "slot named: {named}");
        // A rip-resolved global data symbol is a memory load, not `xmm = off_X`.
        assert_sse_assign("movdqa", "xmm0, off_140116140", "xmm0", "_mm_load_si128((__m128i *)&off_140116140)");
        // `movsd` with xmm operands is the SSE scalar-lane move …
        assert_sse_assign("movsd", "%xmm1, %xmm0", "xmm0", "xmm1");
        // … but the bare string move is not ours.
        assert!(matches!(lift_sse_stmt("movsd", ""), InstrLift::Skip));
    }

    #[track_caller]
    fn assert_ctrl_raw(m: &str, o: &str, want: &str) {
        match lift_ctrl_flow_stmt(m, o) {
            InstrLift::Handled(Some(CfsStatement::Raw(r))) => assert_eq!(r, want, "{m} {o}"),
            other => panic!("{m} {o}: {other:?}", other = match other {
                InstrLift::Handled(s) => format!("Handled({s:?})"),
                InstrLift::Skip => "Skip".to_string(),
            }),
        }
    }

    #[test]
    fn call_to_decimal_absolute_address_is_symbolised() {
        // A DECIMAL absolute call target leaked through as a bare numeric
        // literal call — `5368764544();` instead of a symbol.
        // `parse_hex_target` only accepts `0x…`/`…h`, so a decimal operand fell
        // into the INDIRECT branch, where `clean_operand("5368764544")` is
        // all-alphanumeric and was passed through unchanged. Found in the
        // user's live MCP audit of cargo-zyphora.exe (does NOT reproduce in
        // the 12-binary corpus). 5368764544 == 0x14000D880.
        assert_ctrl_raw("call", "5368764544", "sub_14000D880();");
        // The deref form is an indirect call THROUGH a pointer stored at that
        // data address → the data symbol, called through. 5369787440 ==
        // 0x140107430 — which is exactly the `off_140107430` (an IAT slot the
        // audit expects to become `HeapAlloc`) seen in the live audit.
        assert_ctrl_raw("call", "*5369787440", "(*off_140107430)();");
        // Hex forms keep working exactly as before.
        assert_ctrl_raw("call", "0x1400118C0", "sub_1400118C0();");
        assert_ctrl_raw("call", "1400118C0h", "sub_1400118C0();");
        // Register/memory indirect calls are untouched.
        assert_ctrl_raw("call", "*%rax", "rax();");
        // A SMALL decimal is not an address — it must NOT be symbolised
        // (guards against turning a genuine tiny constant into a fake symbol).
        assert_ctrl_raw("call", "8", "8();");
    }

    #[test]
    fn il_passes_opt_in_gate_rejects_falsy_values() {
        // Unset → OFF (default pipeline stays byte-identical).
        assert!(!il_passes_opt_in(None));
        // Set-but-falsy → OFF. A bare `env::var().is_ok()` test would turn the
        // pass ON for `RUSTRE_IL_PASSES=0` — the bug ssa_split documents.
        for v in ["0", "", "false", "no", "off", " OFF ", "False"] {
            assert!(!il_passes_opt_in(Some(v)), "{v:?} must be OFF");
        }
        // Any other set value → ON.
        for v in ["1", "true", "yes", "on"] {
            assert!(il_passes_opt_in(Some(v)), "{v:?} must be ON");
        }
    }

    #[test]
    fn hlil_opt_in_gate_rejects_falsy_values() {
        // Unset → OFF: path A (`pseudo_code`) stays byte-identical (REGOLA #28).
        assert!(!hlil_opt_in(None));
        // Set-but-falsy → OFF. `RUSTRE_HLIL=0` MUST read as off; the
        // `env::var().is_ok()` form would read it as on, which is exactly how
        // a control group was once believed spent while it was running.
        for v in ["0", "", "false", "no", "off", " OFF ", "False"] {
            assert!(!hlil_opt_in(Some(v)), "{v:?} must be OFF");
        }
        for v in ["1", "true", "yes", "on"] {
            assert!(hlil_opt_in(Some(v)), "{v:?} must be ON");
        }
    }

    #[test]
    fn path_a_is_degenerate_only_for_empty_or_jumpout_bodies() {
        // Blank text.
        assert!(path_a_is_degenerate(""));
        assert!(path_a_is_degenerate("   \n\t\n"));
        // Body with no statements at all — signature + braces only.
        assert!(path_a_is_degenerate("__int64 f(__int64 a1)\n{\n}\n"));
        assert!(path_a_is_degenerate("__int64 f(__int64 a1) {\n}\n"));
        // Comments and lone braces are not statements.
        assert!(path_a_is_degenerate(
            "__int64 f()\n{\n  // nothing was recovered\n}\n"
        ));
        // Unreconstructed control flow, however much text surrounds it.
        assert!(path_a_is_degenerate(
            "__int64 f(__int64 a1)\n{\n  v1 = a1 + 1;\n  JUMPOUT(0x140001000);\n}\n"
        ));
        // A real body is NOT degenerate — the predicate must never green-light
        // throwing away a reconstruction.
        assert!(!path_a_is_degenerate(
            "__int64 f(__int64 a1)\n{\n  return a1 + 1;\n}\n"
        ));
        assert!(!path_a_is_degenerate(
            "void f()\n{\n  if ( a1 )\n  {\n    g();\n  }\n}\n"
        ));
    }

    #[test]
    fn bucket_by_source_opt_in_gate_rejects_falsy_values() {
        assert!(!bucket_by_source_opt_in(None));
        for v in ["0", "", "false", "no", "off", " OFF ", "False"] {
            assert!(!bucket_by_source_opt_in(Some(v)), "{v:?} must be OFF");
        }
        for v in ["1", "true", "yes", "on"] {
            assert!(bucket_by_source_opt_in(Some(v)), "{v:?} must be ON");
        }
    }

    #[test]
    fn build_llil_function_is_reachable_without_the_il_passes_gate() {
        // The point of extracting `build_llil_function` out of
        // `optimize_lifted_llil`: an `LlilFunction` used to exist ONLY inside
        // the `RUSTRE_IL_PASSES` opt-in branch, so with the gate off (the
        // default) nothing in `rustre-il-llil`'s analysis surface could be
        // reached. This calls it directly, with no env var set, and runs the
        // crate's own validator over the result — the same code path
        // `IlAnalysisPass::run` now takes on every function.
        use rustre_il_llil::{LlilAnnotatedInstr, LlilExpr, LlilInstruction, LlilRegister, Size};
        let ai = |addr: u64, instr: LlilInstruction| LlilAnnotatedInstr {
            address: rustre_core::address::Address::new(addr),
            size: 4,
            length: 4,
            instr,
        };
        let set = |addr: u64, reg: &str| {
            ai(
                addr,
                LlilInstruction::SetReg {
                    dest: LlilRegister::Concrete(reg.to_string()),
                    size: Size::QWord,
                    value: LlilExpr::Const { value: 1, size: Size::QWord },
                },
            )
        };
        // Two blocks: a conditional jump splits the stream at 0x1008.
        let lifted = vec![
            (
                0x1000,
                vec![
                    set(0x1000, "rax"),
                    ai(
                        0x1000,
                        LlilInstruction::CondJump {
                            cond: LlilExpr::Const { value: 1, size: Size::QWord },
                            true_dest: rustre_core::address::Address::new(0x1008),
                            false_dest: rustre_core::address::Address::new(0x1008),
                        },
                    ),
                ],
            ),
            (0x1008, vec![set(0x1008, "rbx"), ai(0x1008, LlilInstruction::Ret)]),
        ];
        let func = build_llil_function(&lifted, 0x1000).expect("non-empty stream builds a function");
        assert_eq!(func.entry.0, 0x1000);
        assert_eq!(func.blocks.len(), 2, "the branch target must start a new block: {func:?}");
        // The validator is real code from `rustre-il-llil`, not a type import:
        // it must run and produce a count (0 here — the blocks carry no
        // unresolved successors).
        let errs = rustre_il_llil::llil_builder::LlilValidator::validate(&func);
        assert!(errs.is_empty(), "unexpected validation errors: {errs:?}");
        assert!(rustre_il_llil::llil_builder::LlilValidator::error_counts(&func).is_empty());
        // Empty stream ⇒ None (the case `optimize_lifted_llil` short-circuits).
        assert!(build_llil_function(&[], 0x1000).is_none());
    }

    #[test]
    fn optimize_lifted_llil_preserves_address_order_and_regroups() {
        use rustre_il_llil::{LlilAnnotatedInstr, LlilExpr, LlilInstruction, LlilRegister, Size};
        let ins = |addr: u64, reg: &str, val: u64| LlilAnnotatedInstr {
            address: rustre_core::address::Address::new(addr),
            size: 4,
            length: 4,
            instr: LlilInstruction::SetReg {
                dest: LlilRegister::Concrete(reg.to_string()),
                size: Size::QWord,
                value: LlilExpr::Const { value: val, size: Size::QWord },
            },
        };
        // DESCENDING addresses: a BTreeMap regroup would silently re-sort these
        // into ascending order and corrupt the instruction stream.
        let lifted = vec![
            (0x2000, vec![ins(0x2000, "rax", 1), ins(0x2000, "rbx", 2)]),
            (0x1000, vec![ins(0x1000, "rcx", 3)]),
        ];
        let (out, stats, before, after) = optimize_lifted_llil(&lifted, 0x2000);
        let addrs: Vec<u64> = out.iter().map(|(a, _)| *a).collect();
        assert_eq!(addrs, vec![0x2000, 0x1000], "address ORDER must be preserved");
        // Ops sharing one source address stay grouped under it.
        assert_eq!(out[0].1.len(), 2, "{out:?}");
        assert!(stats.starts_with("3->"), "stats should report the op count: {stats}");
        // The numeric counts exposed for measuring scripts must agree with the
        // string (which is what a script would otherwise have to parse).
        assert_eq!(before, 3, "before count");
        assert_eq!(after, out.iter().map(|(_, v)| v.len()).sum::<usize>(), "after count");
        // Empty input is a no-op with no stats.
        let (empty, s, b0, a0) = optimize_lifted_llil(&[], 0x1000);
        assert!(empty.is_empty() && s.is_empty());
        assert_eq!((b0, a0), (0, 0));
    }

    #[test]
    fn optimize_lifted_llil_actually_runs_passes_on_blocks() {
        // Every pass in PassManager::standard() iterates `func.blocks` —
        // feeding only the flat `instructions` field makes the whole pipeline
        // a provable no-op (see rustre-il-passes/tests/flat_stream_wiring.rs).
        // This test pins the wiring: a Nop in the lifted stream MUST be
        // eliminated by optimize_lifted_llil.
        use rustre_il_llil::{LlilAnnotatedInstr, LlilExpr, LlilInstruction, LlilRegister, Size};
        let ai = |addr: u64, instr: LlilInstruction| LlilAnnotatedInstr {
            address: rustre_core::address::Address::new(addr),
            size: 4,
            length: 4,
            instr,
        };
        let lifted = vec![
            (0x1000, vec![ai(0x1000, LlilInstruction::Nop)]),
            (
                0x1004,
                vec![ai(
                    0x1004,
                    LlilInstruction::SetReg {
                        dest: LlilRegister::Concrete("rax".to_string()),
                        size: Size::QWord,
                        value: LlilExpr::Const { value: 1, size: Size::QWord },
                    },
                )],
            ),
            (0x1008, vec![ai(0x1008, LlilInstruction::Ret)]),
        ];
        let (out, stats, _before, _after) = optimize_lifted_llil(&lifted, 0x1000);
        let flat: Vec<&LlilAnnotatedInstr> = out.iter().flat_map(|(_, v)| v.iter()).collect();
        assert!(
            !flat.iter().any(|i| matches!(i.instr, LlilInstruction::Nop)),
            "NopEliminationPass must actually run over the lifted stream: {out:?}"
        );
        assert!(stats.contains("changed=true"), "pipeline must report a change: {stats}");
        // The return-value computation must survive (bare Ret seeds ABI
        // return registers live in DCE) — deleting it would be a fidelity
        // regression, not an optimization.
        assert!(
            flat.iter().any(|i| matches!(i.instr, LlilInstruction::SetReg { .. })),
            "rax = 1 feeding a bare Ret must NOT be DCE'd: {out:?}"
        );
        // Internal synthetic fall-through jumps (size == 0 markers used to
        // give LlilCfg real fall-through edges) must never leak to callers.
        assert!(flat.iter().all(|i| i.size != 0), "synthetic jump leaked: {out:?}");
        // The Nop's address group drops out entirely; order is preserved.
        let addrs: Vec<u64> = out.iter().map(|(a, _)| *a).collect();
        assert_eq!(addrs, vec![0x1004, 0x1008]);
    }

    /// REGOLA #19: il gruppo di controllo va VERIFICATO spento, non assunto.
    ///
    /// `RUSTRE_IL_PASSES_DCE` e' letto con `matches!(…, Ok("1") | Ok("true"))`,
    /// cioe' opt-in stretto: `VAR=` (stringa vuota) NON lo accende. Questo test
    /// blinda il default OFF del sotto-gate PRIMA che qualcuno misuri la DCE, e
    /// lo fa con un controllo positivo nello stesso corpo: prima toglie la
    /// variabile dall'ambiente (rimozione ESPLICITA, mai `VAR=`) e pretende che
    /// la definizione morta SOPRAVVIVA, poi la mette a "1" e pretende che
    /// SPARISCA. Senza il secondo mezzo, un "sopravvive" non distinguerebbe
    /// «gate spento» da «pass mai cablato», che e' esattamente il falso
    /// negativo gia' costato una volta al percorso B.
    #[test]
    fn optimize_lifted_llil_dce_gate_is_off_by_default() {
        use rustre_il_llil::{LlilAnnotatedInstr, LlilExpr, LlilInstruction, LlilRegister, Size};
        let ai = |addr: u64, instr: LlilInstruction| LlilAnnotatedInstr {
            address: rustre_core::address::Address::new(addr),
            size: 4,
            length: 4,
            instr,
        };
        // `r12` di proposito, NON `rax`: un bare `Ret` semina i registri di
        // ritorno dell'ABI (rax/eax/…/xmm0) come vivi, quindi una definizione
        // di `rax` sopravvivrebbe alla DCE e il test non misurerebbe nulla.
        let lifted = vec![
            (
                0x1000,
                vec![ai(
                    0x1000,
                    LlilInstruction::SetReg {
                        dest: LlilRegister::Concrete("r12".to_string()),
                        size: Size::QWord,
                        value: LlilExpr::Const { value: 7, size: Size::QWord },
                    },
                )],
            ),
            (0x1004, vec![ai(0x1004, LlilInstruction::Ret)]),
        ];
        let has_dead_def = |out: &[(u64, Vec<LlilAnnotatedInstr>)]| {
            out.iter().flat_map(|(_, v)| v.iter()).any(|i| {
                matches!(
                    &i.instr,
                    LlilInstruction::SetReg { dest: LlilRegister::Concrete(r), .. } if r == "r12"
                )
            })
        };

        // Gruppo di controllo: variabile RIMOSSA (non svuotata).
        unsafe { std::env::remove_var("RUSTRE_IL_PASSES_DCE") };
        let (off, _s, _b, _a) = optimize_lifted_llil(&lifted, 0x1000);
        assert!(
            has_dead_def(&off),
            "default OFF: la definizione mai letta deve SOPRAVVIVERE: {off:?}"
        );

        // Controllo positivo: acceso, la DCE deve mordere davvero.
        unsafe { std::env::set_var("RUSTRE_IL_PASSES_DCE", "1") };
        let (on, _s, _b, _a) = optimize_lifted_llil(&lifted, 0x1000);
        unsafe { std::env::remove_var("RUSTRE_IL_PASSES_DCE") };
        assert!(
            !has_dead_def(&on),
            "RUSTRE_IL_PASSES_DCE=1: la DCE deve essere davvero cablata: {on:?}"
        );

        // …e tolta di nuovo, si torna al comportamento di default.
        let (off2, _s, _b, _a) = optimize_lifted_llil(&lifted, 0x1000);
        assert!(has_dead_def(&off2), "il gate deve essere richiudibile: {off2:?}");
    }

    #[test]
    fn optimize_lifted_llil_keeps_cross_block_live_values_and_loop_shape() {
        // A do/while shape: the induction update in the loop body is read by
        // the compare feeding the backward CondJump, and rsi/rdi live across
        // blocks. Block-based DCE must not drop any of it, and the surviving
        // stream must keep original address order.
        use rustre_il_llil::{LlilAnnotatedInstr, LlilExpr, LlilInstruction, LlilRegister, Size};
        let ai = |addr: u64, instr: LlilInstruction| LlilAnnotatedInstr {
            address: rustre_core::address::Address::new(addr),
            size: 4,
            length: 4,
            instr,
        };
        let reg = |n: &str| LlilRegister::Concrete(n.to_string());
        let rref = |n: &str| LlilExpr::RegisterRef { reg: reg(n), size: Size::QWord };
        let lifted = vec![
            // 0x1000: rsi = rsi + 8 (loop body, branch target)
            (
                0x1000,
                vec![ai(
                    0x1000,
                    LlilInstruction::SetReg {
                        dest: reg("rsi"),
                        size: Size::QWord,
                        value: LlilExpr::AddT(
                            Box::new(rref("rsi")),
                            Box::new(LlilExpr::Const { value: 8, size: Size::QWord }),
                            Size::QWord,
                        ),
                    },
                )],
            ),
            // 0x1004: tmp0 = rsi <= rdi
            (
                0x1004,
                vec![ai(
                    0x1004,
                    LlilInstruction::SetReg {
                        dest: reg("tmp0"),
                        size: Size::QWord,
                        value: LlilExpr::CmpUle(Box::new(rref("rsi")), Box::new(rref("rdi"))),
                    },
                )],
            ),
            // 0x1007: if (tmp0) goto 0x1000 else 0x1009
            (
                0x1007,
                vec![ai(
                    0x1007,
                    LlilInstruction::CondJump {
                        cond: rref("tmp0"),
                        true_dest: rustre_core::address::Address::new(0x1000),
                        false_dest: rustre_core::address::Address::new(0x1009),
                    },
                )],
            ),
            (0x1009, vec![ai(0x1009, LlilInstruction::Ret)]),
        ];
        let (out, _stats, _before, _after) = optimize_lifted_llil(&lifted, 0x1000);
        let flat: Vec<&LlilAnnotatedInstr> = out.iter().flat_map(|(_, v)| v.iter()).collect();
        // The comparison feeding the CondJump must survive.
        assert!(
            flat.iter().any(
                |i| matches!(&i.instr, LlilInstruction::SetReg { value: LlilExpr::CmpUle(..), .. })
            ),
            "loop condition compare was dropped: {out:?}"
        );
        // The induction update must survive (read by the compare / next iter).
        assert!(
            flat.iter().any(
                |i| matches!(&i.instr, LlilInstruction::SetReg { value: LlilExpr::AddT(..), .. })
            ),
            "loop induction update was dropped: {out:?}"
        );
        // The CondJump itself must survive, and no synthetic jump may leak.
        assert!(flat.iter().any(|i| matches!(i.instr, LlilInstruction::CondJump { .. })));
        assert!(flat.iter().all(|i| i.size != 0), "synthetic jump leaked: {out:?}");
        // Address order preserved.
        let addrs: Vec<u64> = out.iter().map(|(a, _)| *a).collect();
        assert_eq!(addrs, vec![0x1000, 0x1004, 0x1007, 0x1009]);
    }

    #[test]
    fn sse_scalar_float_arithmetic_stays_comment_until_double_typed() {
        // Regression guard: scalar/packed float arithmetic must NOT map to
        // `_mm_mul_sd`-family intrinsics while the xmm locals are __m128i —
        // that returned __m128d and broke 136 corpus files. Keep the honest
        // asm-comment fallback (Skip) until double-typing lands.
        assert!(sse_binary_intrinsic("mulsd").is_none());
        assert!(sse_binary_intrinsic("addsd").is_none());
        assert!(sse_binary_intrinsic("mulps").is_none());
    }

    #[test]
    fn sse_scalar_movd_movq_cvt_intrinsics() {
        // GPR -> xmm (Intel + AT&T; AT&T `src, dst` order-swap proves (dst,src)).
        assert_sse_assign("movd", "xmm0, eax", "xmm0", "_mm_cvtsi32_si128(eax)");
        assert_sse_assign("movd", "%eax, %xmm0", "xmm0", "_mm_cvtsi32_si128(eax)");
        // xmm -> GPR (direction flip, both syntaxes).
        assert_sse_assign("movd", "eax, xmm0", "eax", "_mm_cvtsi128_si32(xmm0)");
        assert_sse_assign("movd", "%xmm0, %eax", "eax", "_mm_cvtsi128_si32(xmm0)");
        // movq is 64-bit.
        assert_sse_assign("movq", "%rax, %xmm0", "xmm0", "_mm_cvtsi64_si128(rax)");
        assert_sse_assign("movq", "%xmm0, %rax", "rax", "_mm_cvtsi128_si64(xmm0)");
        // WIDTH TRAP: r8d is a 32-bit reg whose name starts with 'r' — width must
        // come from the mnemonic (movd=32), so cvtsi32 not cvtsi64.
        assert_sse_assign("movd", "%r8d, %xmm0", "xmm0", "_mm_cvtsi32_si128(r8d)");
        // MUST-NOT (byte-identical fallback, never a wrong intrinsic):
        // xmm<->xmm movq stays `dst = src` (upper-lane upgrade is a later slice).
        assert_sse_assign("movq", "%xmm1, %xmm0", "xmm0", "xmm1");
        // Memory LOAD into xmm → typed intrinsic keeping the `*(rsp+K)` deref
        // visible for slot naming. movd=32-bit (cvt), movq=64-bit (loadl).
        assert_sse_assign("movd", "0x20(%rsp), %xmm0", "xmm0", "_mm_cvtsi32_si128(*(rsp + 0x20))");
        assert_sse_assign("movq", "0x20(%rsp), %xmm0", "xmm0", "_mm_loadl_epi64((__m128i *)&*(rsp + 0x20))");
        // Memory STORE from xmm → still the plain `dst = src` fallback (slice 2
        // loads only; store intrinsics are a later slice).
        assert_sse_assign("movq", "%xmm0, 0x20(%rsp)", "*(rsp + 0x20)", "xmm0");
        // PIN: the loadl form's `*(rsp+K)` deref must survive name_stack_slots as
        // `&var_20`, never leaking raw `rsp`.
        let named = name_stack_slots("void f() {\n    xmm0 = _mm_loadl_epi64((__m128i *)&*(rsp + 0x20));\n}");
        assert!(named.contains("&var_20"), "slot named: {named}");
        assert!(!named.contains("rsp"), "no raw rsp leak: {named}");
        // A mnemonic/width mismatch (movq with a 32-bit gpr) → fallback, no cvt.
        assert_sse_assign("movq", "%eax, %xmm0", "xmm0", "eax");
        // Non-xmm movd/movq never reaches the SSE arm — the generic mov path
        // keeps `dst = src` (AT&T order-swapped).
        assert!(matches!(
            lift_data_move_stmt("movq", "%rax, %rbx"),
            InstrLift::Handled(Some(CfsStatement::Assign { .. }))
        ));
        // And lift_data_move_stmt bails (Skip) on an xmm-carrying movd/movq so the
        // SSE arm gets it.
        assert!(matches!(lift_data_move_stmt("movq", "%rax, %xmm0"), InstrLift::Skip));
    }

    #[test]
    fn sse_zero_idiom_and_packed_alu() {
        assert_sse_assign("pxor", "%xmm0, %xmm0", "xmm0", "_mm_setzero_si128()");
        assert_sse_assign("xorps", "%xmm1, %xmm1", "xmm1", "_mm_setzero_ps()");
        // AT&T `paddq %xmm1, %xmm0`: dst is the second operand.
        assert_sse_assign("paddq", "%xmm1, %xmm0", "xmm0", "_mm_add_epi64(xmm0, xmm1)");
        assert_sse_assign("pand", "(%rdx), %xmm3", "xmm3", "_mm_and_si128(xmm3, *rdx)");
        assert_sse_assign("pcmpgtb", "%xmm1, %xmm0", "xmm0", "_mm_cmpgt_epi8(xmm0, xmm1)");
        assert_sse_assign("pxor", "%xmm1, %xmm0", "xmm0", "_mm_xor_si128(xmm0, xmm1)");
        // Unknown vector mnemonics fall through to the comment fallback.
        assert!(matches!(lift_sse_stmt("haddps", "%xmm1, %xmm0"), InstrLift::Skip));
    }

    #[test]
    fn sse_shifts_movemask_and_shuffles() {
        // Immediate count picks the `_mm_..i_..` spelling.
        assert_sse_assign("psrlq", "$13, %xmm1", "xmm1", "_mm_srli_epi64(xmm1, 13)");
        assert_sse_assign("psrlq", "xmm1, 13", "xmm1", "_mm_srli_epi64(xmm1, 13)");
        // Register count picks the plain spelling.
        assert_sse_assign("psllq", "%xmm2, %xmm1", "xmm1", "_mm_sll_epi64(xmm1, xmm2)");
        // pmovmskb: gp destination, xmm source, non-destructive.
        assert_sse_assign("pmovmskb", "%xmm0, %eax", "eax", "_mm_movemask_epi8(xmm0)");
        // Shuffles in AT&T (`imm, src, dst`) and Intel (`dst, src, imm`) order.
        assert_sse_assign("pshufd", "$0x44, %xmm0, %xmm1", "xmm1", "_mm_shuffle_epi32(xmm0, 0x44)");
        assert_sse_assign("pshufd", "xmm1, xmm0, 0x44", "xmm1", "_mm_shuffle_epi32(xmm0, 0x44)");
        assert_sse_assign("pshuflw", "$0xE8, %xmm2, %xmm2", "xmm2", "_mm_shufflelo_epi16(xmm2, 0xE8)");
        // A shuffle whose third operand is not an immediate is left honest.
        assert!(matches!(lift_sse_stmt("pshufd", "%xmm0, %xmm1"), InstrLift::Skip));
    }

    #[test]
    fn sync_locals_declares_xmm_as_m128i() {
        // Assigned xmm regs are declared `__m128i`; a live-in (read-only)
        // xmm reg is declared too.
        let code = "__int64 f() {\n    xmm0 = *a1;\n    xmm0 = _mm_add_epi64(xmm0, xmm1);\n    return 0;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("__m128i xmm0;"), "{out}");
        assert!(out.contains("__m128i xmm1;"), "{out}");
        assert!(!out.contains("__int64 xmm"), "{out}");
        // The intrinsic name itself must never be declared.
        assert!(!out.contains("_mm_add_epi64;"), "{out}");
    }

    #[test]
    fn multibyte_nops_are_silent() {
        for m in ["nop", "nopw", "nopl", "nopq"] {
            assert!(matches!(lift_ctrl_flow_stmt(m, "(%rax)"), InstrLift::Handled(None)), "{m}");
        }
    }

    #[test]
    fn sync_locals_declares_undefined_generated_local() {
        // `v1` is read but never assigned/declared (a live-in register that
        // escaped renaming). It must be declared so the output is valid C.
        let code = "__int64 f() {\n    a1 = v1;\n    return a1;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("__int64 v1;"), "{out}");
    }

    #[test]
    fn sync_locals_does_not_declare_calls_or_labels() {
        // `sub_140…`, `loc_…`, `flags` must never be declared as locals.
        let code = "void f() {\n    sub_1000();\n    goto loc_2000;\n    x = flags;\n}";
        let out = sync_local_declarations(code);
        assert!(!out.contains("__int64 sub_1000;"), "{out}");
        assert!(!out.contains("__int64 loc_2000;"), "{out}");
        assert!(!out.contains("__int64 flags;"), "{out}");
    }

    #[test]
    fn sync_locals_targets_function_not_preceding_struct() {
        // A recovered struct precedes the function. sync must manage the
        // function's locals (declare the undeclared `v1`), NOT the struct body.
        let code =
            "struct S {\n    __int64 field_0;\n};\n__int64 f() {\n    v1 = a1;\n    return v1;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("struct S {"), "struct untouched: {out}");
        assert!(out.contains("    __int64 field_0;\n};"), "struct field intact: {out}");
        assert!(out.contains("__int64 v1;"), "undeclared local synthesized: {out}");
    }

    #[test]
    fn sync_locals_drops_unmentioned_declaration() {
        let code = "__int64 f() {\n    void * r_eax;\n\n    return 0;\n}";
        let out = sync_local_declarations(code);
        assert!(!out.contains("r_eax"), "{out}");
        assert!(out.contains("return 0;"), "{out}");
    }

    #[test]
    fn sync_locals_keeps_mentioned_declaration() {
        let code = "__int64 f() {\n    int v1;\n\n    v1 = 3;\n    return v1;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("int v1;"), "{out}");
        // Declared already, so it must not be synthesized a second time.
        assert_eq!(out.matches("v1;").count(), 2, "{out}");
    }

    #[test]
    fn sync_locals_declares_assigned_but_undeclared() {
        let code = "__int64 __fastcall f() {\n    result = 0;\n    return result;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("__int64 result;"), "{out}");
    }

    #[test]
    fn sync_locals_never_redeclares_a_parameter() {
        let code = "__int64 __fastcall f(__int64 a1) {\n    a1 = a1 + 1;\n    return a1;\n}";
        let out = sync_local_declarations(code);
        assert!(!out.contains("__int64 a1;"), "{out}");
    }

    #[test]
    fn sync_locals_declares_undeclared_pointer_role_names() {
        // `dst`/`src`/`ptr` (usage-derived names) used only via deref are never
        // plain-assigned, so they must be declared by the read-undeclared net —
        // and as POINTERS (a plain `__int64 dst;` would make `*dst` invalid).
        let code = "__int64 __fastcall f(__int64 a4) {\n    *dst = *dst - a4;\n    *dst2 = *dst2 + 1;\n    return;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("__int64 *dst;"), "dst declared as pointer: {out}");
        assert!(out.contains("__int64 *dst2;"), "dst2 declared as pointer: {out}");
        // Sanity: the role recogniser matches only the exact stems + suffixes.
        assert!(is_pointer_role_name("dst") && is_pointer_role_name("ptr3") && is_pointer_role_name("src2"));
        assert!(!is_pointer_role_name("distance") && !is_pointer_role_name("result"));
    }

    #[test]
    fn sync_locals_declares_undeclared_role_name_flag_as_pointer_when_derefed() {
        // A live-in register renamed `flag` by usage-based naming, used only
        // through derefs — must be declared, and as a pointer (D4 follow-up:
        // exposed when the two-loop sweep fix decoded full function bodies).
        let code = "__int64 __fastcall f(__int64 a1) {\n    *flag = a1;\n    return a1;\n}";
        let out = sync_local_declarations(code);
        assert!(out.contains("__int64 *flag;"), "flag declared as pointer: {out}");
        // Tight multiplication is NOT a deref: `count` stays scalar.
        let code2 = "__int64 __fastcall f(__int64 a1) {\n    a1 = a1*count;\n    return a1;\n}";
        let out2 = sync_local_declarations(code2);
        assert!(out2.contains("__int64 count;") && !out2.contains("__int64 *count;"), "{out2}");
    }

    #[test]
    fn sync_locals_ignores_non_plain_assignment_targets() {
        // `*p`, `a[i]` and `p->f` are not declarable identifiers.
        let code = "void f() {\n    *p = 1;\n    a[i] = 2;\n    p->f = 3;\n}";
        let out = sync_local_declarations(code);
        assert!(!out.contains(" p;") && !out.contains(" a;"), "{out}");
    }

    #[test]
    fn restore_dce_dropped_return_value_fixes_mis_split_return() {
        // else-branch computes the value into a2 (DCE'd feeder `v4 = a2`) but the
        // return reaches for the if-branch's `result` → must become `return a2;`.
        let code = "__int64 f(int a2) {\n    __int64 result;\n    if (a2 <= 0) {\n        result = a2;\n        return result;\n    } else {\n        a2 = 0;\n        do { a2 += 1; } while (a2 != 5);\n// DCE(df):         v4 = a2;\n        return result;\n    }\n}";
        let out = restore_dce_dropped_return_value(code);
        // The else-branch return is repaired; the if-branch (result assigned in
        // scope) is left alone.
        assert_eq!(out.matches("return a2;").count(), 1, "{out}");
        assert!(out.contains("        return result;\n    }") || out.matches("return result;").count() == 1, "{out}");

        // False positive guard: when `result` IS assigned in the same block, the
        // return is legitimate and must NOT be rewritten to the unrelated feeder.
        let ok = "__int64 f() {\n    result = compute();\n// DCE(df):     v4 = a2;\n    return result;\n}";
        assert_eq!(restore_dce_dropped_return_value(ok), ok, "must not touch a legit return");

        // No DCE feeder → unchanged.
        let plain = "__int64 f() {\n    result = 1;\n    return result;\n}";
        assert_eq!(restore_dce_dropped_return_value(plain), plain);
    }

    #[test]
    fn drop_dead_keeps_bare_return_feeder() {
        // `v3 = a2;` is the else-branch return value: dead by the "no RHS reads
        // it" rule, but the following bare `return;` WILL use it once
        // materialised. It must survive DCE, else the return fill reaches for the
        // wrong (linear-global) name — the sum_varargs "returns 0 not the sum" bug.
        let code = "__int64 __fastcall f(__int64 a1, __int64 a2) {\n    __int64 v3;\n    v3 = a2;\n    return;\n}";
        let out = drop_dead_only_assigned_locals(code);
        assert!(out.contains("    v3 = a2;"), "feeder must survive: {out}");
        assert!(!out.contains("// DCE(df):     v3 = a2;"), "{out}");
    }

    #[test]
    fn fix_return_fills_bare_return_in_every_branch() {
        let code = "__int64 f() {\n    if (c) {\n        result = 0;\n        return;\n    } else {\n        result = 1;\n        return result;\n    }\n}";
        let out = fix_return_statement_consistency(code);
        assert_eq!(out.matches("return result;").count(), 2, "{out}");
    }

    #[test]
    fn fix_return_non_void_bare_return_falls_back_to_zero() {
        // A value-returning function whose body assigned nothing before a bare
        // `return;` (a mis-lifted stub) must become `return 0;` — never a bare
        // `return;` in a non-void function (invalid C).
        let code = "__int64 __fastcall f(__int64 a1) {\n    *dst = a1;\n    return;\n}";
        let out = fix_return_statement_consistency(code);
        assert!(out.contains("    return 0;"), "{out}");
        assert!(!out.contains("    return;\n"), "no bare return in non-void: {out}");
    }

    #[test]
    fn fix_return_strips_value_from_void_function() {
        // A tail call keeps its side effect; a bare value does not.
        let code = "void f() {\n    return sub_2000();\n}";
        assert!(fix_return_statement_consistency(code).contains("    sub_2000();"));

        let code = "void f() {\n    x = 1;\n    return x;\n}";
        let out = fix_return_statement_consistency(code);
        assert!(out.contains("    return;"), "{out}");
        assert!(!out.contains("return x;"), "{out}");
    }

    #[test]
    fn fix_return_leaves_a_consistent_function_alone() {
        let code = "__int64 f() {\n    result = 1;\n    return result;\n}";
        assert_eq!(fix_return_statement_consistency(code), code);
        let code = "void f() {\n    return;\n}";
        assert_eq!(fix_return_statement_consistency(code), code);
    }

    #[test]
    fn fix_return_ignores_identifiers_starting_with_return() {
        let code = "__int64 f() {\n    returned = 1;\n    return returned;\n}";
        assert_eq!(fix_return_statement_consistency(code), code);
    }

    #[test]
    fn fold_compound_increment_and_decrement() {
        assert_eq!(fold_assign_expr("result = result + 1").unwrap(), "++result");
        assert_eq!(fold_assign_expr("i = i - 1").unwrap(), "--i");
    }

    #[test]
    fn fold_compound_binary_ops() {
        assert_eq!(fold_assign_expr("x = x + 4").unwrap(), "x += 4");
        assert_eq!(fold_assign_expr("x = x * y").unwrap(), "x *= y");
        assert_eq!(fold_assign_expr("x = x ^ 0xff").unwrap(), "x ^= 0xff");
        assert_eq!(fold_assign_expr("x = x << 2").unwrap(), "x <<= 2");
    }

    #[test]
    fn fold_compound_rejects_non_self_assignments() {
        // Different variable on the right.
        assert!(fold_assign_expr("x = y + 1").is_none());
        // Prefix match must not count: `xs` is not `x`.
        assert!(fold_assign_expr("x = xs + 1").is_none());
        // Comparisons and non-identifier targets.
        assert!(fold_assign_expr("x == x + 1").is_none());
        assert!(fold_assign_expr("*p = *p + 1").is_none());
        assert!(fold_assign_expr("a[i] = a[i] + 1").is_none());
        // Identity, no operator.
        assert!(fold_assign_expr("x = x").is_none());
        // Field / element access must NOT be mis-parsed as a compound op — the
        // `->` arrow in particular must be rejected before `-` matches it
        // (regression: `ptr = ptr->field_0` mis-folded to `ptr -= >field_0`).
        assert!(fold_assign_expr("ptr = ptr->field_0").is_none());
        assert!(fold_assign_expr("x = x.field").is_none());
        assert!(fold_assign_expr("p = p[3]").is_none());
    }

    #[test]
    fn fold_compound_rewrites_for_step_clause() {
        let code = "    for (; result < a1; result = result + 1) {\n    }";
        let out = fold_compound_assignments(code);
        assert!(out.contains("for (; result < a1; ++result) {"), "{out}");
    }

    #[test]
    fn retype_m128i_return_when_all_returns_vector() {
        // Every return yields an __m128i xmm → return type becomes __m128i.
        let code = "__int64 __fastcall f() {\n    __m128i xmm0;\n    return xmm0;\n}";
        let out = retype_m128i_return(code);
        assert!(out.contains("__m128i __fastcall f()"), "{out}");
        // A mixed return (one scalar) → left __int64.
        let mixed = "__int64 __fastcall f() {\n    __m128i xmm0;\n    __int64 v2;\n    return xmm0;\n    return v2;\n}";
        assert_eq!(retype_m128i_return(mixed), mixed);
    }

    #[test]
    fn cast_struct_pointer_scalar_deref_casts_base() {
        // `*ptr = v6` where ptr is struct* and v6 int → cast base to __int64*.
        let code = "int f() {\n    struct Struct_2_t *ptr;\n    int v6;\n    *ptr = v6;\n}";
        assert!(cast_struct_pointer_scalar_deref(code).contains("*(__int64 *)ptr = (__int64)(v6);"), "{}", cast_struct_pointer_scalar_deref(code));
        // `a1[4] = a3` (struct* base indexed) → cast.
        let idx = "int f(struct Struct_1_t *a1) {\n    __int64 a3;\n    a1[4] = a3;\n}";
        assert!(cast_struct_pointer_scalar_deref(idx).contains("((__int64 *)a1)[4] = (__int64)(a3);"), "{}", cast_struct_pointer_scalar_deref(idx));
        // A genuine struct copy (`*p = s` where s is a struct) is left alone.
        let cp = "int f() {\n    struct Struct_1_t *p;\n    struct Struct_1_t s;\n    *p = s;\n}";
        assert_eq!(cast_struct_pointer_scalar_deref(cp), cp);
        // A non-struct pointer base is untouched.
        let np = "int f() {\n    __int64 *p;\n    int v;\n    *p = v;\n}";
        assert_eq!(cast_struct_pointer_scalar_deref(np), np);
        // READ form: scalar = *structptr → cast deref.
        let rd = "int f() {\n    struct Struct_2_t *ptr;\n    __int64 a4;\n    a4 = *ptr;\n}";
        assert!(cast_struct_pointer_scalar_deref(rd).contains("a4 = *(__int64 *)ptr;"), "{}", cast_struct_pointer_scalar_deref(rd));
        // READ form: scalar = *(structptr + i) → cast deref.
        let ro = "int f(struct Struct_1_t *a1) {\n    __int64 a4;\n    a4 = *(a1 + 3);\n}";
        assert!(cast_struct_pointer_scalar_deref(ro).contains("a4 = *(__int64 *)(a1 + 3);"), "{}", cast_struct_pointer_scalar_deref(ro));
        // READ form: scalar = structptr[i] → cast base.
        let ri = "int f(struct Struct_1_t *a1) {\n    __int64 a4;\n    a4 = a1[2];\n}";
        assert!(cast_struct_pointer_scalar_deref(ri).contains("a4 = ((__int64 *)a1)[2];"), "{}", cast_struct_pointer_scalar_deref(ri));
        // READ into a struct-typed lvalue (genuine copy) is left alone.
        let rc = "int f() {\n    struct Struct_1_t *p;\n    struct Struct_1_t s;\n    s = *p;\n}";
        assert_eq!(cast_struct_pointer_scalar_deref(rc), rc);
    }

    #[test]
    fn fold_segment_intrinsic_offset_inlines_teb_offset() {
        // `mov $0x30,%eax; mov %gs:(%eax),%rax` → the immediate must be folded
        // into the read so it isn't the self-referential `rax = __readgsqword(rax)`
        // (uninitialised TEB read). eax/rax collapse to one canonical register.
        let mut stmts = vec![
            CfsStatement::Assign { lhs: "eax".into(), rhs: "0x30".into() },
            CfsStatement::Assign { lhs: "rax".into(), rhs: "__readgsqword(eax)".into() },
        ];
        fold_segment_intrinsic_offset(&mut stmts);
        let CfsStatement::Assign { rhs, .. } = &stmts[1] else { panic!() };
        assert_eq!(rhs, "__readgsqword(0x30)", "{stmts:?}");
        // A non-adjacent or non-matching register is left alone.
        let mut other = vec![
            CfsStatement::Assign { lhs: "ecx".into(), rhs: "0x30".into() },
            CfsStatement::Assign { lhs: "rax".into(), rhs: "__readgsqword(rbx)".into() },
        ];
        fold_segment_intrinsic_offset(&mut other);
        let CfsStatement::Assign { rhs, .. } = &other[1] else { panic!() };
        assert_eq!(rhs, "__readgsqword(rbx)");
        // Go-runtime TLS-base idiom: the offset is a data symbol, not a literal.
        let mut go = vec![
            CfsStatement::Assign { lhs: "rbx".into(), rhs: "off_14018B0F0".into() },
            CfsStatement::Assign { lhs: "rbx".into(), rhs: "__readgsqword(rbx)".into() },
        ];
        fold_segment_intrinsic_offset(&mut go);
        let CfsStatement::Assign { rhs, .. } = &go[1] else { panic!() };
        assert_eq!(rhs, "__readgsqword(off_14018B0F0)", "{go:?}");
    }

    #[test]
    fn propagate_register_copies_only_rewrites_after_def() {
        // A copy `eax = ecx` must NOT rewrite an earlier, independent use of eax
        // (the bug that turned `eax = 0x2AA0` into `ecx = 0x2AA0`, self-cancelling
        // the whole computation and leaving an empty `return 0` body).
        let mut stmts = vec![
            CfsStatement::Assign { lhs: "ebx".into(), rhs: "eax + 1".into() }, // reads eax BEFORE def
            CfsStatement::Assign { lhs: "eax".into(), rhs: "ecx".into() },      // copy def
            CfsStatement::Assign { lhs: "edx".into(), rhs: "eax + 2".into() },  // reads eax AFTER def
        ];
        propagate_register_copies(&mut stmts);
        let rendered: Vec<String> = stmts
            .iter()
            .map(|s| match s {
                CfsStatement::Assign { lhs, rhs } => format!("{lhs} = {rhs}"),
                _ => String::new(),
            })
            .collect();
        // The pre-def use keeps `eax`; only the post-def use becomes `ecx`.
        assert!(rendered.iter().any(|l| l == "ebx = eax + 1"), "{rendered:?}");
        assert!(rendered.iter().any(|l| l == "edx = ecx + 2"), "{rendered:?}");
    }

    #[test]
    fn propagate_register_copies_keeps_def_used_at_another_width() {
        // `mov %r9d, %edx` feeding `*(rsp + rdx*2 + 0x20)`: the use spells the
        // same machine register 64-bit wide, so the textual rewrite can't reach
        // it. Dropping the def as "dead" left `rdx` holding the stale frame
        // pointer set far above — the `buf[buf]` bug. The copy must be skipped.
        let mut stmts = vec![
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "rsp + 0x20".into() },
            CfsStatement::Assign { lhs: "edx".into(), rhs: "r9d".into() },
            CfsStatement::Assign { lhs: "r8".into(), rhs: "*(rsp + rdx*2 + 0x20)".into() },
        ];
        propagate_register_copies(&mut stmts);
        let rendered: Vec<String> = stmts
            .iter()
            .map(|s| match s {
                CfsStatement::Assign { lhs, rhs } => format!("{lhs} = {rhs}"),
                _ => String::new(),
            })
            .collect();
        assert!(rendered.iter().any(|l| l == "edx = r9d"), "def dropped: {rendered:?}");
        assert!(
            rendered.iter().any(|l| l == "r8 = *(rsp + rdx*2 + 0x20)"),
            "use corrupted: {rendered:?}"
        );
    }

    #[test]
    fn is_pointer_type_knows_winapi_pointer_typedefs() {
        // Spelled-out pointers.
        assert!(is_pointer_type("char *"));
        assert!(is_pointer_type("struct S *"));
        // WinAPI typedefs that are pointers without a `*`.
        for t in ["LPCSTR", "LPVOID", "HANDLE", "PBYTE", "HMODULE", "FARPROC"] {
            assert!(is_pointer_type(t), "{t} is a pointer");
        }
        // Genuine scalars must stay scalars.
        for t in ["__int64", "int", "DWORD", "SIZE_T", "size_t", "char", "BOOL"] {
            assert!(!is_pointer_type(t), "{t} is not a pointer");
        }
    }

    #[test]
    fn win64_cc_treats_self_zeroing_as_a_define_not_a_read() {
        // `_GetPEImageBase`'s real shape: `mov mem,%rax; xor %edx,%edx; ...`.
        // Its prototype takes VOID; the self-zeroing `xor` must not make rdx a
        // parameter (which would also drag a phantom a1 in, since arity is
        // "highest param index + 1").
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 f() {\n    return 0;\n}";
        let instrs = vec![ins("mov", "0x1EE9(%rip), %rax"), ins("xor", "%edx, %edx")];
        let out = apply_win64_calling_convention(code, &instrs, &HashMap::new());
        assert!(!out.contains("a1"), "self-zeroing xor invented a parameter: {out}");
        // A genuine read of rdx still marks it a parameter.
        let real = vec![ins("mov", "%rdx, %rax")];
        let out = apply_win64_calling_convention(code, &real, &HashMap::new());
        assert!(out.contains("a2"), "a genuine read must still be a param: {out}");
    }

    #[test]
    fn win64_cc_recovers_xmm_double_param_and_binds_dangling_xmm_local() {
        // sample11 `punned_bits(double)`: body is `movq %xmm0, %rax; ret`.
        // xmm0 is read before any write, so Win64 slot 1 carries a `double`
        // parameter; the emitted `xmm0` name must be bound to it instead of
        // dangling as an uninitialised local.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let insns = vec![ins("movq", "%xmm0, %rax"), ins("ret", "")];
        assert_eq!(win64_xmm_param_regs_live_in(&insns), [true, false, false, false]);
        assert_eq!(win64_recovered_arity(&insns), 1);
        let code = "void punned_bits() {\n    rax = xmm0;\n}";
        let out = apply_win64_calling_convention(code, &insns, &HashMap::new());
        assert!(out.contains("(double a1)"), "{out}");
        assert!(out.contains("rax = a1;"), "{out}");

        // Self-zeroed xmm0 is a DEFINE, not a read; a genuine RMW read of
        // xmm1 (addsd reads its destination) still marks slot 2.
        let scratch = vec![ins("xorps", "%xmm0, %xmm0"), ins("addsd", "%xmm0, %xmm1")];
        assert_eq!(win64_xmm_param_regs_live_in(&scratch), [false, true, false, false]);

        // A load into xmm0 (write) before use: no parameter.
        let loaded = vec![ins("movsd", "8(%rsp), %xmm0"), ins("addsd", "%xmm1, %xmm0")];
        assert_eq!(win64_xmm_param_regs_live_in(&loaded)[0], false);
    }

    #[test]
    fn win64_cc_refuses_to_coalesce_wide_reuse_into_narrow_param() {
        // sample1 `accumulate(long *p, int n)` scalar tail: the param is only
        // ever READ as `edx` (32-bit), dies at `movslq %edx, %rdx`, and rdx is
        // then reused as the 64-bit accumulator (`xor %edx,%edx` zeroing it,
        // `add %rax, %rdx` accumulating). Coalescing that reuse into the slot
        // (later narrowed to `int a2`) silently truncates the 64-bit sum. The
        // refusal must leave the post-redefinition register uncoalesced while
        // still renaming the genuine live-in reads and keeping the signature.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let instrs = vec![
            ins("test", "%edx, %edx"),
            ins("jle", "0x2000"),
            ins("movslq", "%edx, %rdx"),
            ins("lea", "(%rdx,%rdx,2), %rax"),
            ins("xor", "%edx, %edx"),
            ins("add", "%rax, %rdx"),
            ins("mov", "%rdx, %rax"),
            ins("mov", "%rcx, %r10"),
        ];
        assert!(wide_reuse_after_param_death(&instrs, "rdx"));
        // rcx is read at full width — never a truncation hazard.
        assert!(!wide_reuse_after_param_death(&instrs, "rcx"));

        // Structured-emission text order mirrors the real corpus output: the
        // early-exit block (with its OWN pure redefinition of the register)
        // comes textually first. The split must land on the accumulator's
        // redefinition in the main path, not that earlier one — otherwise the
        // main path's param-derived stride (`rdx = edx; rax = rdx + rdx*2`)
        // loses its parameter and reads an uninitialised local.
        let code = "void f() {\n    if (edx <= 0) {\n        edx = 0;\n        rax = rdx;\n        return;\n    }\n    rdx = edx;\n    rax = rdx + rdx*2;\n    edx = 0;\n    rdx = rdx + rax;\n    rax = rdx;\n    return;\n}\n";
        let out = apply_win64_calling_convention(code, &instrs, &HashMap::new());
        // Live-in reads (and the derived value before the accumulator's pure
        // redefinition) are still the parameter.
        assert!(out.contains("if (a2 <= 0)"), "{out}");
        assert!(out.contains("rax = a2 + a2*2;"), "{out}");
        // From the accumulator's pure redefinition on, the register must NOT
        // be coalesced into the (narrower) parameter slot.
        assert!(out.contains("edx = 0;\n    rdx = rdx + rax;"), "wide reuse was coalesced into the param: {out}");
        assert!(out.contains("rax = rdx;\n    return;"), "{out}");
        // Signature untouched by the refusal: a2 still declared (not widened
        // away, not dropped).
        assert!(out.contains("__int64 a1, __int64 a2"), "{out}");
    }

    #[test]
    fn win64_cc_movabs_and_pop_are_writes_not_reads() {
        // Witness: Go's `internal_runtime_sys_OnesCount64` takes ONE argument
        // (in rax, per the Go register ABI) yet came out with two parameters —
        // `movabs $0x5555555555555555, %rdx` fell through to the "assume the
        // destination is read" arm and invented them.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 f() {\n    return 0;\n}";

        let instrs = vec![
            ins("mov", "%rax, %rcx"),
            ins("movabs", "$0x5555555555555555, %rdx"),
            ins("and", "%rdx, %rax"),
        ];
        let out = apply_win64_calling_convention(code, &instrs, &HashMap::new());
        assert!(!out.contains("a1"), "movabs destination read as a param: {out}");

        // `pop %rdx` writes rdx; its single operand is not a read.
        let popped = vec![ins("pop", "%rdx"), ins("mov", "%rdx, %rax")];
        let out = apply_win64_calling_convention(code, &popped, &HashMap::new());
        assert!(!out.contains("a1"), "pop destination read as a param: {out}");

        // But `pop (%rcx)` DOES read rcx as an address base.
        let mem = vec![ins("pop", "(%rcx)")];
        let out = apply_win64_calling_convention(code, &mem, &HashMap::new());
        assert!(out.contains("a1"), "memory-operand pop must read its base: {out}");
    }

    #[test]
    fn win64_cc_recovers_a_param_whose_only_use_is_a_forwarded_call_arg() {
        // Bug D9. `caller(int a, int b) { return rec(a % 11, b); }` — gcc -O1
        // leaves edx completely untouched (b is already in the right register),
        // so rdx is never MENTIONED in this function's own instruction text.
        // A textual read-before-write scan therefore drops it, leaving an
        // undefined local at the forwarding call site. The direct call reads
        // the callee's first `arity` argument registers, so any of those not
        // yet defined here must be live-in — i.e. a parameter.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 f() {
    return 0;
}";
        let instrs = vec![
            ins("sub", "$0x28, %rsp"),
            ins("sub", "%eax, %ecx"),
            ins("call", "0x0000000140001450"),
            ins("add", "$0x28, %rsp"),
            ins("ret", ""),
        ];
        // Without callee knowledge: the pre-fix behaviour, arity 1.
        let out = apply_win64_calling_convention(code, &instrs, &HashMap::new());
        assert!(out.contains("a1") && !out.contains("a2"), "{out}");
        // With the callee recovered as taking 2 register args, the forwarded
        // rdx becomes this function's second parameter.
        let mut arities = HashMap::new();
        arities.insert(0x1_4000_1450u64, 2usize);
        let out = apply_win64_calling_convention(code, &instrs, &arities);
        assert!(out.contains("__int64 a1, __int64 a2"), "D9: forwarded param dropped: {out}");
        // A callee arity of 1 must NOT invent a second parameter.
        let mut one = HashMap::new();
        one.insert(0x1_4000_1450u64, 1usize);
        let out = apply_win64_calling_convention(code, &instrs, &one);
        assert!(!out.contains("a2"), "phantom parameter invented: {out}");
        // A register already DEFINED before the call is not live-in.
        let defined = vec![
            ins("mov", "$0x5, %edx"),
            ins("sub", "%eax, %ecx"),
            ins("call", "0x0000000140001450"),
        ];
        let out = apply_win64_calling_convention(code, &defined, &arities);
        assert!(!out.contains("a2"), "a locally-defined arg reg must not become a param: {out}");
        // Contiguity: a callee arity of 2 must not conjure a FIRST parameter
        // for a function that reads no argument register of its own.
        let none = vec![ins("call", "0x0000000140001450"), ins("ret", "")];
        let out = apply_win64_calling_convention(code, &none, &arities);
        assert!(!out.contains("a1"), "phantom first parameter invented: {out}");
    }

    #[test]
    fn att_mnemonic_stem_normalises_sized_forms() {
        // The extension family carries two size letters.
        assert_eq!(att_mnemonic_stem("movzwl"), "movzx");
        assert_eq!(att_mnemonic_stem("movzbl"), "movzx");
        assert_eq!(att_mnemonic_stem("movslq"), "movsx");
        assert_eq!(att_mnemonic_stem("movsbl"), "movsx");
        // Single trailing size letter on a known stem.
        assert_eq!(att_mnemonic_stem("movl"), "mov");
        assert_eq!(att_mnemonic_stem("addq"), "add");
        assert_eq!(att_mnemonic_stem("testb"), "test");
        assert_eq!(att_mnemonic_stem("cmpw"), "cmp");
        // SSE and unrelated mnemonics ending in a size letter are untouched.
        for m in ["movsd", "movss", "movaps", "movdqu", "sal", "shl", "call", "imul", "jl", "mul"] {
            assert_eq!(att_mnemonic_stem(m), m, "{m} must not be rewritten");
        }
    }

    #[test]
    fn hlil_duplicate_local_decl_is_dropped() {
        let code = "void f()\n{\n    uint64_t fp;\n    uint64_t fp;\n    fp = 1;\n}\n";
        let out = fix_hlil_local_decls(code);
        assert_eq!(out.matches("uint64_t fp;").count(), 1, "{out}");
    }

    #[test]
    fn hlil_flag_decl_not_placed_after_a_goto() {
        // `goto loc_X;` looks like a 2-token declaration — the synthesised
        // decl must NOT be anchored to it, or it lands after its own uses.
        let code = "void f()\n{\n    uint64_t v1;\n    v1 = flag_df;\n    goto loc_140001050;\n}\n";
        let out = fix_hlil_local_decls(code);
        let decl = out.find("uint64_t flag_df;").expect("no decl");
        let usage = out.find("v1 = flag_df;").expect("no use");
        assert!(decl < usage, "declaration placed after its use: {out}");
    }

    #[test]
    fn hlil_missing_flag_declared_even_after_dedupe() {
        // A duplicate declaration is dropped, which shifts the line indices —
        // the synthesised decl must still land after the real locals.
        let code = "void f()\n{\n    uint64_t fp;\n    uint64_t fp;\n    uint64_t v1;\n    v1 = flag_df;\n}\n";
        let out = fix_hlil_local_decls(code);
        assert!(out.contains("uint64_t flag_df;"), "{out}");
        let decl = out.find("uint64_t flag_df;").unwrap_or(0);
        let usage = out.find("v1 = flag_df;").unwrap_or(0);
        assert!(decl < usage, "declaration after use: {out}");
    }

    #[test]
    fn hlil_missing_flag_gets_declared() {
        let code = "void f()\n{\n    uint64_t v1;\n    v1 = flag_df;\n}\n";
        let out = fix_hlil_local_decls(code);
        assert!(out.contains("uint64_t flag_df;"), "{out}");
    }

    #[test]
    fn hlil_declared_flag_not_duplicated() {
        let code = "void f()\n{\n    uint64_t flag_df;\n    v1 = flag_df;\n}\n";
        let out = fix_hlil_local_decls(code);
        assert_eq!(out.matches("uint64_t flag_df;").count(), 1, "{out}");
    }

    #[test]
    fn hlil_doubled_parens_collapse() {
        // The corpus defect shape: `((((v6 < v2)) == 1) ? v6 : v2)`.
        let code = "v2 = ((((v6 < v2)) == 1) ? v6 : v2);\n";
        let out = collapse_doubled_hlil_parens(code);
        assert_eq!(out, "v2 = (((v6 < v2) == 1) ? v6 : v2);\n");
        // `if ((cond))` collapses too.
        assert_eq!(
            collapse_doubled_hlil_parens("if ((var_tmp0 == 0)) {\n"),
            "if (var_tmp0 == 0) {\n"
        );
        // Triples reach fixpoint.
        assert_eq!(collapse_doubled_hlil_parens("x = (((a + b)));"), "x = (a + b);");
    }

    #[test]
    fn hlil_doubled_parens_collapse_leaves_non_redundant_parens() {
        // Cast application, adjacent groups, call args, string literals.
        for s in [
            "x = ((int64_t)(y));",
            "x = (a)(b);",
            "f((a), (b));",
            "puts(\"((x))\");",
            "x = ((a + b) * (c + d));",
        ] {
            assert_eq!(collapse_doubled_hlil_parens(s), s, "must be unchanged: {s}");
        }
        // Nested call arg `f((x))` IS collapsed — identical semantics.
        assert_eq!(collapse_doubled_hlil_parens("f((x));"), "f(x);");
    }

    #[test]
    fn hlil_unknown_identifier_not_fabricated() {
        // Only `flag_*` is synthesised — a genuine lifting gap must stay visible.
        let code = "void f()\n{\n    v1 = mystery_thing;\n}\n";
        let out = fix_hlil_local_decls(code);
        assert!(!out.contains("uint64_t mystery_thing;"), "{out}");
    }

    #[test]
    fn hlil_deref_casts_static_data_definition() {
        // #5410: con `RUSTRE_EMIT_DATA` il simbolo e' DEFINITO, non `extern`.
        let code = "static __int64 off_140004000 = 0x140001450;\nvoid f()\n{\n    uint64_t v2;\n    v2 = *(off_140004000 + 8);\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("*(__int64 *)(off_140004000 + 8)"), "{out}");
        // RIFIUTO: un puntatore vero non va ri-castato.
        let ptr = "static __int64 *p = 0;\nvoid f()\n{\n    v2 = *p;\n}\n";
        assert_eq!(cast_hlil_integer_derefs(ptr), ptr);
    }

    #[test]
    fn hlil_deref_con_indirizzo_castato_di_un_array() {
        // `(__int64)&off_X` e' un intero PER COSTRUZIONE anche se `off_X` e'
        // un array `uint8_t[64]` (forma emessa da `RUSTRE_EMIT_DATA`), che la
        // raccolta di `ints` non puo' registrare (il nome esce `off_X[64]`).
        let code = "static uint8_t off_1400F5378[64] = { 0x00 };\nvoid f()\n{\n    uint64_t v8;\n    uint64_t v5;\n    v5 = *(v8 + (__int64)&off_1400F5378);\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(
            out.contains("*(__int64 *)(v8 + (__int64)&off_1400F5378)"),
            "{out}"
        );
    }

    #[test]
    fn hlil_deref_array_senza_cast_non_viene_toccato() {
        // ⚠ Il caso che rende la regola sicura: `*(off_X + 1)` su un array di
        // `uint8_t` e' un deref LEGITTIMO a passo 1. Castarlo a `__int64 *`
        // leggerebbe 8 byte invece di 1 — aritmetica sbagliata che COMPILA.
        // Qui manca la forma `)&`, quindi il ramo non deve scattare.
        let code = "static uint8_t off_140001000[64] = { 0x00 };\nvoid f()\n{\n    uint64_t v5;\n    v5 = *(off_140001000 + 1);\n}\n";
        assert_eq!(cast_hlil_integer_derefs(code), code);
    }

    #[test]
    fn hlil_deref_of_numeric_literal_is_cast() {
        let code = "void f()\n{\n    uint64_t v2;\n    v2 = *88;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("v2 = *(__int64 *)88;"), "{out}");
    }

    #[test]
    fn hlil_call_through_dereferenced_slot() {
        let code = "void f()\n{\n    uint64_t v10;\n    *(__int64 *)(v10 + 24)();\n}\n";
        let out = cast_hlil_called_integers(code);
        assert!(out.contains("((__int64 (*)())*(__int64 *)(v10 + 24))()"), "{out}");
    }

    #[test]
    fn hlil_catena_di_cast_non_e_una_chiamata() {
        // `*(__int64 *)(uint64_t)(uint32_t)0 = 0;` e' la scrittura a 0 (crash
        // deliberato di Go): la `(` dopo il load apre un CAST, non una lista
        // di argomenti. Trattarla come chiamata spezzava la catena e produceva
        // `((__int64 (*)())*(__int64 *)(uint64_t))(uint32_t)0 = 0;`, che gcc
        // rifiuta con «expected expression before ')'».
        let code = "void f()\n{\n    *(__int64 *)(uint64_t)(uint32_t)0 = 0;\n}\n";
        let out = cast_hlil_called_integers(code);
        assert!(
            out.contains("*(__int64 *)(uint64_t)(uint32_t)0 = 0;"),
            "{out}"
        );
        assert!(!out.contains("(__int64 (*)())*"), "catena spezzata: {out}");
    }

    #[test]
    fn hlil_plain_deref_load_not_wrapped() {
        // Not followed by `(` — a plain load must stay as it is.
        let code = "void f()\n{\n    uint64_t v10;\n    v1 = *(__int64 *)(v10 + 24);\n}\n";
        let out = cast_hlil_called_integers(code);
        assert!(out.contains("v1 = *(__int64 *)(v10 + 24);"), "{out}");
        assert!(!out.contains("(*)()"), "{out}");
    }

    #[test]
    fn hlil_called_integer_becomes_function_pointer() {
        let code = "void f()\n{\n    uint64_t v6;\n    v6();\n}\n";
        let out = cast_hlil_called_integers(code);
        assert!(out.contains("((__int64 (*)())v6)();"), "{out}");
    }

