    #[test]
    fn hlil_deref_cast_leaves_call_result_multiplication() {
        // `f(x) * v1` is a PRODUCT — the `)` closes a call, not a cast.
        let code = "void f()\n{\n    uint64_t v1;\n    uint64_t a;\n    a = g(a) * v1;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("g(a) * v1"), "call-result product rewritten: {out}");
    }

    #[test]
    fn hlil_deref_cast_leaves_subscript_multiplication() {
        let code = "void f()\n{\n    uint64_t v1;\n    uint64_t a[4];\n    v1 = a[0] * v1;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("a[0] * v1"), "subscript product rewritten: {out}");
    }

    #[test]
    fn hlil_deref_cast_covers_parenthesised_expr() {
        let code = "void f()\n{\n    uint64_t sp;\n    uint64_t v8;\n    v8 = *(sp + 60);\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("*(__int64 *)(sp + 60)"), "{out}");
    }

    #[test]
    fn hlil_deref_cast_ignores_cast_type_names_in_the_index() {
        // `*(v7 + (int64_t)(int32_t)v9 * 8)` — the cast keywords are NOT
        // operands; only v7/v9 must be integers. Before the fix the pass saw
        // `int64_t` ∉ ints and bailed, leaving `*int` → gcc error.
        let code = "void f()\n{\n    uint64_t v7;\n    uint64_t v9;\n    uint64_t v11;\n\
                    v11 = *(v7 + (int64_t)(int32_t)v9 * 8);\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("*(__int64 *)(v7 + (int64_t)(int32_t)v9 * 8)"), "{out}");
    }

    #[test]
    fn hlil_deref_cast_still_skips_when_a_real_pointer_is_present() {
        // `p` is a pointer → casting would drop element scaling → leave alone.
        let code = "void f()\n{\n    __int64 *p;\n    uint64_t v9;\n    uint64_t v11;\n\
                    v11 = *(p + (int32_t)v9);\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(!out.contains("*(__int64 *)(p"), "must not cast a real pointer: {out}");
    }

    #[test]
    fn hlil_deref_cast_skips_expr_holding_a_real_pointer() {
        // `p` is a POINTER: casting would drop its element scaling — silent
        // wrong arithmetic. Must be left untouched.
        let code = "void f()\n{\n    uint64_t *p;\n    uint64_t v;\n    v = *(p + 1);\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("v = *(p + 1);"), "pointer expr rewritten: {out}");
    }

    #[test]
    fn hlil_deref_cast_does_not_double_cast() {
        let code = "void f()\n{\n    uint64_t v;\n    v = *(__int64 *)v;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert_eq!(out.matches("(__int64 *)").count(), 1, "{out}");
    }

    #[test]
    fn hlil_code_pointer_resolves_to_function_symbol() {
        // The three shapes measured on the corpus, plus a control: `off_140009999`
        // is NOT a function start and must survive untouched, declaration included.
        let starts: HashMap<u64, usize> =
            [(0x1_4000_1DE0u64, 0usize), (0x1_4000_6890, 1)].into_iter().collect();
        let code = concat!(
            "extern __int64 off_140001DE0;\n",
            "extern __int64 off_140006890;\n",
            "extern __int64 off_140009999;\n",
            "void f()\n{\n",
            "    v9 = off_140001DE0;\n",
            "    a1 = (a1 + off_140006890);\n",
            "    v2 = off_140009999;\n",
            "}\n",
        );
        // `0x1400_1DE0` carries a recovered symbol, `0x1400_6890` does not: the
        // first must be spelled with the name its definition actually uses.
        // The second address answers with a SYNTHETIC `sub_<hex>` name, which is
        // what the real symbol map does and must NOT be taken as a definition
        // spelling — the emitted C showed that exact mismatch.
        let name_of = |va: u64| {
            Some(if va == 0x1_4000_1DE0 {
                "internal_cpu_doinit".to_string()
            } else {
                format!("sub_{va:X}")
            })
        };
        let out = resolve_hlil_code_pointers(code, &starts, &name_of);
        // Entry points: renamed at the use site AND re-declared as functions.
        assert!(out.contains("__int64 internal_cpu_doinit();\n"), "{out}");
        assert!(out.contains("    v9 = (__int64)internal_cpu_doinit;\n"), "{out}");
        // No recovered symbol -> the DEFINITION spelling `fn_<lowercase hex>`,
        // never `sub_<hex>` (which is not a definition spelling anywhere).
        assert!(out.contains("__int64 fn_140006890();\n"), "{out}");
        assert!(out.contains("    a1 = (a1 + (__int64)fn_140006890);\n"), "{out}");
        assert!(!out.contains("extern __int64 off_140001DE0;"), "{out}");
        // The shape the fixed-list gcc run rejected: an arithmetic use needs the
        // cast, or it is "invalid operands to binary -" on a function designator.
        let arith = "extern __int64 off_140001DE0;\nvoid f()\n{\n    if ((v - off_140001DE0) != 0) {\n    }\n}\n";
        let a_out = resolve_hlil_code_pointers(arith, &starts, &name_of);
        assert!(a_out.contains("(v - (__int64)internal_cpu_doinit)"), "{a_out}");
        // After `&` the cast would be illegal C, so the bare name is used.
        let amp = "extern __int64 off_140001DE0;\nvoid f()\n{\n    v = &off_140001DE0;\n}\n";
        let amp_out = resolve_hlil_code_pointers(amp, &starts, &name_of);
        assert!(amp_out.contains("v = &internal_cpu_doinit;"), "{amp_out}");
        // Self-reference: the text DEFINES the target, so re-declaring it would
        // be "conflicting types" in the same translation unit. Rename, no decl.
        let selfref = concat!(
            "extern __int64 off_140006890;\n",
            "void fn_140006890(uint64_t a1)\n{\n",
            "    a1 = off_140006890;\n}\n",
        );
        let s_out = resolve_hlil_code_pointers(selfref, &starts, &name_of);
        assert!(!s_out.contains("__int64 fn_140006890();"), "{s_out}");
        assert!(s_out.contains("    a1 = (__int64)fn_140006890;\n"), "{s_out}");
        assert!(!s_out.contains("off_140006890"), "{s_out}");
        // Control: not a function start, so nothing about it may change.
        assert!(out.contains("extern __int64 off_140009999;\n"), "{out}");
        assert!(out.contains("    v2 = off_140009999;\n"), "{out}");
    }

    #[test]
    fn hlil_sub_symbols_renamed_to_definition_spelling() {
        let starts: HashMap<u64, usize> =
            [(0x1_4008_9E10u64, 0usize), (0x1_4000_1DE0, 1)].into_iter().collect();
        // Synthetic answer for the first, a real symbol for the second.
        let name_of = |va: u64| {
            Some(if va == 0x1_4000_1DE0 {
                "internal_cpu_doinit".to_string()
            } else {
                format!("sub_{va:X}")
            })
        };
        let code = concat!(
            "__int64 sub_140089E10();\n",
            "__int64 sub_140001DE0();\n",
            "__int64 sub_140099999();\n",
            "void f()\n{\n",
            "    sub_140089E10();\n",
            "    sub_140001DE0(1);\n",
            "    sub_140099999();\n",
            "}\n",
        );
        let out = rename_hlil_sub_symbols(code, &starts, &name_of);
        assert!(out.contains("__int64 fn_140089e10();\n"), "{out}");
        assert!(out.contains("    fn_140089e10();\n"), "{out}");
        assert!(out.contains("__int64 internal_cpu_doinit();\n"), "{out}");
        assert!(out.contains("    internal_cpu_doinit(1);\n"), "{out}");
        // Not a known function start: untouched, declaration included.
        assert!(out.contains("__int64 sub_140099999();\n"), "{out}");
        assert!(out.contains("    sub_140099999();\n"), "{out}");
    }

    /// #1200: quando il `ret` sta in un blocco proprio (misurato: **51.2%** dei
    /// blocchi con `Ret`), il valore di ritorno si perdeva e la firma diventava
    /// `void` (#1160, `find_max` verificata sul SORGENTE). Si riempie dai
    /// predecessori SOLO quando la risposta e' univoca; in conflitto si lascia
    /// il `return;` nudo, che e' onesto.
    #[test]
    fn a_return_takes_rax_from_the_predecessors_only_when_they_agree() {
        use rustre_il_mlil::{MlilAnnotatedInstr, MlilBasicBlock, MlilExpr, MlilInstruction, Size};
        let at = |va: u64| rustre_core::address::Address::new(va);
        let def_rax = |va: u64, ver: &str| MlilAnnotatedInstr {
            address: at(va),
            instr: MlilInstruction::Assign {
                dest: rustre_il_mlil::SsaVar::initial(ver),
                src: MlilExpr::Const { value: va, size: Size::QWord },
                size: Size::QWord,
            },
        };
        let ret = MlilAnnotatedInstr {
            address: at(0x3000),
            instr: MlilInstruction::Ret { values: Vec::new() },
        };
        // due predecessori che definiscono rax, piu' il blocco del solo `ret`.
        let build = |same: bool| {
            vec![
                MlilBasicBlock {
                    id: 0,
                    start: at(0x1000),
                    end: at(0x1008),
                    instrs: vec![def_rax(0x1000, "rax")],
                    predecessors: Vec::new(),
                    successors: vec![2],
                },
                MlilBasicBlock {
                    id: 1,
                    start: at(0x2000),
                    end: at(0x2008),
                    // stessa versione (concordi) oppure una diversa (conflitto)
                    instrs: vec![def_rax(0x2000, if same { "rax" } else { "rbx" })],
                    predecessors: Vec::new(),
                    successors: vec![2],
                },
                MlilBasicBlock {
                    id: 2,
                    start: at(0x3000),
                    end: at(0x3001),
                    instrs: vec![ret.clone()],
                    predecessors: vec![0, 1],
                    successors: Vec::new(),
                },
            ]
        };
        let filled = |blocks: &[MlilBasicBlock]| match &blocks[2].instrs[0].instr {
            MlilInstruction::Ret { values } => values.len(),
            _ => usize::MAX,
        };
        // concordi: il valore si recupera.
        let mut agree = build(true);
        fill_mlil_return_values(&mut agree);
        assert_eq!(filled(&agree), 1, "predecessori concordi: il return prende il valore");
        // in conflitto: NON si sceglie a caso, resta `return;`.
        let mut differ = build(false);
        fill_mlil_return_values(&mut differ);
        assert_eq!(filled(&differ), 0, "in conflitto NON si inventa una versione");

        // #1230: catena PROFONDA — il predecessore immediato non definisce
        // `rax`, ma il suo predecessore si'. Un livello solo non bastava.
        let mut deep = vec![
            MlilBasicBlock {
                id: 0,
                start: at(0x1000),
                end: at(0x1008),
                instrs: vec![def_rax(0x1000, "rax")],
                predecessors: Vec::new(),
                successors: vec![1],
            },
            MlilBasicBlock {
                id: 1,
                start: at(0x2000),
                end: at(0x2008),
                instrs: Vec::new(), // nessuna definizione: si deve risalire
                predecessors: vec![0],
                successors: vec![2],
            },
            MlilBasicBlock {
                id: 2,
                start: at(0x3000),
                end: at(0x3001),
                instrs: vec![ret.clone()],
                predecessors: vec![1],
                successors: Vec::new(),
            },
        ];
        // ⚠ il clone va preso PRIMA di riempire: `fill_...` MUTA `deep`, e su un
        // `Ret` gia' pieno la funzione non interviene (il test fallirebbe per
        // un difetto del test, non del codice — successo davvero, #1230).
        let mut dead = deep.clone();
        fill_mlil_return_values(&mut deep);
        assert_eq!(filled(&deep), 1, "la risalita attraversa un blocco senza rax");

        // VICOLO CIECO: un cammino risale fino a un blocco iniziale che `rax`
        // non lo definisce mai ⇒ su quel cammino il valore e' INDEFINITO e non
        // si restituisce nulla.
        dead[0].instrs.clear();
        fill_mlil_return_values(&mut dead);
        assert_eq!(filled(&dead), 0, "cammino senza rax: non si restituisce un indefinito");
    }

    /// #1310: un `jmp` FUORI dalla funzione e' una tail call e va promosso, uno
    /// INTERNO no — promuoverlo inventerebbe una chiamata che non esiste.
    #[test]
    fn only_a_jump_out_of_the_function_becomes_a_tail_call() {
        use rustre_il_mlil::{MlilAnnotatedInstr, MlilBasicBlock, MlilExpr, MlilInstruction, Size};
        let jump_to = |va: u64| MlilAnnotatedInstr {
            address: rustre_core::address::Address::new(0x1000),
            instr: MlilInstruction::Jump {
                dest: MlilExpr::Const { value: va, size: Size::QWord },
            },
        };
        let block = |va: u64| MlilBasicBlock {
            id: 0,
            start: rustre_core::address::Address::new(0x1000),
            end: rustre_core::address::Address::new(0x1010),
            instrs: vec![jump_to(va)],
            predecessors: Vec::new(),
            successors: Vec::new(),
        };
        let is_tail = |bs: &[MlilBasicBlock]| {
            matches!(bs[0].instrs[0].instr, MlilInstruction::TailCall { .. })
        };
        // fuori dal range [0x1000, 0x1010]: e' una tail call.
        let out = promote_outward_jumps_to_tail_calls(vec![block(0x2000)], 0x1000, 0x1010);
        assert!(is_tail(&out), "un salto FUORI dalla funzione e' una tail call");
        // dentro il range: resta un salto.
        let inside = promote_outward_jumps_to_tail_calls(vec![block(0x1008)], 0x1000, 0x1010);
        assert!(!is_tail(&inside), "un salto INTERNO non va promosso a chiamata");

    }

    #[test]
    fn mlil_call_args_come_only_from_the_arity_map() {
        use rustre_il_mlil::{MlilAnnotatedInstr, MlilBasicBlock, MlilExpr, MlilInstruction, Size};
        let call = |va: u64| MlilAnnotatedInstr {
            address: rustre_core::address::Address::new(va),
            instr: MlilInstruction::Call {
                dest: MlilExpr::Const { value: va, size: Size::QWord },
                args: Vec::new(),
                ret_vars: Vec::new(),
            },
        };
        let set = |r: &str| MlilAnnotatedInstr {
            address: rustre_core::address::Address::new(0x900),
            instr: MlilInstruction::Assign {
                dest: rustre_il_mlil::SsaVar::initial(r),
                src: MlilExpr::Const { value: 0, size: Size::QWord },
                size: Size::QWord,
            },
        };
        let mut blocks = vec![MlilBasicBlock {
            id: 0,
            start: rustre_core::address::Address::new(0x1000),
            end: rustre_core::address::Address::new(0x1010),
            // The function must MENTION the argument registers, or the arity is
            // clamped: a caller that never touches r9 cannot be passing a 4th
            // argument. Here all four are set up, so nothing is clamped.
            // Ogni chiamata prepara i PROPRI argomenti: una call CLOBBERA i
            // registri volatili, quindi lo staging non si eredita dalla call
            // precedente (ed e' cosi' che il codice reale e' fatto).
            instrs: vec![
                set("rcx"), set("rdx"), set("r8"), set("r9"),
                call(0x2000),
                set("rcx"), set("rdx"), set("r8"), set("r9"),
                call(0x3000),
                set("rcx"), set("rdx"), set("r8"), set("r9"),
                call(0x4000),
                set("rcx"), set("rdx"), set("r8"), set("r9"),
                call(0x5000),
            ],
            predecessors: Vec::new(),
            successors: Vec::new(),
        }];
        // arity 0, 2, 6 (clamped to the 4 register slots), and one ABSENT target.
        let arities: HashMap<u64, usize> =
            [(0x2000u64, 0usize), (0x3000, 2), (0x4000, 6)].into_iter().collect();
        fill_mlil_call_args(&mut blocks, &arities);
        let argc = |i: usize| match &blocks[0].instrs[i].instr {
            MlilInstruction::Call { args, .. } => args.len(),
            _ => usize::MAX,
        };
        assert_eq!(argc(4), 0, "arita' 0");
        assert_eq!(argc(9), 2, "arita' 2");
        assert_eq!(argc(14), 4, "arita' 6 va tagliata ai 4 registri");
        // Absent from the map: zero arguments, never a phantom.
        assert_eq!(argc(19), 0, "target sconosciuto");
        // And the two it did fill carry the ABI registers, in order.
        let MlilInstruction::Call { args, .. } = &blocks[0].instrs[9].instr else {
            unreachable!()
        };
        let names: Vec<String> = args
            .iter()
            .map(|a| match a {
                MlilExpr::Var { var, .. } => var.name.clone(),
                _ => String::new(),
            })
            .collect();
        assert_eq!(names, vec!["rcx".to_string(), "rdx".to_string()]);
    }

    #[test]
    fn mlil_call_args_clamped_to_registers_the_caller_touches() {
        use rustre_il_mlil::{MlilAnnotatedInstr, MlilBasicBlock, MlilExpr, MlilInstruction, Size};
        // The caller sets up rcx and rdx only. The map claims arity 4 — that is
        // the shape that produced 417 calls passing more arguments than the
        // callee declares. A function that never touches r8/r9 cannot be
        // passing a 3rd or 4th argument, so the arity is clamped to 2.
        let set = |r: &str| MlilAnnotatedInstr {
            address: rustre_core::address::Address::new(0x900),
            instr: MlilInstruction::Assign {
                dest: rustre_il_mlil::SsaVar::initial(r),
                src: MlilExpr::Const { value: 0, size: Size::QWord },
                size: Size::QWord,
            },
        };
        let mut blocks = vec![MlilBasicBlock {
            id: 0,
            start: rustre_core::address::Address::new(0x1000),
            end: rustre_core::address::Address::new(0x1010),
            instrs: vec![
                set("rcx"),
                set("rdx"),
                MlilAnnotatedInstr {
                    address: rustre_core::address::Address::new(0x1004),
                    instr: MlilInstruction::Call {
                        dest: MlilExpr::Const { value: 0x2000, size: Size::QWord },
                        args: Vec::new(),
                        ret_vars: Vec::new(),
                    },
                },
            ],
            predecessors: Vec::new(),
            successors: Vec::new(),
        }];
        let arities: HashMap<u64, usize> = [(0x2000u64, 4usize)].into_iter().collect();
        fill_mlil_call_args(&mut blocks, &arities);
        let MlilInstruction::Call { args, .. } = &blocks[0].instrs[2].instr else {
            unreachable!()
        };
        assert_eq!(args.len(), 2, "arita' 4 tagliata a 2: r8/r9 mai toccati");
    }

    #[test]
    fn dead_call_result_assignment_becomes_a_statement() {
        let code = concat!(
            "void f()\n{\n",
            // Le DICHIARAZIONI non contano come uso: contarle rendeva ogni
            // locale "usata altrove" e la passata diventava un no-op.
            "    uint64_t v1;\n    uint64_t v2;\n    uint64_t v10;\n",
            "    v1 = fn_140052140(a1);\n",   // mai letta -> statement
            "    v2 = fn_140001000();\n",     // letta sotto -> intatta
            "    v10 = fn_140002000();\n",    // `v1` non deve agganciare `v10`
            "    g(v2);\n",
            "    h(v10);\n",
            "}\n",
        );
        let out = drop_dead_call_result_assignments(code);
        assert!(out.contains("    fn_140052140(a1);\n"), "{out}");
        // Forma a CICLO: la variabile e' letta PRIMA dell'assegnazione. Guardare
        // solo in avanti la giudicherebbe morta e lascerebbe il lettore senza
        // definizione (costo misurato: +2 residui).
        let loopy = concat!(
            "void f()\n{\n",
            "    while (1) {\n",
            "        g(v3);\n",
            "        v3 = fn_140003000();\n",
            "    }\n}\n",
        );
        let lo = drop_dead_call_result_assignments(loopy);
        assert!(lo.contains("        v3 = fn_140003000();\n"), "{lo}");
        assert!(!out.contains("v1 = fn_140052140"), "{out}");
        assert!(out.contains("    v2 = fn_140001000();\n"), "{out}");
        assert!(out.contains("    v10 = fn_140002000();\n"), "{out}");
    }

    #[test]
    fn void_hlil_signature_gets_the_return_type_the_body_produces() {
        // Il predicato e' quello di A (`scan_accumulator_writes`), quindi qui si
        // verifica solo che il TIPO venga scambiato sulla riga giusta: la firma,
        // non un cast `(void *)` ne' una dichiarazione che finisce con `;`.
        let code = concat!(
            "__int64 fn_140001000();
",
            "void fn_140002000(uint64_t a1)
{
",
            "    v1 = (void *)a1;
",
            "    return v1;
",
            "}
",
        );
        let insns = vec![make_instr(0x1000, "mov", "%eax, %ecx"), make_instr(0x1003, "ret", "")];
        let out = retype_void_hlil_signature(code, &insns);
        assert!(out.contains("int fn_140002000(uint64_t a1)
"), "{out}");
        // Il cast resta intatto, e la dichiarazione sopra pure.
        assert!(out.contains("    v1 = (void *)a1;
"), "{out}");
        assert!(out.contains("__int64 fn_140001000();
"), "{out}");
    }

    #[test]
    fn a_non_void_function_gets_its_missing_tail_return() {
        // #1080: cadere fuori da una funzione non-void e' comportamento
        // indefinito. Misurato: 249 casi, TUTTI solo su B (path A: 0).
        let code = concat!(
            "__int64 f(void)
{
",
            "    uint64_t v3;
",
            "    v3 = sub_A();
",
            "}
",
        );
        let out = append_missing_tail_return(code);
        assert!(out.contains("return v3;"), "manca il return di coda: {out}");
        // Una `void` non va toccata: li' cadere in fondo e' LEGALE.
        let v = "void g(void)
{
    v1 = sub_A();
}
";
        assert_eq!(append_missing_tail_return(v), v, "una void non si tocca");
        // Chi gia' termina non va toccato.
        let r = "__int64 h(void)
{
    return 1;
}
";
        assert_eq!(append_missing_tail_return(r), r, "gia' terminata");
    }

    #[test]
    fn a_redefinition_is_not_an_inlining_site() {
        // #1050: se la riga dopo RIDEFINISCE il temporaneo, quella occorrenza
        // e' un BERSAGLIO, non un uso. Inlinarla produceva `(f(a2)) = g();`
        // — `lvalue required` — e cancellava la riga definitoria, quindi UNA
        // CHIAMATA SPARIVA. Misurato: 4 file su 11144, ora 0.
        let code = concat!(
            "void f(uint64_t a2)
{
",
            "    v1 = sub_A(a2);
",
            "    v1 = sub_B();
",
            "    return;
}
",
        );
        let out = inline_hlil_single_use_temps(code);
        assert!(
            !out.contains(") = "),
            "nessuna chiamata deve finire a sinistra: {out}"
        );
        assert!(out.contains("sub_A(a2)"), "la prima chiamata deve restare: {out}");
        assert!(out.contains("sub_B()"), "la seconda chiamata deve restare: {out}");
    }

    #[test]
    fn a_crt_forward_decl_is_dropped_not_the_call() {
        // #960: la rinomina dei simboli trasforma `__int64 sub_140001010();`
        // in `__int64 _set_invalid_parameter_handler();`, che confligge col
        // prototipo vero (il prelude include l'header). Si toglie la sola
        // DICHIARAZIONE: l'uso resta e il prototipo giusto arriva dall'header.
        let code = concat!(
            "__int64 _set_invalid_parameter_handler();
",
            "__int64 sub_140002000();
",
            "__int64 f(void)
{
",
            "    return _set_invalid_parameter_handler(0);
}
",
        );
        let out = drop_conflicting_crt_forward_decls(code);
        assert!(
            !out.contains("__int64 _set_invalid_parameter_handler();"),
            "la dichiarazione in conflitto deve sparire: {out}"
        );
        assert!(
            out.contains("return _set_invalid_parameter_handler(0);"),
            "l'USO deve restare: {out}"
        );
        assert!(
            out.contains("__int64 sub_140002000();"),
            "una forward decl legittima non si tocca: {out}"
        );
        // #1100: `return <nome>();` NON e' una dichiarazione. Prima veniva
        // cancellata e la funzione restava con il corpo VUOTO (84 casi).
        let r = concat!(
            "__int64 f(uint64_t a1)
{
",
            "    return __gcc_register_frame();
}
",
        );
        assert_eq!(
            drop_conflicting_crt_forward_decls(r),
            r,
            "un return non e' una dichiarazione"
        );
    }

    #[test]
    fn a_control_flow_statement_is_not_a_declaration() {
        // #930: `return v1;` e `goto loc_X;` finiscono con ';', non hanno '='
        // ne' '(' e sono fatti di 2 parole — il predicato di dichiarazione li
        // prendeva per tali e cancellava ogni occorrenza dopo la prima come
        // "duplicato". Misurato: 1449 `return` e 658 `goto` eliminati su UN
        // binario, con salti in avanti di ~93 righe che sparivano ⇒ il codice
        // cadeva nell'`else` invece di saltare. Silenziosamente SBAGLIATO.
        let code = concat!(
            "__int64 f(void)
{
",
            "    uint64_t v1;
",
            "    if (v1 == 0) {
        goto loc_1;
    }
",
            "    if (v1 == 1) {
        goto loc_1;
    }
",
            "    return v1;
",
            "    return v1;
",
            "loc_1:
    return v1;
}
",
        );
        let out = fix_hlil_local_decls(code);
        assert_eq!(
            out.matches("goto loc_1;").count(),
            2,
            "un goto duplicato NON e' una dichiarazione duplicata: {out}"
        );
        assert_eq!(
            out.matches("return v1;").count(),
            3,
            "un return duplicato NON e' una dichiarazione duplicata: {out}"
        );
    }

    #[test]
    fn void_signature_is_kept_when_no_return_carries_a_value() {
        // Contratto STRETTO di proposito (#870): una firma non-void deve avere
        // per COSTRUZIONE almeno un `return <valore>;`. Prima bastava che le
        // istruzioni scrivessero rax, e il risultato era una firma che nessun
        // `return` onorava — misurato su `sample10_cs`: 2057 funzioni promosse
        // contro le 345 del controllo, scese a 483 con questa guardia.
        let code = concat!(
            "void fn_140002000(uint64_t a1)
{
",
            "    v1 = (void *)a1;
",
            "    return;
",
            "}
",
        );
        let insns = vec![make_instr(0x1000, "mov", "%eax, %ecx"), make_instr(0x1003, "ret", "")];
        let out = retype_void_hlil_signature(code, &insns);
        assert_eq!(out, code, "un `return;` nudo non giustifica una firma non-void");
    }

    #[test]
    fn duplicate_forward_declarations_collapse() {
        let code = concat!(
            "__int64 fn_140012db0();
",
            "__int64 fn_140012db0();
",   // ripetuta identica -> via
            "__int64 fn_140099999();
",   // diversa -> resta
            "void f()
{
    fn_140012db0();
}
",
        );
        let out = drop_duplicate_forward_decls(code);
        assert_eq!(out.matches("__int64 fn_140012db0();").count(), 1, "{out}");
        assert!(out.contains("__int64 fn_140099999();"), "{out}");
        // L'ordine delle dichiarazioni non cambia: la PRIMA resta al suo posto.
        assert!(
            out.find("fn_140012db0();").unwrap() < out.find("fn_140099999();").unwrap(),
            "{out}"
        );
    }

    #[test]
    fn unused_local_declarations_are_dropped() {
        let code = concat!(
            "void f()\n{\n",
            "    uint64_t v1;\n",           // mai usata -> via
            "    uint64_t v2;\n",           // usata sotto -> resta
            "    uint64_t v10;\n",          // `v1` non deve agganciare `v10`
            "    uint64_t sp;\n",           // stato macchina -> resta
            "    uint64_t v3 = 7;\n",       // ha inizializzatore -> resta
            "    v2 = 1;\n",
            "    g(v10);\n",
            "}\n",
        );
        let out = drop_unused_local_declarations(code);
        assert!(!out.contains("uint64_t v1;"), "{out}");
        assert!(out.contains("    uint64_t v2;\n"), "{out}");
        assert!(out.contains("    uint64_t v10;\n"), "{out}");
        assert!(out.contains("    uint64_t sp;\n"), "{out}");
        assert!(out.contains("    uint64_t v3 = 7;\n"), "{out}");
    }

    #[test]
    fn hlil_sub_symbols_skip_self_definition() {
        // The text DEFINES the target, so re-declaring it is `conflicting types`.
        let starts: HashMap<u64, usize> = [(0x1_4000_6890u64, 0usize)].into_iter().collect();
        let code = concat!(
            "__int64 sub_140006890();\n",
            "void fn_140006890(uint64_t a1)\n{\n",
            "    sub_140006890();\n}\n",
        );
        // The recursive call keeps `sub_`: renaming it would sit next to the real
        // prototype and expose the emitter's dropped arguments as invalid C.
        let out = rename_hlil_sub_symbols(code, &starts, &|_| None);
        assert_eq!(out, code, "un'auto-definizione non va toccata\n{out}");
    }

    #[test]
    fn hlil_code_pointer_leaves_unknown_addresses_alone() {
        // An empty start set is the no-oracle case: the text must be byte-identical.
        let code = "void f()\n{\n    v9 = off_140001DE0;\n}\n";
        assert_eq!(resolve_hlil_code_pointers(code, &HashMap::new(), &|_| None), code);
    }

    #[test]
    fn hlil_called_symbol_declared_as_function() {
        let code = "void f()\n{\n    sub_140002640();\n}\n";
        let out = prepend_hlil_externs(code, None, false, &[], false);
        assert!(out.starts_with("__int64 sub_140002640();\n"), "{out}");
        assert!(!out.contains("extern __int64 sub_140002640;"), "{out}");
    }

    #[test]
    fn hlil_data_symbol_stays_extern() {
        let code = "void f()\n{\n    v1 = off_140004420;\n}\n";
        let out = prepend_hlil_externs(code, None, false, &[], false);
        assert!(out.starts_with("extern __int64 off_140004420;\n"), "{out}");
    }

    #[test]
    fn hlil_symbol_used_both_ways_prefers_function() {
        let code = "void f()\n{\n    v1 = &sub_X1;\n    sub_X1();\n}\n";
        let out = prepend_hlil_externs(code, None, false, &[], false);
        assert!(out.contains("__int64 sub_X1();"), "{out}");
        assert!(!out.contains("extern __int64 sub_X1;"), "{out}");
    }

    #[test]
    fn hlil_single_use_temp_is_inlined() {
        let code = "void f()\n{\n    uint64_t t;\n    t = a + 1;\n    b = t;\n}\n";
        let out = inline_hlil_single_use_temps(code);
        assert!(out.contains("b = (a + 1);"), "{out}");
        assert!(!out.contains("uint64_t t;"), "decl kept: {out}");
    }

    #[test]
    fn hlil_temp_used_twice_is_kept() {
        let code = "void f()\n{\n    uint64_t t;\n    t = a + 1;\n    b = t;\n    c = t;\n}\n";
        let out = inline_hlil_single_use_temps(code);
        assert!(out.contains("t = a + 1;"), "multi-use temp inlined: {out}");
    }

    #[test]
    fn hlil_temp_used_far_away_is_kept() {
        // Use is NOT on the next line — an intervening statement could change
        // the operands, so folding would be unsound.
        let code = "void f()\n{\n    uint64_t t;\n    t = a + 1;\n    a = 9;\n    b = t;\n}\n";
        let out = inline_hlil_single_use_temps(code);
        assert!(out.contains("t = a + 1;"), "unsound fold across a write: {out}");
    }

    #[test]
    fn hlil_call_temp_is_kept() {
        // A call has side effects; folding it changes evaluation order.
        let code = "void f()\n{\n    uint64_t t;\n    t = g();\n    b = t;\n}\n";
        let out = inline_hlil_single_use_temps(code);
        assert!(out.contains("t = g();"), "call folded: {out}");
    }

    /// Due inline che si TOCCANO non devono lasciare un nome usato e mai
    /// dichiarato. Testo reale ridotto da `sample4_go/sub_140002d20`, dove
    /// questa catena produceva `'v1' undeclared` (gcc) su 6 file.
    #[test]
    fn a_chain_of_inlines_never_leaves_a_name_undeclared() {
        let code = concat!(
            "void f()\n{\n",
            "    uint64_t v1;\n    uint64_t v2;\n    uint64_t v3;\n    uint64_t var_tmp0;\n\n",
            "    v1 = *(__int64 *)v2;\n",
            "    var_tmp0 = (*(__int64 *)v3 - v1);\n",
            "    v2 = (var_tmp0 == 0);\n}\n"
        );
        let out = inline_hlil_single_use_temps(code);
        // INVARIANTE POSITIVA: ogni `vN` che il testo USA deve restare
        // DICHIARATO. Non basta che la passata "non esploda".
        for name in ["v1", "v2", "v3"] {
            let used = out
                .lines()
                .any(|l| l.contains(name) && !l.trim_start().starts_with("uint64_t"));
            let declared = out.lines().any(|l| l.trim() == format!("uint64_t {name};"));
            assert!(
                declared || !used,
                "{name} usato senza dichiarazione:\n{out}"
            );
        }
    }

    /// Testo REALE ridotto da `sample4_go/sub_140001620`. Il registro di
    /// contesto va dichiarato `extern`, non lasciato locale non inizializzato;
    /// e la passata NON deve toccare un nome usato anche altrove.
    #[test]
    fn the_thread_context_register_becomes_extern_only_when_used_solely_as_the_guard() {
        // SAFETY: test a thread singolo; il gate legge una `OnceLock`.
        unsafe { std::env::set_var("RUSTRE_THREAD_CTX_REG", "1") };
        let guard_only = concat!(
            "void f()
{
",
            "    uint64_t v1;
    uint64_t sp;

",
            "    var_tmp0 = (sp - *(__int64 *)(v1 + 16));
",
            "    if (sp <= *(__int64 *)(v1 + 16)) {
        return;
    }
}
"
        );
        let out = rewrite_thread_context_register(guard_only);
        if thread_ctx_reg_enabled() {
            assert!(out.contains("extern uint64_t __thread_context;"), "{out}");
            assert!(!out.contains("uint64_t v1;"), "la locale deve sparire: {out}");
            assert!(out.contains("*(__int64 *)(__thread_context + 16)"), "{out}");
        }
        // Controllo NEGATIVO: se il nome serve anche ad altro NON e' il registro
        // di contesto e va lasciato stare.
        let also_other = concat!(
            "void f()
{
",
            "    uint64_t v1;

",
            "    var_tmp0 = (sp - *(__int64 *)(v1 + 16));
",
            "    v2 = (v1 + 8);
}
"
        );
        let out2 = rewrite_thread_context_register(also_other);
        assert!(out2.contains("uint64_t v1;"), "non deve riscrivere: {out2}");
    }

    /// Il FRAME POINTER non e' mai il registro di contesto: tutti e QUATTRO i
    /// falsi positivi misurati fuori da Go erano `fp` (`mov 0x10(%rbp),…`), il
    /// cui unico uso ha per caso la forma della guardia.
    #[test]
    fn the_frame_pointer_is_never_taken_for_the_thread_context_register() {
        // SAFETY: test a thread singolo; il gate legge una `OnceLock`.
        unsafe { std::env::set_var("RUSTRE_THREAD_CTX_REG", "1") };
        let code = concat!(
            "void f()
{
",
            "    uint64_t fp;

",
            "    a1 = *(__int64 *)(fp + 16);
}
"
        );
        let out = rewrite_thread_context_register(code);
        assert!(out.contains("uint64_t fp;"), "fp non va riscritto: {out}");
        assert!(!out.contains("__thread_context"), "{out}");
    }

    /// L'istruzione va TENUTA, non cancellata: sparisce solo il risultato
    /// morto con la sua lista di argomenti. Testo reale ridotto da
    /// `sample10_cs/sub_1400a0cbb`.
    #[test]
    fn a_dead_pure_intrinsic_keeps_the_instruction_and_loses_only_the_noise() {
        // SAFETY: test a thread singolo; il gate legge una `OnceLock`.
        unsafe { std::env::set_var("RUSTRE_DROP_PURE_INTRINSICS", "1") };
        let code = "void f()\n{\n    uint64_t var_zmm0;\n    uint64_t var_xmm0;\n\n    var_zmm0 = vzero_zmm0(var_xmm0, var_xmm1);\n}\n";
        let out = drop_dead_pure_intrinsics(code);
        if drop_pure_intrinsics_enabled() {
            assert!(out.contains("vzero_zmm0();"), "l'istruzione resta: {out}");
            assert!(!out.contains("var_zmm0 ="), "il risultato morto sparisce: {out}");
            assert!(!out.contains("vzero_zmm0(var_xmm0"), "gli argomenti spariscono: {out}");
        }
        // Se il risultato SERVE, non si tocca nulla.
        let live = "void f()\n{\n    uint64_t var_zmm0;\n\n    var_zmm0 = vzero_zmm0(var_xmm0);\n    a1 = var_zmm0;\n}\n";
        let out2 = drop_dead_pure_intrinsics(live);
        assert!(out2.contains("var_zmm0 = vzero_zmm0(var_xmm0);"), "{out2}");
    }

    #[test]
    fn hlil_unused_label_is_dropped() {
        let code = "void f()\n{\nloc_140001050:\n    return;\n}\n";
        let out = drop_unused_hlil_labels(code);
        assert!(!out.contains("loc_140001050:"), "{out}");
    }

    #[test]
    fn hlil_used_label_is_kept() {
        let code = "void f()\n{\n    goto loc_140001050;\nloc_140001050:\n    return;\n}\n";
        let out = drop_unused_hlil_labels(code);
        assert!(out.contains("loc_140001050:"), "used label dropped: {out}");
    }

    #[test]
    fn hlil_label_drop_ignores_similar_lines() {
        // A statement ending in `:` that is not a label must survive.
        let code = "void f()\n{\n    x = a ? b : c;\n}\n";
        assert_eq!(drop_unused_hlil_labels(code), code);
    }

    #[test]
    fn hlil_deref_cast_covers_multiplication_operand() {
        // `*(v7 * 8)` is a deref of a PRODUCT, not a cast — must be cast.
        let code = "void f()\n{\n    uint64_t v7;\n    *(v7 * 8) = 0;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("*(__int64 *)(v7 * 8)"), "product not cast: {out}");
    }

    #[test]
    fn hlil_deref_cast_leaves_existing_cast_alone() {
        // A real cast ends with `*` — must not be double-cast.
        let code = "void f()\n{\n    uint64_t v1;\n    v2 = *(__int64 *)v1;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert_eq!(out.matches("(__int64 *)").count(), 1, "double cast: {out}");
    }

    #[test]
    fn hlil_deref_cast_covers_negative_literal() {
        // `*-<literal>` is a deref of an absolute address that lifted negative.
        let code = "void f()\n{\n    uint64_t v2;\n    v2 = *-4568365269872803840;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(
            out.contains("*(__int64 *)-4568365269872803840"),
            "negative literal deref not cast: {out}"
        );
    }

    #[test]
    fn hlil_deref_cast_leaves_negated_variable_alone() {
        // `*-v1` is not a literal — this branch must not swallow it.
        let code = "void f()\n{\n    uint64_t v1;\n    v2 = *-v1;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(!out.contains("*(__int64 *)-v1"), "negated var mis-cast: {out}");
    }

    #[test]
    fn hlil_wide_256_type_narrows_when_scalar_only() {
        let code = "void f()\n{\n    uint256_t var_ymm0;\n    var_ymm0 = (a & b);\n}\n";
        let out = normalize_hlil_type_names(code);
        assert!(!out.contains("uint256_t"), "256-bit spelling left: {out}");
        assert!(out.contains("__int64 var_ymm0;"), "not narrowed: {out}");
    }

    #[test]
    fn hlil_wide_256_type_kept_when_intrinsics_present() {
        // A real vector computation must NOT be narrowed — gate on `_mm`.
        let code = "void f()\n{\n    uint256_t var_ymm0;\n    v = _mm_add_epi64(a, b);\n}\n";
        let out = normalize_hlil_type_names(code);
        assert!(out.contains("uint256_t"), "narrowed despite intrinsics: {out}");
    }

    #[test]
    fn hlil_128_bit_map_still_applies_with_intrinsics() {
        // The 128-bit mapping is unconditional; the gate is 256-bit only.
        let code = "void f()\n{\n    uint128_t x;\n    v = _mm_add_epi64(a, b);\n}\n";
        let out = normalize_hlil_type_names(code);
        assert!(out.contains("unsigned __int128 x;"), "{out}");
    }

    #[test]
    fn hlil_declaration_after_use_is_hoisted() {
        // `flag_df` used on line 3 but declared on line 5 → move the decl up.
        let code = "void f()\n{\n    v1 = (flag_df == 1);\n    v2 = 0;\n    uint64_t flag_df;\n}\n";
        let out = hoist_late_hlil_decls(code);
        let decl = out.find("uint64_t flag_df;").expect("decl kept");
        let use_at = out.find("flag_df == 1").expect("use kept");
        assert!(decl < use_at, "declaration must precede its use: {out}");
        assert_eq!(out.matches("uint64_t flag_df;").count(), 1, "duplicated: {out}");
        assert!(out.contains("v2 = 0;"), "other lines preserved: {out}");
    }

    #[test]
    fn hlil_declaration_before_use_is_untouched() {
        // Already in order → byte-identical (the common case).
        let code = "void f()\n{\n    uint64_t flag_df;\n    v1 = (flag_df == 1);\n}\n";
        assert_eq!(hoist_late_hlil_decls(code), code);
    }

    #[test]
    fn hlil_hoist_ignores_substring_names() {
        // `flag_d` must not count as a use of `flag_df`.
        let code = "void f()\n{\n    v1 = flag_d;\n    uint64_t flag_df;\n}\n";
        assert_eq!(hoist_late_hlil_decls(code), code);
    }

    #[test]
    fn hlil_definition_gets_the_recovered_symbol() {
        let code = "__int64 fn_14001bd70(uint64_t a1)\n{\n    return 0;\n}\n";
        let out = apply_recovered_hlil_name(code, 0x1_4001_bd70, "pthread_condattr_init");
        assert!(out.contains("__int64 pthread_condattr_init(uint64_t a1)"), "{out}");
    }

    #[test]
    fn hlil_name_skips_synthetic_placeholders() {
        // `sub_<addr>` is the placeholder in another spelling — adopting it
        // clashes with the forward declaration the file already emits.
        let code = "void fn_14001bd70()\n{\n}\n";
        assert_eq!(apply_recovered_hlil_name(code, 0x1_4001_bd70, "sub_14001bd70"), code);
    }

    #[test]
    fn hlil_name_skips_names_the_prelude_declares() {
        // Adopting `atexit` puts our signature next to the header's prototype.
        let code = "void fn_14001bd70()\n{\n}\n";
        assert_eq!(apply_recovered_hlil_name(code, 0x1_4001_bd70, "atexit"), code);
    }

    #[test]
    fn hlil_void_header_widens_when_body_returns_a_value() {
        let code = "void fn_14001bd70(uint64_t a1)\n{\n    return sub_140001040();\n}\n";
        let out = widen_void_returning_hlil_header(code);
        assert!(out.starts_with("__int64 fn_14001bd70(uint64_t a1)"), "{out}");
    }

    #[test]
    fn hlil_void_header_stays_void_on_bare_return() {
        // `return;` returns nothing — the function really is void.
        let code = "void fn_14001bd70()\n{\n    return;\n}\n";
        assert_eq!(widen_void_returning_hlil_header(code), code);
    }

    #[test]
    fn hlil_void_widening_leaves_forward_decls_alone() {
        let code = "void fn_140009999();\nvoid fn_14001bd70()\n{\n    return sub_1();\n}\n";
        let out = widen_void_returning_hlil_header(code);
        assert!(out.contains("void fn_140009999();"), "forward decl touched: {out}");
        assert!(out.contains("__int64 fn_14001bd70()"), "{out}");
    }

    #[test]
    fn hlil_folds_adjacent_temp_into_its_use() {
        let code = "void f()\n{\n    var_tmp0 = v1;\n    if (var_tmp0 != 0) {\n    }\n}\n";
        let out = inline_adjacent_hlil_temps(code);
        assert!(out.contains("if (v1 != 0) {"), "not folded: {out}");
        assert!(!out.contains("var_tmp0"), "definition kept: {out}");
    }

    #[test]
    fn hlil_fold_parenthesises_compound_expressions() {
        // Without parens this would reassociate into `*(__int64 *)sp + 8 = 1`.
        let code = "void f()\n{\n    var_tmp0 = sp + 8;\n    *(__int64 *)var_tmp0 = 1;\n}\n";
        let out = inline_adjacent_hlil_temps(code);
        assert!(out.contains("*(__int64 *)(sp + 8) = 1;"), "bad fold: {out}");
    }

    #[test]
    fn hlil_fold_never_targets_a_redefinition() {
        // The next line REASSIGNS the temp — folding would emit
        // `(sp + 8) = 5;`, which is not an lvalue. Caught in the corpus.
        let code = "void f()\n{\n    var_tmp0 = sp + 8;\n    var_tmp0 = 5;\n}\n";
        assert_eq!(inline_adjacent_hlil_temps(code), code);
    }

    #[test]
    fn hlil_fold_does_not_double_wrap() {
        let code = "void f()\n{\n    var_tmp0 = (sp - 56);\n    sp = var_tmp0;\n}\n";
        let out = inline_adjacent_hlil_temps(code);
        assert!(out.contains("sp = (sp - 56);"), "double-wrapped: {out}");
    }

    #[test]
    fn hlil_fold_wraps_when_parens_are_not_enclosing() {
        // `(a) + (b)` is NOT an enclosed expression — it still needs wrapping.
        let code = "void f()\n{\n    var_tmp0 = (a) + (b);\n    x = var_tmp0 * 2;\n}\n";
        let out = inline_adjacent_hlil_temps(code);
        assert!(out.contains("x = ((a) + (b)) * 2;"), "lost precedence: {out}");
    }

    #[test]
    fn hlil_fold_never_enters_a_loop_header() {
        // A `while` re-evaluates its condition — folding a call in would turn
        // one evaluation into many.
        let code = "void f()\n{\n    var_tmp0 = next();\n    while (var_tmp0 != 0) {\n    }\n}\n";
        assert_eq!(inline_adjacent_hlil_temps(code), code);
    }

    #[test]
    fn hlil_fold_skips_temps_used_twice() {
        let code = "void f()\n{\n    var_tmp0 = v1;\n    x = (var_tmp0 + var_tmp0);\n}\n";
        assert_eq!(inline_adjacent_hlil_temps(code), code);
    }

    #[test]
    fn hlil_drops_trailing_goto_when_both_arms_return() {
        let code = "__int64 f(uint64_t a1)\n{\n    if (a1 != 0) {\n        return g();\n    } else {\n        return;\n    }\n    goto loc_140001000;\n}\n";
        let out = drop_unreachable_trailing_gotos(code);
        assert!(!out.contains("goto loc_140001000"), "unreachable goto kept: {out}");
        assert!(out.contains("return g();"), "body damaged: {out}");
    }

    #[test]
    fn hlil_keeps_trailing_goto_when_an_arm_falls_through() {
        // THE guarantee: the `if` has no else, so control reaches the goto.
        let code = "void f(uint64_t a1)\n{\n    if (a1 != 0) {\n        x = 1;\n    }\n    goto loc_140001000;\n}\n";
        assert_eq!(drop_unreachable_trailing_gotos(code), code);
    }

    #[test]
    fn hlil_keeps_trailing_goto_when_only_one_arm_returns() {
        let code = "void f(uint64_t a1)\n{\n    if (a1 != 0) {\n        return;\n    } else {\n        x = 1;\n    }\n    goto loc_140001000;\n}\n";
        assert_eq!(drop_unreachable_trailing_gotos(code), code);
    }

    #[test]
    fn hlil_drops_gotos_stranded_after_return() {
        let code = "void f()\n{\n    return;\n    goto loc_140001000;\n    goto loc_140002000;\n}\n";
        let out = drop_unreachable_gotos_after_return(code);
        assert!(!out.contains("goto"), "unreachable gotos kept: {out}");
        assert!(out.contains("return;"), "return lost: {out}");
    }

    #[test]
    fn hlil_keeps_goto_reachable_through_a_label() {
        // A label makes the following code reachable — must not be dropped.
        let code = "void f()\n{\n    return;\nloc_140001000:\n    goto loc_140002000;\n}\n";
        assert_eq!(drop_unreachable_gotos_after_return(code), code);
    }

    #[test]
    fn hlil_drops_dead_tail_after_a_return() {
        // Real residual from `sample1/sub_140001730`: after the function's
        // `return` there is a stray assignment and a jump back into the body.
        // Nothing can reach either — the assignment is what stopped the
        // trailing-goto pass from seeing the goto as unreachable.
        let code = "void f()\n{\nloc_14000176f:\n    v1 = 1;\n    return;\n    v2 = off_1400040BF;\n    goto loc_14000176f;\n}\n";
        let out = drop_unreachable_trailing_gotos(code);
        assert!(!out.contains("goto"), "dead goto kept: {out}");
    }

    #[test]
    fn hlil_drops_goto_out_of_a_nested_then_arm() {
        // Real residual shape from `sample10_cs/sub_140037800`: the inner
        // `then` arm holds nothing but a jump to the function's tail, which is
        // exactly where falling out of BOTH `if`s lands.
        let code = "void f(uint64_t a1, uint64_t a2)\n{\n    if (a2 != 0) {\n        if (a2 == off_1400F48A8) {\n            goto loc_14003781a;\n        } else {\n            a1 = (a1 + 24);\n            sub_140050940();\n        }\n    }\nloc_14003781a:\n    return;\n}\n";
        let out = drop_redundant_fallthrough_gotos(code);
        assert!(!out.contains("goto"), "nested-arm goto kept: {out}");
        assert!(
            out.contains("sub_140050940();") && out.contains("return;"),
            "code lost: {out}"
        );
    }

    #[test]
    fn hlil_drops_goto_the_fallthrough_already_reaches() {
        // `goto` in the `else` arm targeting the label right after the `if`.
        let code = "void f()\n{\n    if (c) {\n        x = 1;\n    } else {\n        goto loc_140001000;\n    }\nloc_140001000:\n    return;\n}\n";
        let out = drop_redundant_fallthrough_gotos(code);
        assert!(!out.contains("goto"), "redundant goto kept: {out}");
        assert!(out.contains("x = 1;") && out.contains("return;"), "code lost: {out}");
    }

    #[test]
    fn hlil_drops_goto_to_an_empty_arm_with_the_same_exit() {
        // Label sits in an EMPTY `then` arm: falling out of it lands after the
        // `if`, exactly where the goto's own fall-through lands.
        let code = "void f()\n{\n    if (c) {\nloc_140001000:\n    } else {\n        goto loc_140001000;\n    }\n    return;\n}\n";
        let out = drop_redundant_fallthrough_gotos(code);
        assert!(!out.contains("goto"), "redundant goto kept: {out}");
    }

    #[test]
    fn hlil_keeps_goto_that_skips_real_code() {
        // The label is followed by a statement the fall-through would NOT run.
        let code = "void f()\n{\n    if (c) {\nloc_140001000:\n        x = 1;\n    } else {\n        y = 2;\n    }\n    goto loc_140001000;\n}\n";
        assert_eq!(drop_redundant_fallthrough_gotos(code), code);
    }

    #[test]
    fn break_riscrive_il_goto_che_esce_dal_ciclo() {
        // La forma misurata sul corpus: ultimo statement del corpo, label
        // subito dopo la graffa del ciclo.
        let code = "void f()\n{\n    while (1) {\n        if (c) {\n            continue;\n        }\n        goto loc_140001f04;\n    }\nloc_140001f04:\n    v9 = 0;\n}\n";
        let out = goto_loop_exit_to_break(code);
        assert!(!out.contains("goto"), "goto rimasto: {out}");
        assert!(out.contains("break;"), "break non emesso: {out}");
        // La label resta orfana e va via con lui.
        assert!(!out.contains("loc_140001f04:"), "label orfana tenuta: {out}");
        assert!(out.contains("v9 = 0;"), "codice perso: {out}");
    }

    #[test]
    fn break_non_tocca_il_goto_che_salta_altrove() {
        // La label NON e' il punto d'uscita del ciclo: c'e' codice in mezzo.
        let code = "void f()\n{\n    while (1) {\n        goto loc_140001f04;\n    }\n    x = 1;\nloc_140001f04:\n    v9 = 0;\n}\n";
        assert_eq!(goto_loop_exit_to_break(code), code);
    }

    #[test]
    fn break_non_tocca_il_goto_che_esce_da_un_ciclo_da_dentro_uno_switch() {
        // ⚠ Il caso che rende la passata sbagliata se si guarda al CICLO invece
        // che al costrutto interrompibile piu' interno: qui `break` uscirebbe
        // dallo `switch`, non dal `while`, e finirebbe in `x = 1;`.
        let code = "void f()\n{\n    while (1) {\n        switch (k) {\n        case 1:\n            goto loc_140001f04;\n        }\n        x = 1;\n    }\nloc_140001f04:\n    v9 = 0;\n}\n";
        assert_eq!(goto_loop_exit_to_break(code), code);
    }

    #[test]
    fn break_tiene_la_label_se_un_altro_goto_la_usa_ancora() {
        // Un solo goto diventa `break`; l'altro arriva da fuori dal ciclo e
        // resta, quindi la label NON e' orfana.
        let code = "void f()\n{\n    if (d) {\n        goto loc_140001f04;\n    }\n    while (1) {\n        goto loc_140001f04;\n    }\nloc_140001f04:\n    v9 = 0;\n}\n";
        let out = goto_loop_exit_to_break(code);
        assert!(out.contains("break;"), "break non emesso: {out}");
        assert!(out.contains("loc_140001f04:"), "label ancora usata rimossa: {out}");
        assert_eq!(out.matches("goto loc_140001f04;").count(), 1, "{out}");
    }

    #[test]
    fn break_esce_anche_da_uno_switch() {
        // `break` esce dallo switch: se la label e' proprio la' , e' corretto.
        let code = "void f()\n{\n    switch (k) {\n    case 1:\n        goto loc_140001f04;\n    }\nloc_140001f04:\n    v9 = 0;\n}\n";
        let out = goto_loop_exit_to_break(code);
        assert!(out.contains("break;") && !out.contains("goto"), "{out}");
    }

    #[test]
    fn hlil_keeps_goto_that_leaves_a_loop() {
        // Falling off a loop body jumps BACK to the header, so the destinations
        // are not comparable and the goto must survive.
        let code = "void f()\n{\n    while (c) {\n        goto loc_140001000;\n    }\nloc_140001000:\n    return;\n}\n";
        assert_eq!(drop_redundant_fallthrough_gotos(code), code);
    }

    #[test]
    fn hlil_hoists_then_arm_that_is_jumped_back_into() {
        let code = "void f()\n{\n    if (c) {\nloc_140001000:\n        return;\n    } else {\n        x = 1;\n    }\n    goto loc_140001000;\n}\n";
        let out = hoist_jumped_back_then_arms(code);
        assert!(!out.contains("goto"), "goto kept: {out}");
        assert!(!out.contains("loc_140001000:"), "label kept: {out}");
        assert!(out.contains("if (!(c)) {"), "condition not inverted: {out}");
        assert!(out.contains("x = 1;") && out.contains("return;"), "code lost: {out}");
    }

    #[test]
    fn hlil_keeps_jump_back_into_a_falling_through_arm() {
        // `T` does not terminate: the original really is an endless loop, and
        // hoisting would quietly change what the program does.
        let code = "void f()\n{\n    if (c) {\nloc_140001000:\n        x = 1;\n    } else {\n        y = 2;\n    }\n    goto loc_140001000;\n}\n";
        assert_eq!(hoist_jumped_back_then_arms(code), code);
    }

    #[test]
    fn hlil_keeps_jump_back_when_the_label_has_other_referents() {
        let code = "void f()\n{\n    if (c) {\nloc_140001000:\n        return;\n    } else {\n        goto loc_140001000;\n    }\n    goto loc_140001000;\n}\n";
        assert_eq!(hoist_jumped_back_then_arms(code), code);
    }

    #[test]
    fn hlil_sole_goto_branch_takes_a_copy() {
        let code = "void f()\n{\n    if (c) {\n        if (d) {\n            x = 1;\n        } else {\nloc_140001000:\n            y = 2;\n        }\n    } else {\n        goto loc_140001000;\n    }\n    return;\n}\n";
        let out = duplicate_sole_goto_branches(code);
        assert!(!out.contains("goto"), "goto kept: {out}");
        assert!(!out.contains("loc_140001000:"), "label kept: {out}");
        assert_eq!(out.matches("y = 2;").count(), 2, "not duplicated: {out}");
        assert_eq!(
            out.matches('{').count(),
            out.matches('}').count(),
            "braces unbalanced: {out}"
        );
    }

    #[test]
    fn hlil_sole_goto_copy_stops_at_an_else() {
        // `Y` is the `then` arm only; running past `} else {` (which nets zero
        // braces) would copy an `else` with no `if` in front of it.
        let code = "void f()\n{\n    if (c) {\n        if (d) {\nloc_140001000:\n            y = 2;\n        } else {\n            z = 3;\n        }\n    } else {\n        goto loc_140001000;\n    }\n}\n";
        let out = duplicate_sole_goto_branches(code);
        assert_eq!(
            out.matches('{').count(),
            out.matches('}').count(),
            "braces unbalanced: {out}"
        );
        assert_eq!(out.matches("z = 3;").count(), 1, "else arm copied: {out}");
    }

    #[test]
    fn taildup_copies_linear_return_tail_and_refuses_everything_else() {
        // Gate passato come PARAMETRO: leggerlo dall'ambiente non e' testabile.
        let ok = "void f()\n{\n    if (c) {\n        goto loc_140001000;\n    }\n    x = 1;\nloc_140001000:\n    y = 2;\n    return y;\n}\n";
        let out = duplicate_return_tails(ok, true);
        assert!(!out.contains("goto loc_140001000;"), "goto rimasto: {out}");
        assert_eq!(out.matches("y = 2;").count(), 2, "coda non copiata: {out}");
        assert_eq!(out.matches("return y;").count(), 2, "return non copiato: {out}");

        // RIFIUTO 1 — gate spento.
        assert_eq!(duplicate_return_tails(ok, false), ok);
        // RIFIUTO 2 — la coda contiene un `if`: non e' lineare.
        let ramo = "void f()\n{\n    goto loc_140001000;\nloc_140001000:\n    if (c) {\n        y = 2;\n    }\n    return y;\n}\n";
        assert_eq!(duplicate_return_tails(ramo, true), ramo);
        // RIFIUTO 3 — la coda contiene un altro goto.
        let rimb = "void f()\n{\n    goto loc_140001000;\nloc_140001000:\n    y = 2;\n    goto loc_140002000;\n}\n";
        assert_eq!(duplicate_return_tails(rimb, true), rimb);
        // RIFIUTO 4 — il blocco finisce con `}` prima di un return.
        let chiuso = "void f()\n{\n    if (c) {\nloc_140001000:\n        y = 2;\n    }\n    goto loc_140001000;\n}\n";
        assert_eq!(duplicate_return_tails(chiuso, true), chiuso);
        // RIFIUTO 5 — etichetta inesistente.
        let orfano = "void f()\n{\n    goto loc_140009999;\n}\n";
        assert_eq!(duplicate_return_tails(orfano, true), orfano);
    }

    #[test]
    fn hlil_keeps_sole_goto_when_continuations_differ() {
        // After `y = 2;` control reaches `z = 3;`, but from the `else` it does
        // not — copying would change what runs.
        let code = "void f()\n{\n    if (c) {\n        if (d) {\n            x = 1;\n        } else {\nloc_140001000:\n            y = 2;\n        }\n        z = 3;\n    } else {\n        goto loc_140001000;\n    }\n    return;\n}\n";
        assert_eq!(duplicate_sole_goto_branches(code), code);
    }

    #[test]
    fn hlil_keeps_sole_goto_out_of_a_loop() {
        let code = "void f()\n{\n    while (c) {\n        if (d) {\n            goto loc_140001000;\n        }\n    }\nloc_140001000:\n    y = 2;\n}\n";
        assert_eq!(duplicate_sole_goto_branches(code), code);
    }

    #[test]
    fn hlil_intrinsic_indirect_call_becomes_direct() {
        let code = "void f()\n{\n    uint64_t var_memcpy;\n    ((__int64 (*)())var_memcpy)(v1, v2, (v3 * 8));\n}\n";
        let out = rewrite_hlil_intrinsic_calls(code);
        assert!(out.contains("memcpy(v1, v2, (v3 * 8));"), "not rewritten: {out}");
        assert!(!out.contains("var_memcpy"), "placeholder decl left: {out}");
    }

    #[test]
    fn hlil_intrinsic_rewrite_covers_the_sse_tail() {
        // Not just memcpy/memset: every never-assigned callee is a lifter
        // intrinsic (`pcmpeq`, `cvt`, `bsf`, …) and gets its real name.
        let code = "void f()\n{\n    uint64_t var_pcmpeq;\n    ((__int64 (*)())var_pcmpeq)(v1, v2);\n}\n";
        let out = rewrite_hlil_intrinsic_calls(code);
        assert!(out.contains("pcmpeq(v1, v2);"), "tail intrinsic not named: {out}");
        assert!(!out.contains("var_pcmpeq"), "placeholder decl left: {out}");
    }

    #[test]
    fn hlil_intrinsic_rewrite_leaves_real_function_pointers_alone() {
        // THE guarantee: a callee that is ASSIGNED is a genuine function
        // pointer. Renaming it into a direct call would invent a function the
        // program never named.
        let code = "void f()\n{\n    uint64_t var_thing;\n    var_thing = off_140001000;\n    ((__int64 (*)())var_thing)(v1);\n}\n";
        assert_eq!(rewrite_hlil_intrinsic_calls(code), code);
    }

    #[test]
    fn the_direction_flag_gets_the_value_the_abi_guarantees() {
        // Il testo REALE di `rep movsq` in B (sample10_cs/sub_140016ca0).
        let code = "void f()
{
    uint8_t flag_df;
    memcpy(((flag_df == 1) ? (v5 - 8) : v5), v6, 8);
}
";
        let out = define_abi_direction_flag(code);
        assert!(
            out.contains("uint8_t flag_df = 0; /* DF is 0 on entry per the x86-64 ABI */"),
            "non definita: {out}"
        );
        // Il ternario RESTA: la riparazione definisce, non riscrive il corpo.
        assert!(out.contains("(flag_df == 1)"), "corpo alterato: {out}");
        assert_eq!(out.matches('{').count(), out.matches('}').count(), "{out}");
    }

    #[test]
    fn a_function_that_sets_the_direction_flag_is_left_alone() {
        // THE guarantee: se la funzione esegue `std`, DF vale davvero 1 a
        // runtime e imporre 0 sarebbe una BUGIA. La scrittura e' la guardia.
        let sets = "void f()\n{\n    uint8_t flag_df;\n    flag_df = 1;\n    memcpy(((flag_df == 1) ? v5 : v6), v6, 8);\n}\n";
        assert_eq!(define_abi_direction_flag(sets), sets);
        // Nessuna dichiarazione di `flag_df`: niente da fare.
        let none = "void f()\n{\n    uint8_t v1;\n    v1 = 1;\n}\n";
        assert_eq!(define_abi_direction_flag(none), none);
        // Una dichiarazione GIA' inizializzata non viene toccata due volte.
        let once = "void f()\n{\n    uint8_t flag_df = 0;\n    a1 = flag_df;\n}\n";
        assert_eq!(define_abi_direction_flag(once), once);
    }

    #[test]
    fn a_prologue_saved_callee_register_is_named_not_deleted() {
        // Il testo REALE di `push %rbx` in B (sample10_cs/sub_140004060).
        let code = "void f()
{
    uint64_t v6;
    var_sp = (var_sp - 8);
    *(__int64 *)var_sp = v6;
}
";
        let out = name_saved_callee_regs(code);
        assert!(out.contains("extern uint64_t v6;"), "non nominata: {out}");
        // ⚠ Il salvataggio NON deve sparire: toglierlo sposterebbe gli offset.
        assert!(out.contains("*(__int64 *)var_sp = v6;"), "store perso: {out}");
        assert!(out.contains("var_sp = (var_sp - 8);"), "decremento perso: {out}");
        assert_eq!(out.matches('{').count(), out.matches('}').count(), "{out}");
    }

    #[test]
    fn a_register_with_any_other_use_is_left_alone() {
        // THE guarantee: un solo uso diverso dal salvataggio significa che la
        // variabile porta un valore vero — sono i 5 casi "misti" misurati.
        let mixed = "void f()\n{\n    uint64_t v6;\n    *(__int64 *)var_sp = v6;\n    a1 = (v6 + 1);\n}\n";
        assert_eq!(name_saved_callee_regs(mixed), mixed);
        // Una variabile DEFINITA non e' un salvataggio del chiamante.
        let def = "void f()\n{\n    uint64_t v6;\n    v6 = 1;\n    *(__int64 *)var_sp = v6;\n}\n";
        assert_eq!(name_saved_callee_regs(def), def);
        // `sp`/`fp` sono stato della macchina, gia' esclusi dalla metrica.
        let sp = "void f()\n{\n    uint64_t fp;\n    *(__int64 *)var_sp = fp;\n}\n";
        assert_eq!(name_saved_callee_regs(sp), sp);
        // Dichiarata e mai usata: niente da nominare.
        let unused = "void f()\n{\n    uint64_t v6;\n    a1 = 1;\n}\n";
        assert_eq!(name_saved_callee_regs(unused), unused);
        // La META' SSE del prologo usa lo slot con spiazzamento COSTANTE
        // (`movdqa %xmm6, 0x2D0(%rsp)`); matchare solo `var_sp` li mancava tutti.
        let sse = "void f()\n{\n    __m128i var_xmm10;\n    *(__int64 *)(sp + 784) = var_xmm10;\n}\n";
        let out = name_saved_callee_regs(sse);
        assert!(out.contains("extern __m128i var_xmm10;"), "{out}");
        assert!(out.contains("*(__int64 *)(sp + 784) = var_xmm10;"), "store perso: {out}");
        // La META' SSE narrowizza in uscita: il lato destro porta dei CAST.
        // Pretendere il nome NUDO mancava 30 salvataggi (misurati).
        let cast = "void f()\n{\n    __m128i var_xmm15;\n    *(__int64 *)(sp + 40) = (uint64_t)(unsigned __int128)var_xmm15;\n}\n";
        let out = name_saved_callee_regs(cast);
        assert!(out.contains("extern __m128i var_xmm15;"), "{out}");
        assert!(out.contains("(unsigned __int128)var_xmm15;"), "store perso: {out}");
        // Un xmm ALTO letto e mai scritto porta un valore IN INGRESSO anche
        // quando l'uso NON e' un salvataggio (calcolo, store via puntatore):
        // misurati 145 casi, nessuno raggiunto dal solo test «tutti salvataggi».
        let compute = "void f()\n{\n    unsigned __int128 var_xmm6;\n    var_xmm1 = (var_xmm1 * var_xmm6);\n}\n";
        let out = name_saved_callee_regs(compute);
        assert!(out.contains("extern unsigned __int128 var_xmm6;"), "{out}");
        assert!(
            out.contains("incoming register value"),
            "commento sbagliato per un uso in calcolo: {out}"
        );
        assert!(out.contains("(var_xmm1 * var_xmm6);"), "uso perso: {out}");
        // ⚠ `xmm0`-`xmm5` sono i registri dei PARAMETRI FP Win64: la cura giusta
        // e' promuoverli a parametri, NON nominarli esterni.
        let arg = "void f()\n{\n    unsigned __int128 var_xmm2;\n    var_xmm1 = (var_xmm1 * var_xmm2);\n}\n";
        assert_eq!(name_saved_callee_regs(arg), arg);
        // ⚠⚠ THE guarantee della via xmm: un registro che il corpo ASSEGNA non
        // e' un valore in ingresso. Senza questo test la passata riscriveva 682
        // dichiarazioni invece di 145, dichiarando `extern` 537 locali che la
        // funzione DEFINISCE — e ogni altra metrica restava VERDE.
        let written = "void f()\n{\n    unsigned __int128 var_xmm6;\n    var_xmm6 = (unsigned __int128)a1;\n    a2 = var_xmm6;\n}\n";
        assert_eq!(name_saved_callee_regs(written), written);
        // ⚠ Un OPERATORE a destra significa valore CALCOLATO, non salvato.
        let computed = "void f()\n{\n    uint64_t v6;\n    *(__int64 *)(sp + 8) = (v6 + 1);\n}\n";
        assert_eq!(name_saved_callee_regs(computed), computed);
        // Uno spiazzamento CALCOLATO e' uno store in un buffer, non un salvataggio.
        let idx = "void f()\n{\n    uint64_t v6;\n    *(__int64 *)(sp + a1) = v6;\n}\n";
        assert_eq!(name_saved_callee_regs(idx), idx);
        // Una base che non e' lo stack non e' un salvataggio.
        let heap = "void f()\n{\n    uint64_t v6;\n    *(__int64 *)(a1 + 8) = v6;\n}\n";
        assert_eq!(name_saved_callee_regs(heap), heap);
        // ⚠ Una riga GIA' `extern` non e' una locale: riscriverla produceva
        // `extern extern __int64 off_X;`, che gcc rifiuta (misurato: 3 file,
        // ricompilabilita' a lista fissa 1199 -> 1196).
        let already = "extern __int64 off_1400B03D8;\nvoid f()\n{\n    *(__int64 *)var_sp = off_1400B03D8;\n}\n";
        assert_eq!(name_saved_callee_regs(already), already);
    }

    #[test]
    fn a_loaded_function_address_returns_to_call_position() {
        // The shape the call-return fix produces: the callee load and the
        // indirect call are no longer a single-use temp pair.
        let code = "void f()
{
    uint64_t v1;
    v1 = 5369692352;
    v1 = v1();
}
";
        let out = fold_loaded_fnptr_into_call(code);
        assert!(
            out.contains("v1 = 5369692352();"),
            "not folded into call position: {out}"
        );
        assert!(!out.contains("v1 = v1()"), "indirect call survived: {out}");
        // Brace balance is the structural invariant (REGOLA #13).
        assert_eq!(out.matches('{').count(), out.matches('}').count(), "{out}");
    }

    #[test]
    fn a_discarded_result_and_arguments_both_fold() {
        let code = "void f()\n{\n    v2 = 0x140001000;\n    v2(a1, a2);\n}\n";
        let out = fold_loaded_fnptr_into_call(code);
        assert!(out.contains("0x140001000(a1, a2);"), "{out}");
        assert!(!out.contains("v2 = 0x140001000;"), "def survived: {out}");
    }

    #[test]
    fn a_computed_callee_is_never_folded() {
        // THE guarantee: only a bare address constant may move into call
        // position. Folding an expression could duplicate work or reorder it,
        // and folding a callee that is read again would lose its definition.
        let expr = "void f()\n{\n    v1 = (a1 + 8);\n    v1 = v1();\n}\n";
        assert_eq!(fold_loaded_fnptr_into_call(expr), expr);
        let reread = "void f()\n{\n    v1 = 5369692352;\n    v1 = v1(v1);\n}\n";
        assert_eq!(fold_loaded_fnptr_into_call(reread), reread);
        // A non-adjacent call is left alone too.
        let apart = "void f()\n{\n    v1 = 5369692352;\n    v3 = 1;\n    v1 = v1();\n}\n";
        assert_eq!(fold_loaded_fnptr_into_call(apart), apart);
    }

    #[test]
    fn hlil_duplicate_label_is_deduped() {
        // Same `loc_X:` emitted twice (two blocks at one address) → keep first.
        let code = "void f()\n{\nloc_140001050:\n    a = 1;\n    goto loc_140001050;\nloc_140001050:\n    b = 2;\n}\n";
        let out = dedup_hlil_labels(code);
        assert_eq!(out.matches("loc_140001050:").count(), 1, "not deduped: {out}");
        // The code under the dropped label survives.
        assert!(out.contains("b = 2;"), "code under dup label lost: {out}");
        assert!(out.contains("goto loc_140001050;"), "goto lost: {out}");
    }

    #[test]
    fn hlil_dedup_labels_is_noop_without_duplicates() {
        let code = "void f()\n{\nloc_140001050:\n    goto loc_140001050;\n}\n";
        assert_eq!(dedup_hlil_labels(code), code);
    }

    #[test]
    fn hlil_empty_then_flip_relational() {
        // `if (C) { } else { B }` → `if (!C) { B }` with the operator flipped.
        let code = "    if (var_tmp0 != 0) {\n    } else {\n        v5 = 4;\n    }\n";
        let out = flip_empty_hlil_then_branches(code);
        assert!(out.contains("if (var_tmp0 == 0) {"), "{out}");
        assert!(!out.contains("} else {"), "{out}");
        assert!(out.contains("v5 = 4;"), "{out}");
    }

    #[test]
    fn hlil_empty_then_flip_compound_wraps_not() {
        let code = "    if (a == 1 && b == 2) {\n    } else {\n        x();\n    }\n";
        let out = flip_empty_hlil_then_branches(code);
        assert!(out.contains("if (!(a == 1 && b == 2)) {"), "{out}");
    }

    #[test]
    fn hlil_empty_then_flip_leaves_normal_if_and_loops_alone() {
        let code = "    if (a == 1) {\n        y();\n    } else {\n        x();\n    }\n    while (b < 2) {\n    }\n";
        assert_eq!(flip_empty_hlil_then_branches(code), code);
    }

    #[test]
    fn hlil_empty_then_flip_handles_else_if() {
        let code = "    } else if (v6 == 0) {\n    } else {\n        x();\n    }\n";
        let out = flip_empty_hlil_then_branches(code);
        assert!(out.contains("} else if (v6 != 0) {"), "{out}");
    }

    #[test]
    fn hlil_empty_then_flip_shift_is_not_relational() {
        // `<<` must not be mistaken for `<`; falls back to `!(…)`.
        let code = "    if (a << 2) {\n    } else {\n        x();\n    }\n";
        let out = flip_empty_hlil_then_branches(code);
        assert!(out.contains("if (!(a << 2)) {"), "{out}");
    }

    #[test]
    fn hlil_empty_if_no_else_is_deleted_with_hlil_doubled_parens() {
        // Path `B`'s printer parenthesises unconditionally, so the guard
        // arrives as `((var_tmp0 != 0))`. Both arms empty ⇒ provable no-op.
        let code = "    v1 = 1;\n    if ((var_tmp0 != 0)) {\n    }\n    v2 = 2;\n";
        let out = fold_empty_if_branches(code);
        assert_eq!(out, "    v1 = 1;\n    v2 = 2;\n", "{out}");
    }

    #[test]
    fn hlil_empty_if_holding_a_label_is_never_deleted() {
        // A label inside the arm is a real jump target — the body is NOT empty.
        let code = "    if ((v7 == 0)) {\nloc_14000c82c:\n    }\n";
        assert_eq!(fold_empty_if_branches(code), code);
    }

    #[test]
    fn sse_store_of_scalar_param_becomes_a_scalar_store() {
        // Verbatim shape from sample1/sub_140001d90.c: a varargs spill whose
        // source the scalar-xmm pass already retyped to `__int64`.
        let code = "__int64 __fastcall f(__int64 a1,__int64 a2,__int64 a3) {\n\
                        *(__int64 *)(rsp + 40) = a2;\n\
                    _mm_storeu_si128((__m128i *)&*(__int64 *)(rsp + 48), a3);\n}\n";
        let out = scalarize_sse_store_of_scalar_source(code);
        assert!(out.contains("*(__int64 *)(rsp + 48) = a3;"), "{out}");
        assert!(!out.contains("_mm_storeu_si128"), "{out}");
    }

    #[test]
    fn sse_store_of_a_real_m128_source_is_untouched() {
        // `xmm0` declared `__m128i` — narrowing this to 64 bits would silently
        // drop half the stored data. The pass must keep its hands off.
        let code = "void f() {\n    __m128i xmm0;\n\
                    _mm_storeu_si128((__m128i *)&*(__int64 *)(rsp + 48), xmm0);\n}\n";
        assert_eq!(scalarize_sse_store_of_scalar_source(code), code);
    }

    #[test]
    fn sse_store_with_unknown_source_type_is_untouched() {
        // No declaration for `v9` anywhere ⇒ type unknown ⇒ leave it alone.
        let code = "void f() {\n\
                    _mm_storeu_si128((__m128i *)&*(__int64 *)(rsp + 48), v9);\n}\n";
        assert_eq!(scalarize_sse_store_of_scalar_source(code), code);
    }

    #[test]
    fn sse_store_rewrite_handles_nested_parens_in_the_destination() {
        let code = "void f() {\n    __int64 a3;\n\
                    _mm_storeu_si128((__m128i *)&*(__int64 *)(rsp + (v1 * 8)), a3);\n}\n";
        let out = scalarize_sse_store_of_scalar_source(code);
        assert!(out.contains("*(__int64 *)(rsp + (v1 * 8)) = a3;"), "{out}");
    }

    #[test]
    fn empty_if_with_cast_deref_guard_is_deleted() {
        // `)(` here is a CAST, not a call — the guard is side-effect-free.
        // 62 corpus empty-ifs survived only because it read as a call.
        let code = "    if (*(__int64 *)(v2 + 8) < var_r8d) {\n    }\n    x();\n";
        assert_eq!(fold_empty_if_branches(code), "    x();\n");
    }

    #[test]
    fn empty_if_calling_through_parenthesised_fn_ptr_survives() {
        // `(fp)(x)` IS a call: a bare identifier must never read as a type.
        let code = "    if ((fp)(x) != 0) {\n    }\n";
        assert_eq!(fold_empty_if_branches(code), code);
        // …and neither must a cast-looking call through a function pointer:
        // in a cast the `*` is a SUFFIX (`__int64 *`), here it is a leading
        // dereference, so `(*fp)(x)` stays a call.
        let code2 = "    if ((*fp)(x) != 0) {\n    }\n";
        assert_eq!(fold_empty_if_branches(code2), code2);
    }

    #[test]
    fn empty_if_with_struct_pointer_cast_guard_is_deleted() {
        // `(struct Struct_X_t *)` — the corpus' own struct-recovery spelling.
        let code = "    if (*(struct Struct_7C900929_t *)(v2 + 8) == 0) {\n    }\n    x();\n";
        assert_eq!(fold_empty_if_branches(code), "    x();\n");
    }

    #[test]
    fn hlil_empty_if_with_call_guard_survives() {
        // Side-effecting guard: deleting it would drop the call.
        let code = "    if ((sub_140012DB0() == 0)) {\n    }\n";
        assert_eq!(fold_empty_if_branches(code), code);
    }

    #[test]
    fn self_referential_goto_becomes_jumpout_and_keeps_its_label() {
        let code = "    v1 = 1;\nloc_140001830:\n    goto loc_140001830;\n    v2 = 2;\n";
        let out = break_self_referential_gotos(code);
        assert!(out.contains("loc_140001830:\n"), "label must survive: {out}");
        assert!(out.contains("JUMPOUT(0x140001830);"), "{out}");
        assert!(!out.contains("goto loc_140001830;"), "{out}");
    }

    #[test]
    fn goto_to_a_different_label_is_untouched() {
        // A real forward/backward edge must NOT be degraded to a JUMPOUT.
        let code = "loc_140001830:\n    goto loc_140001900;\n";
        assert_eq!(break_self_referential_gotos(code), code);
    }

    #[test]
    fn label_followed_by_real_code_is_untouched() {
        let code = "loc_140001830:\n    v1 = 2;\n    goto loc_140001830;\n";
        assert_eq!(break_self_referential_gotos(code), code);
    }

    #[test]
    fn hlil_unlabelled_goto_becomes_jumpout() {
        // No `loc_140001050:` anywhere ⇒ the target is not in this function.
        let code = "void f()\n{\n        goto loc_140001050;\n}\n";
        let out = rewrite_hlil_numeric_gotos(code);
        assert!(out.contains("        JUMPOUT(0x140001050);"), "{out}");
    }

    #[test]
    fn hlil_external_jumpout_becomes_tail_call() {
        // No `loc_140002000:` in the function ⇒ external target ⇒ tail call.
        let code = "void f()\n{\n    JUMPOUT(0x140002000);\n}\n";
        let out = rewrite_hlil_tail_calls(code, &[]);
        assert!(out.contains("return sub_140002000();"), "{out}");
        assert!(!out.contains("JUMPOUT"), "{out}");
    }

    #[test]
    fn hlil_internal_jumpout_with_label_stays_jumpout() {
        // `loc_1400012ec:` exists ⇒ unresolved INTERNAL target ⇒ keep JUMPOUT.
        let code = "void f()\n{\nloc_1400012ec:\n    JUMPOUT(0x1400012ec);\n}\n";
        let out = rewrite_hlil_tail_calls(code, &[]);
        assert!(out.contains("JUMPOUT(0x1400012ec);"), "internal must stay: {out}");
        assert!(!out.contains("return sub_"), "{out}");
    }

    #[test]
    fn hlil_jumpout_inside_own_range_is_never_a_tail_call() {
        // No label for it — but the target lies INSIDE this function, so it is
        // an unemitted intra-function block, not a callee. Inventing
        // `return sub_X();` would both fabricate a call and end the function.
        let code = "void f()
{
    JUMPOUT(0x140001100);
}
";
        let out = rewrite_hlil_tail_calls(code, &[(0x1_4000_1100, 0x1_4000_1110)]);
        assert!(out.contains("JUMPOUT(0x140001100);"), "invented a call: {out}");
        assert!(!out.contains("return sub_"), "invented a call: {out}");
    }

    #[test]
    fn hlil_jumpout_into_the_middle_of_an_own_block_is_never_a_tail_call() {
        // Not a block START, but inside one of our blocks — measured 807 such
        // targets (e.g. `sub_1400020a0` jumping to 0x1400020eb, which the
        // disassembly shows is mid-block code, not a prologue). Testing only
        // block starts left these as invented calls.
        let code = "void f()\n{\n    JUMPOUT(0x1400020eb);\n}\n";
        let out = rewrite_hlil_tail_calls(code, &[(0x1_4000_20e0, 0x1_4000_20f8)]);
        assert!(out.contains("JUMPOUT(0x1400020eb);"), "invented a call: {out}");
        assert!(!out.contains("return sub_"), "invented a call: {out}");
    }

    #[test]
    fn hlil_labelled_goto_survives_the_pass() {
        let code = "void f()\n{\n    goto loc_140001050;\nloc_140001050:\n    return;\n}\n";
        let out = rewrite_hlil_numeric_gotos(code);
        assert!(out.contains("goto loc_140001050;"), "real edge destroyed: {out}");
        assert!(!out.contains("JUMPOUT"), "{out}");
    }

    #[test]
    fn hlil_numeric_goto_with_matching_label_is_kept() {
        // A resolved intra-function edge: the label IS there. Rewriting it to
        // JUMPOUT would compile but throw away the recovered control flow.
        let code = "void f()\n{\n    goto 0x140001050;\nloc_140001050:\n    return;\n}\n";
        let out = rewrite_hlil_numeric_gotos(code);
        assert!(out.contains("goto 0x140001050;"), "resolved edge destroyed: {out}");
        assert!(!out.contains("JUMPOUT"), "{out}");
    }

    #[test]
    fn hlil_labelled_goto_is_left_alone() {
        // A real labelled goto is valid C — never rewrite it.
        let code = "void f()\n{\n    goto loc_140001050;\nloc_140001050:\n    return;\n}\n";
        assert_eq!(rewrite_hlil_numeric_gotos(code), code);
    }

    #[test]
    fn hlil_goto_rewrite_preserves_indentation() {
        let code = "            goto 0xABC;\n";
        assert_eq!(rewrite_hlil_numeric_gotos(code), "            JUMPOUT(0xABC);\n");
    }

    #[test]
    fn hlil_externs_land_at_the_top() {
        let code = "void fn_1400013e0()\n{\n    v1 = *off_140004420;\n}\n";
        let out = prepend_hlil_externs(code, None, false, &[], false);
        assert!(out.starts_with("extern __int64 off_140004420;\n"), "{out}");
    }

    #[test]
    fn hlil_externs_relocate_misplaced_copies() {
        // A mid-file declaration (what the A-shaped pass produced) must move up.
        let code = "void fn_X()\n{\n    v1 = off_140004420;\n}\nextern __int64 off_140004420;\n";
        let out = prepend_hlil_externs(code, None, false, &[], false);
        let first = out.lines().next().unwrap_or_default();
        assert_eq!(first, "extern __int64 off_140004420;");
        assert_eq!(out.matches("extern __int64 off_140004420;").count(), 1, "{out}");
    }

    #[test]
    fn hlil_externs_noop_without_symbols() {
        let code = "void f()\n{\n    v1 = 1;\n}\n";
        assert_eq!(prepend_hlil_externs(code, None, false, &[], false), code);
    }

    #[test]
    fn hlil_type_names_map_uint128() {
        let code = "uint128_t v1;\n";
        assert_eq!(normalize_hlil_type_names(code), "unsigned __int128 v1;\n");
    }

    #[test]
    fn hlil_type_names_map_int128_and_leave_256_alone() {
        assert_eq!(normalize_hlil_type_names("int128_t v1;\n"), "__int128 v1;\n");
        // 256-bit has no width-faithful scalar target under the prelude. It is
        // narrowed to `__int64` ONLY when the function is intrinsic-free (the
        // same gate the shipped xmm policy uses), so a genuine vector
        // computation is still never silently narrowed — that guarantee, which
        // this test originally enforced by leaving 256-bit alone everywhere, is
        // now enforced by the gate instead.
        assert_eq!(normalize_hlil_type_names("uint256_t v2;\n"), "__int64 v2;\n");
        assert_eq!(
            normalize_hlil_type_names("uint256_t v2;\nx = _mm_add_epi64(a, b);\n"),
            "uint256_t v2;\nx = _mm_add_epi64(a, b);\n"
        );
    }

    #[test]
    fn hlil_type_names_leave_similar_identifiers_alone() {
        let code = "uint128_ta v1;\nmy_uint128_t v2;\n";
        assert_eq!(normalize_hlil_type_names(code), code);
    }

    #[test]
    fn hlil_deref_cast_covers_narrow_int_types() {
        let code = "void f()\n{\n    uint16_t v2;\n    v2 = *v2;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("*(__int64 *)v2"), "{out}");
    }

    #[test]
    fn hlil_deref_cast_wraps_integer_locals() {
        let code = "void f()\n{\n    uint64_t v1;\n    v1 = *v1;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("v1 = *(__int64 *)v1;"), "{out}");
    }

    #[test]
    fn hlil_deref_cast_wraps_extern_data() {
        let code = "extern __int64 off_140004420;\nvoid f()\n{\n    uint64_t v1;\n    v1 = *off_140004420;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("*(__int64 *)off_140004420"), "{out}");
    }

    #[test]
    fn hlil_deref_cast_leaves_multiplication_alone() {
        // BINARY `*` must never be touched — `a * v1` is a product, not a deref.
        let code = "void f()\n{\n    uint64_t v1;\n    uint64_t a;\n    a = a * v1;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("a = a * v1;"), "multiplication rewritten: {out}");
        assert!(!out.contains("(__int64 *)"), "{out}");
    }

    #[test]
    fn hlil_deref_cast_leaves_real_pointers_alone() {
        let code = "void f()\n{\n    uint64_t *p;\n    uint64_t v;\n    v = *p;\n}\n";
        let out = cast_hlil_integer_derefs(code);
        assert!(out.contains("v = *p;"), "pointer deref rewritten: {out}");
    }

    #[test]
    fn hlil_deref_cast_noop_without_declarations() {
        let code = "void f()\n{\n    v = *x;\n}\n";
        assert_eq!(cast_hlil_integer_derefs(code), code);
    }

    #[test]
    fn symbolize_hlil_addresses_names_calls_and_data() {
        // The exact shapes from the 2026-07-18 audit of sub_140026ad0.
        let anchor = 0x1_4002_6ad0;
        assert_eq!(
            symbolize_hlil_addresses("    5369702912();", anchor, false),
            "    sub_1400F2A00();"
        );
        assert_eq!(
            symbolize_hlil_addresses("    var_rax = *5369938976;", anchor, false),
            "    var_rax = *off_14012C420;"
        );
        // Small immediates (counts, masks, sizes) must NOT be mangled.
        assert_eq!(symbolize_hlil_addresses("x = y + 16;", anchor, false), "x = y + 16;");
        assert_eq!(symbolize_hlil_addresses("if (n != 0x1000) {", anchor, false), "if (n != 0x1000) {");
        // A digit run inside an identifier is untouched.
        assert_eq!(symbolize_hlil_addresses("var_r10 = 1;", anchor, false), "var_r10 = 1;");
        // An address far outside this image is left alone.
        assert_eq!(symbolize_hlil_addresses("q = 999999999999;", anchor, false), "q = 999999999999;");
    }

    /// #4990: the address-of half, and — the part that matters — what it must
    /// NOT touch. The gate is a parameter precisely so both branches are
    /// reachable from a test.
    #[test]
    fn symbolize_hlil_addresses_addr_of_casts_and_rejects() {
        let anchor = 0x1_4002_6ad0;

        // The constant IS an address, so it is spelled `(__int64)&off_X`.
        // The cast is load-bearing: a bare `&off_X` is an `__int64 *`, and the
        // 181 arithmetic sites would become pointer arithmetic scaled by 8.
        assert_eq!(
            symbolize_hlil_addresses("    v2 = 5369938976;", anchor, true),
            "    v2 = (__int64)&off_14012C420;"
        );
        // Arithmetic: the whole reason for the cast.
        assert_eq!(
            symbolize_hlil_addresses("    a1 = (a1 + 5369938976);", anchor, true),
            "    a1 = (a1 + (__int64)&off_14012C420);"
        );

        // RIFIUTO 1 — gate spento: testo IDENTICO, byte per byte.
        let nudo = "    v2 = 5369938976;";
        assert_eq!(
            symbolize_hlil_addresses(nudo, anchor, false),
            "    v2 = off_14012C420;",
            "a gate spento la forma storica non deve cambiare"
        );

        // RIFIUTO 2 — un target di CHIAMATA non prende mai `&`: e' `sub_X`,
        // e il ramo `is_call` deve restare PRIMA di quello dell'indirizzo.
        assert_eq!(
            symbolize_hlil_addresses("    5369702912();", anchor, true),
            "    sub_1400F2A00();"
        );

        // RIFIUTO 3 — una costante fuori dall'immagine resta un numero, gate o no.
        assert_eq!(
            symbolize_hlil_addresses("q = 999999999999;", anchor, true),
            "q = 999999999999;"
        );

        // RIFIUTO 4 — un immediato piccolo non e' un indirizzo.
        assert_eq!(
            symbolize_hlil_addresses("x = y + 16;", anchor, true),
            "x = y + 16;"
        );
    }

    #[test]
    fn collapse_redundant_casts_only_collapses_identical_adjacent() {
        assert_eq!(collapse_redundant_casts("x = (__int64)(__int64)ptr;"), "x = (__int64)ptr;");
        // Triple collapses fully.
        assert_eq!(collapse_redundant_casts("(__int64)(__int64)(__int64)a1"), "(__int64)a1");
        // Pointer type.
        assert_eq!(collapse_redundant_casts("(char *)(char *)p"), "(char *)p");
        // DIFFERENT types must NOT collapse (inner cast is meaningful).
        assert_eq!(collapse_redundant_casts("(__int64)(int)x"), "(__int64)(int)x");
        // A parenthesised expression next to a cast is not a doubled cast.
        assert_eq!(collapse_redundant_casts("(__int64)(a + b)"), "(__int64)(a + b)");
        // Nothing to do.
        assert_eq!(collapse_redundant_casts("y = a + b;"), "y = a + b;");
    }

    #[test]
    fn capture_call_result_folds_read_rax_but_skips_void_calls() {
        // A call whose rax result is read next → capture it.
        let mut stmts = vec![
            CfsStatement::Raw("accumulate(str2, 3);".into()),
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "rax".into() },
        ];
        capture_call_result(&mut stmts);
        assert!(
            matches!(&stmts[0], CfsStatement::Raw(r) if r == "rax = accumulate(str2, 3);"),
            "{stmts:?}"
        );
        // A void SSE store must NOT be captured (returns void).
        let mut v = vec![
            CfsStatement::Raw("_mm_storeu_si128((__m128i *)&v_30, xmm2);".into()),
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "rax".into() },
        ];
        capture_call_result(&mut v);
        assert!(
            matches!(&v[0], CfsStatement::Raw(r) if r == "_mm_storeu_si128((__m128i *)&v_30, xmm2);"),
            "void call must not be captured: {v:?}"
        );
        // No later rax read → leave the call bare (don't clutter void calls).
        let mut n = vec![
            CfsStatement::Raw("side_effect(a1);".into()),
            CfsStatement::Return(None),
        ];
        capture_call_result(&mut n);
        assert!(matches!(&n[0], CfsStatement::Raw(r) if r == "side_effect(a1);"), "{n:?}");
    }

    /// `free`/`abort` are void in the recompile prelude: capturing them emits
    /// `rax = free(ptr);` — gcc's "invalid use of void expression" (2 corpus
    /// files, sample7_cpp, 2026-07-18).
    #[test]
    fn strip_void_call_capture_drops_assignment_keeps_call() {
        let code = "int f() {\n    __int64 src;\n    src = free(ptr);\n    result = free(ptr);\n    v1 = freeform(x);\n    src = strlen(s);\n}";
        let out = strip_void_call_capture(code);
        assert!(out.contains("\n    free(ptr);\n"), "{out}");
        assert!(!out.contains("src = free("), "{out}");
        assert!(!out.contains("result = free("), "{out}");
        // Non-void and merely-prefixed names untouched.
        assert!(out.contains("v1 = freeform(x);"), "{out}");
        assert!(out.contains("src = strlen(s);"), "{out}");
    }

    #[test]
    fn capture_call_result_skips_void_crt_calls() {
        let mut b = vec![
            CfsStatement::Raw("free(ptr);".into()),
            CfsStatement::Branch("if (rax != 0) goto loc_1c50;".into()),
        ];
        capture_call_result(&mut b);
        assert!(
            matches!(&b[0], CfsStatement::Raw(r) if r == "free(ptr);"),
            "void CRT call must not be captured: {b:?}"
        );
    }

    #[test]
    fn capture_call_result_crosses_block_boundary_until_rax_clobber() {
        // Corpus witness (sample10_cs/sub_140001bd0): the call's rax is tested
        // by the very NEXT branch — a Branch statement reading rax must count
        // as a use, not as an opaque block terminator.
        let mut b = vec![
            CfsStatement::Raw("sub_140002340(ptr, a2, 123);".into()),
            CfsStatement::Branch("if (rax != 0) goto loc_1c50;".into()),
        ];
        capture_call_result(&mut b);
        assert!(
            matches!(&b[0], CfsStatement::Raw(r) if r == "rax = sub_140002340(ptr, a2, 123);"),
            "branch-condition rax use must trigger capture: {b:?}"
        );
        // Use in the NEXT basic block (across a goto + label) with no
        // intervening rax write → still capture.
        let mut x = vec![
            CfsStatement::Raw("sub_9(a1);".into()),
            CfsStatement::Raw("goto loc_28;".into()),
            CfsStatement::Raw("loc_28:".into()),
            CfsStatement::Assign { lhs: "v2".into(), rhs: "rax".into() },
        ];
        capture_call_result(&mut x);
        assert!(
            matches!(&x[0], CfsStatement::Raw(r) if r == "rax = sub_9(a1);"),
            "cross-block rax use must trigger capture: {x:?}"
        );
        // An intervening CALL in the next block clobbers rax — the FIRST call
        // must stay bare; the second (whose result is the one read) is captured.
        let mut k = vec![
            CfsStatement::Raw("sub_9(a1);".into()),
            CfsStatement::Raw("loc_28:".into()),
            CfsStatement::Raw("sub_b(a2);".into()),
            CfsStatement::Assign { lhs: "v2".into(), rhs: "rax".into() },
        ];
        capture_call_result(&mut k);
        assert!(
            matches!(&k[0], CfsStatement::Raw(r) if r == "sub_9(a1);"),
            "intervening call must kill the binding: {k:?}"
        );
        assert!(
            matches!(&k[2], CfsStatement::Raw(r) if r == "rax = sub_b(a2);"),
            "nearest call gets the capture: {k:?}"
        );
        // An intervening plain write to rax in the next block also kills it.
        let mut w = vec![
            CfsStatement::Raw("sub_9(a1);".into()),
            CfsStatement::Raw("loc_28:".into()),
            CfsStatement::Assign { lhs: "rax".into(), rhs: "0".into() },
            CfsStatement::Assign { lhs: "v2".into(), rhs: "rax".into() },
        ];
        capture_call_result(&mut w);
        assert!(
            matches!(&w[0], CfsStatement::Raw(r) if r == "sub_9(a1);"),
            "intervening rax write must kill the binding: {w:?}"
        );
    }

    #[test]
    fn capture_call_result_follows_backward_goto_to_loop_head_use() {
        // Residual class: the call is at the BOTTOM of a loop body and the
        // only rax use is at the loop HEAD, reached via a backward goto. A
        // purely forward scan never sees the use.
        let mut b = vec![
            CfsStatement::Raw("loc_10:".into()),
            CfsStatement::Assign { lhs: "v2".into(), rhs: "rax".into() },
            CfsStatement::Raw("sub_9(a1);".into()),
            CfsStatement::Raw("goto loc_10;".into()),
        ];
        capture_call_result(&mut b);
        assert!(
            matches!(&b[2], CfsStatement::Raw(r) if r == "rax = sub_9(a1);"),
            "backward-goto loop-head rax use must trigger capture: {b:?}"
        );
        // Same shape but the loop head DEFINES rax before any use → the
        // call's result is dead on the back edge; no capture.
        let mut d = vec![
            CfsStatement::Raw("loc_10:".into()),
            CfsStatement::Assign { lhs: "rax".into(), rhs: "0".into() },
            CfsStatement::Assign { lhs: "v2".into(), rhs: "rax".into() },
            CfsStatement::Raw("sub_9(a1);".into()),
            CfsStatement::Raw("goto loc_10;".into()),
        ];
        capture_call_result(&mut d);
        assert!(
            matches!(&d[3], CfsStatement::Raw(r) if r == "sub_9(a1);"),
            "loop-head rax def must kill the backward binding: {d:?}"
        );
    }

    #[test]
    fn refine_param_types_does_not_treat_lea_as_a_dereference() {
        // `add_fn(int32_t x, int32_t y)` compiles to `lea (%rcx,%rdx), %eax` —
        // lea as a plain adder. Typing x as `int *` from that makes `x + y`
        // pointer arithmetic that scales y by 4: add_fn(3,4) == 3+16.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 __fastcall add_fn(__int64 a1, __int64 a2) {\n    return a1 + a2;\n}";
        let out = refine_param_types(code, &[ins("lea", "(%rcx,%rdx), %eax")]);
        assert!(!out.contains('*'), "lea must not promote a param to a pointer: {out}");
        // A real memory read through the param still proves a pointer.
        let out = refine_param_types(code, &[ins("movzbl", "(%rcx), %eax")]);
        assert!(out.contains("char *a1"), "a genuine byte deref must still type a1: {out}");
    }

    #[test]
    fn refine_param_types_byte_cmp_deref_types_param_char_ptr() {
        // Corpus witness `my_strlen(const char *s)`: the only deref of the
        // live param register is `cmpb $0, (%rcx)` (the loop derefs go
        // through a copy in rax). A memory-operand cmp is a byte-wide read
        // through the base — the observed access width must pick `char *`,
        // not leave the promoted `__int64 *`.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 __fastcall my_strlen(__int64 *a1) {\n    return *a1;\n}";
        let out = refine_param_types(code, &[ins("cmpb", "$0, (%rcx)"), ins("je", "0x2000")]);
        assert!(out.contains("char *a1"), "byte cmp deref must type a1 char*: {out}");
        // Scalar form: the promotion is recorded for the rescaler.
        let scode = "__int64 __fastcall my_strlen(__int64 a1) {\n    return a1;\n}";
        let (sout, rec) = refine_param_types_rec(scode, &[ins("cmpb", "$0, (%rcx)")]);
        assert!(sout.contains("char *a1"), "scalar byte-cmp deref must promote: {sout}");
        assert_eq!(rec, vec!["a1".to_string()], "scalar→pointer promotion must be recorded");
    }

    #[test]
    fn refine_param_types_records_scalar_to_pointer_promotions_for_rescale() {
        // Ptr-scaling CLASS rule: any pass retyping int→pointer must feed the
        // rescaler. A scalar `__int64 a1` promoted here to `int *` keeps its
        // byte arithmetic (`a1 += 4` meaning 4 BYTES) — emitted as int*
        // arithmetic that is 16 bytes unless the name is recorded.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 __fastcall f(__int64 a1) {\n    a1 += 4;\n    return a1;\n}";
        let (out, rec) = refine_param_types_rec(code, &[ins("movl", "(%rcx), %eax")]);
        assert!(out.contains("int *a1"), "dword deref must type a1 int*: {out}");
        assert_eq!(rec, vec!["a1".to_string()], "scalar→pointer promotion must be recorded");
        // Sharpening an ALREADY-pointer param is not a new promotion — the
        // earlier promotion pass recorded it; no duplicate record here.
        let pcode = "__int64 __fastcall f(__int64 *a1) {\n    return *a1;\n}";
        let (_, rec2) = refine_param_types_rec(pcode, &[ins("movl", "(%rcx), %eax")]);
        assert!(rec2.is_empty(), "pointer sharpening must not re-record: {rec2:?}");
    }

    #[test]
    fn refine_param_types_two_param_cmp_attributes_count_role_deterministically() {
        // `cmp %rdx, %r8` mentions TWO param registers (a2 and a3). Which one
        // the following `ja` marks used_as_count/unsigned used to depend on
        // HashMap iteration order, flipping a3 between `int *`-family and
        // `size_t`-family verdicts run-to-run. The tie-break is now fixed ABI
        // order: the LOWEST param index mentioned takes the count role, so a3
        // (whose other evidence is small_cmp + narrow_use) must always come
        // out `int`, never `size_t`.
        let ins = |m: &str, o: &str| make_instr(0x1000, m, o);
        let code = "__int64 __fastcall f(__int64 a1, __int64 a2, __int64 a3) {\n    return a3;\n}";
        let instrs = [
            ins("cmpl", "$0x10, %r8d"), // a3: small_cmp + narrow_use
            ins("je", "0x2000"),
            ins("cmp", "%rdx, %r8"),    // ambiguous: mentions a2 AND a3
            ins("ja", "0x2000"),        // unsigned count evidence → a2 (lowest), not a3
        ];
        for _ in 0..4 {
            let out = refine_param_types(code, &instrs);
            assert!(out.contains("int a3"), "a3 must deterministically stay int: {out}");
            assert!(!out.contains("size_t a3"), "a3 must not flip to size_t: {out}");
        }
    }

    #[test]
    fn att_mem_access_width_reports_the_memory_operand_not_the_destination() {
        // The extension family spells src-size then dst-size: the memory read
        // in `movzbl (%rcx), %eax` is ONE byte, even though the dst is 4.
        // (`width_hint_from_instr` answers 4 here — that is the difference.)
        assert_eq!(att_mem_access_width("movzbl", "(%rcx), %eax"), Some(1));
        assert_eq!(att_mem_access_width("movzwl", "(%rcx), %eax"), Some(2));
        assert_eq!(att_mem_access_width("movslq", "(%rcx), %rax"), Some(4));
        // Plain size suffix sizes the whole operation.
        assert_eq!(att_mem_access_width("movb", "$1, (%rcx)"), Some(1));
        assert_eq!(att_mem_access_width("cmpl", "$5, (%rcx)"), Some(4));
        // Unsuffixed AT&T: the register operand fixes the size.
        assert_eq!(att_mem_access_width("mov", "(%rcx), %eax"), Some(4));
        assert_eq!(att_mem_access_width("mov", "(%rcx), %rax"), Some(8));
        // Intel operand hints still work.
        assert_eq!(att_mem_access_width("movzx", "eax, byte ptr [rcx]"), Some(1));
    }

    #[test]
    fn writes_reg_sees_att_sized_writes() {
        // `movzwl 6(%r8), %r9d` WRITES r9 — missing this left the register
        // eligible to be mistaken for an incoming parameter. The caller passes
        // each width alias in turn, so the destination is matched as `r9d`.
        assert!(writes_reg("movzwl", "6(%r8), %r9d", "r9d"));
        assert!(writes_reg("movslq", "0x3C(%rdx), %r8", "r8"));
        assert!(writes_reg("movl", "$1, %edx", "edx"));
        // A store through a register is not a write TO that register.
        assert!(!writes_reg("movl", "%eax, 8(%rdx)", "rdx"));
        // Regression guard: the plain (unsized) forms still work.
        assert!(writes_reg("mov", "0x1FE9(%rip), %rdx", "rdx"));
    }

    #[test]
    fn clamp_known_api_call_arity_casts_deficit_calls_through_fn_pointer() {
        // A call site whose argument recovery came up SHORT of the known
        // prototype (`strlen();` — cross-block setup lost) is a hard gcc
        // error against the string.h prototype. The argument cannot be
        // fabricated, so the call is routed through an explicit
        // function-pointer cast — valid gnu89, name preserved, no invented
        // argument. (Found via sample7_cpp/sub_140011740: strlen call in an
        // out-of-line `call; jmp` block.)
        let c = "void f() {\n    strlen();\n}";
        let out = clamp_known_api_call_arity(c);
        assert!(out.contains("((__int64 (*)())strlen)();"), "{out}");
        // Partial deficit gets the same treatment, keeping the args it has.
        let p = "void f() {\n    v1 = strchr(v4);\n}";
        let pout = clamp_known_api_call_arity(p);
        assert!(pout.contains("v1 = ((__int64 (*)())strchr)(v4);"), "{pout}");
        // Exact arity stays untouched.
        let ok = "void f() {\n    strchr(v4, a2);\n}";
        assert_eq!(clamp_known_api_call_arity(ok), ok);
        // A zero-arg call to a zero-arg prototype stays untouched.
        // (No such CRT entry with 0 params is in the table today; guard the
        // unknown-name path instead.)
        let unk = "void f() {\n    sub_140001000();\n}";
        assert_eq!(clamp_known_api_call_arity(unk), unk);
        // WinAPI names are declared UNPROTOTYPED by the forward-declaration
        // pass, so a short call is already legal — and the cast would hide
        // the name from that pass ("'CloseHandle' undeclared"). Never cast.
        let win = "void f() {\n    CloseHandle();\n}";
        assert_eq!(clamp_known_api_call_arity(win), win);
    }

    #[test]
    fn clamp_direct_call_arity_clamps_only_known_targets() {
        let mut known: HashMap<String, usize> = HashMap::new();
        known.insert("rec_f21_0".to_string(), 2);

        // D10: a direct call to a KNOWN 2-arity target emitted with three
        // argument expressions is clamped to two.
        let over = "void f() {\n    result = rec_f21_0(a1, a2, v7);\n}";
        assert_eq!(
            clamp_direct_call_arity(over, &known),
            "void f() {\n    result = rec_f21_0(a1, a2);\n}"
        );
        // Tail-call and bare-call shapes clamp too.
        let tail = "void f() {\n    return rec_f21_0(a1, a2, v7);\n}";
        assert!(clamp_direct_call_arity(tail, &known).contains("return rec_f21_0(a1, a2);"));

        // A call to an UNKNOWN target is untouched — never guessed.
        let unk = "void f() {\n    result = sub_140001000(a1, a2, v7);\n}";
        assert_eq!(clamp_direct_call_arity(unk, &known), unk);

        // A correct 2-of-2 call is unchanged.
        let exact = "void f() {\n    result = rec_f21_0(a1, a2);\n}";
        assert_eq!(clamp_direct_call_arity(exact, &known), exact);

        // A DEFICIT is left alone (nothing is fabricated).
        let short = "void f() {\n    result = rec_f21_0(a1);\n}";
        assert_eq!(clamp_direct_call_arity(short, &known), short);

        // An empty map is a no-op over the whole body.
        assert_eq!(clamp_direct_call_arity(over, &HashMap::new()), over);

        // Regression (D10 over-reach): a statically-linked CRT callee whose
        // RECOVERED arity is wrong must be left completely alone — clamping
        // `fprintf`/`vfprintf` to their bogus 0 emitted `fprintf();`, and
        // `fwrite`/`strtoul` lost real arguments. Published prototype wins.
        let mut lib: HashMap<String, usize> = HashMap::new();
        lib.insert("fprintf".to_string(), 0);
        lib.insert("vfprintf".to_string(), 0);
        lib.insert("fwrite".to_string(), 2);
        lib.insert("strtoul".to_string(), 2);
        let crt = "void f() {\n    fprintf(v1, v2, v3);\n    vfprintf(v1, v2, v3);\n    fwrite(a, b, c, d);\n    n = strtoul(s, e, 10);\n}";
        assert_eq!(clamp_direct_call_arity(crt, &lib), crt);

        // A recovered arity of 0 is UNKNOWN, never "takes nothing" — even for
        // an in-image synthesized name.
        let mut zero: HashMap<String, usize> = HashMap::new();
        zero.insert("sub_140001000".to_string(), 0);
        let z = "void f() {\n    sub_140001000(a1, a2);\n}";
        assert_eq!(clamp_direct_call_arity(z, &zero), z);

        // Commas nested inside an argument expression are not split points.
        let nested = "void f() {\n    result = rec_f21_0(g(x, y), a2, v7);\n}";
        assert_eq!(
            clamp_direct_call_arity(nested, &known),
            "void f() {\n    result = rec_f21_0(g(x, y), a2);\n}"
        );
    }

    #[test]
    fn clamp_known_api_call_arity_drops_surplus_args() {
        // A tail call is symbolised to `atexit` only after arity inference, so
        // the surplus register slot survives to the final text.
        let c = "void f() {\n    return atexit(v7, src);\n}";
        assert!(clamp_known_api_call_arity(c).contains("return atexit(v7);"), "{}", clamp_known_api_call_arity(c));
        // Correct arity is left byte-identical.
        let ok = "void f() {\n    memchr(a1, a2, a3);\n}";
        assert_eq!(clamp_known_api_call_arity(ok), ok);
        // Unknown callees are never touched.
        let unk = "void f() {\n    sub_140001000(a1, a2, a3, a4);\n}";
        assert_eq!(clamp_known_api_call_arity(unk), unk);
        // Commas inside a nested call must not be counted as outer arguments.
        let nested = "void f() {\n    atexit(sub_1(a, b), c);\n}";
        assert!(clamp_known_api_call_arity(nested).contains("atexit(sub_1(a, b));"), "{}", clamp_known_api_call_arity(nested));
        // The `LHS = f(...)` form keeps working.
        let assign = "void f() {\n    v1 = atexit(v7, src);\n}";
        assert!(clamp_known_api_call_arity(assign).contains("v1 = atexit(v7);"), "{}", clamp_known_api_call_arity(assign));
    }

    #[test]
    fn fuse_standalone_cmov_keeps_the_seed_as_the_else_value() {
        // `eax = 0; cmovg eax, ebx` is a max: on the false path eax must be 0.
        // Dropping the seed left eax reading its previous value.
        let mut stmts = vec![
            CfsStatement::Assign { lhs: "eax".into(), rhs: "0".into() },
            CfsStatement::Raw("if (flags >) eax = ebx;".into()),
        ];
        fuse_standalone_cmov(&mut stmts);
        assert!(
            stmts.iter().any(|s| matches!(s, CfsStatement::Assign { lhs, rhs } if lhs == "eax" && rhs == "0")),
            "seed (else-value) dropped: {stmts:?}"
        );
        assert!(
            stmts.iter().any(|s| matches!(s, CfsStatement::Raw(r) if r == "if (ebx > 0) eax = ebx;")),
            "cmov not fused: {stmts:?}"
        );
    }

    #[test]
    fn lift_rep_movs_keeps_count_def_read_before_the_rep() {
        // The count value is folded into the memcpy, but an intervening
        // statement READS rcx — deleting the def would lose that value.
        let mut stmts = vec![
            CfsStatement::Assign { lhs: "rcx".into(), rhs: "0x10".into() },
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "rcx + 1".into() },
            CfsStatement::Raw("/* rep movsb */".into()),
        ];
        lift_rep_movs(&mut stmts);
        assert!(
            stmts.iter().any(|s| matches!(s, CfsStatement::Assign { lhs, rhs } if lhs == "rcx" && rhs == "0x10")),
            "live count def dropped: {stmts:?}"
        );
        assert!(
            stmts.iter().any(|s| matches!(s, CfsStatement::Raw(r) if r.starts_with("memcpy("))),
            "rep not re-raised: {stmts:?}"
        );
        // With no intervening reader the def is still folded away, as before.
        let mut plain = vec![
            CfsStatement::Assign { lhs: "rcx".into(), rhs: "0x10".into() },
            CfsStatement::Raw("/* rep movsb */".into()),
        ];
        lift_rep_movs(&mut plain);
        assert!(
            !plain.iter().any(|s| matches!(s, CfsStatement::Assign { lhs, .. } if lhs == "rcx")),
            "dead count def fold regressed: {plain:?}"
        );
    }

    #[test]
    fn infer_call_arguments_keeps_arg_setup_read_before_the_call() {
        // `edx = r9d` sets the rdx arg slot, but a load between it and the call
        // READS rdx. Folding the value into the call and deleting the def left
        // that load reading rdx's previous value (the frame pointer set above) —
        // the `buf[buf]` bug. The def must survive; the call still names rdx.
        let mut stmts = vec![
            CfsStatement::Assign { lhs: "rdx".into(), rhs: "rsp + 0x20".into() },
            CfsStatement::Assign { lhs: "edx".into(), rhs: "r9d".into() },
            CfsStatement::Assign { lhs: "r8d".into(), rhs: "*(rsp + rdx*2 + 0x20)".into() },
            CfsStatement::Raw("sub_14009BC00();".into()),
        ];
        infer_call_arguments(&mut stmts);
        let alive = stmts
            .iter()
            .any(|s| matches!(s, CfsStatement::Assign { lhs, rhs } if lhs == "edx" && rhs == "r9d"));
        assert!(alive, "live arg-setup def was folded away: {stmts:?}");
        // A setup with no intervening read still folds, as before.
        let mut plain = vec![
            CfsStatement::Assign { lhs: "ecx".into(), rhs: "0xA".into() },
            CfsStatement::Raw("sub_140001000();".into()),
        ];
        infer_call_arguments(&mut plain);
        assert!(
            plain.iter().any(|s| matches!(s, CfsStatement::Raw(r) if r.contains("0xA"))),
            "plain literal fold regressed: {plain:?}"
        );
    }

    #[test]
    fn cast_nonpointer_deref_casts_int_operands() {
        // Bare frame-register write/read.
        let w = "int f() {\n    __int64 rsp;\n    *rsp = a4;\n}";
        assert!(cast_nonpointer_deref(w).contains("*(__int64 *)rsp = a4;"), "{}", cast_nonpointer_deref(w));
        let r = "int f() {\n    __int64 rsp;\n    a2 = *rsp;\n}";
        assert!(cast_nonpointer_deref(r).contains("a2 = *(__int64 *)rsp;"), "{}", cast_nonpointer_deref(r));
        // Frame reg inside parenthesized arithmetic.
        let p = "int f() {\n    *(rsp + result + 64) = a1;\n}";
        assert!(cast_nonpointer_deref(p).contains("*(__int64 *)(rsp + result + 64) = a1;"), "{}", cast_nonpointer_deref(p));
        // `(__int64)`-cast integer sum.
        let c = "int f() {\n    dst = *((__int64)src + (__int64)dst);\n}";
        assert!(cast_nonpointer_deref(c).contains("dst = *(__int64 *)((__int64)src + (__int64)dst);"), "{}", cast_nonpointer_deref(c));
        // `return *rsp;` — the previous token is the keyword `return`, not a
        // multiplicand, so `*` is a UNARY deref and must be cast (found via
        // sample4_go/sub_140049de0's `return *rsp;`).
        let ret = "int f() {\n    __int64 rsp;\n    return *rsp;\n}";
        assert!(cast_nonpointer_deref(ret).contains("return *(__int64 *)rsp;"), "{}", cast_nonpointer_deref(ret));
        // A genuine pointer deref is left alone.
        let g = "int f() {\n    __int64 *ptr;\n    v = *ptr;\n    w = *(a1 + 4);\n}";
        assert_eq!(cast_nonpointer_deref(g), g);
        // Multiplication is not a deref.
        let m = "int f() {\n    x = a * b;\n}";
        assert_eq!(cast_nonpointer_deref(m), m);
        // Idempotent: an already-cast deref is untouched.
        let idem = "int f() {\n    *(__int64 *)rsp = a4;\n}";
        assert_eq!(cast_nonpointer_deref(idem), idem);
    }

    /// ⚠ Il confine di parola serve su ENTRAMBI i lati: `operator_new` e'
    /// PREFISSO di `operator_new_unsigned_long_long_`, e una sostituzione
    /// ingenua produrrebbe `operator_new_unsigned_long_long__unsigned_long_long_`.
    #[test]
    fn rename_ident_rispetta_il_confine_di_parola() {
        let code = "void operator_new(uint64_t a1)
{
    operator_new_unsigned_long_long_(a1);
}
";
        let out = rename_ident_everywhere(code, "operator_new", "operator_new_unsigned_long_long_");
        assert!(out.contains("void operator_new_unsigned_long_long_(uint64_t a1)"), "{out}");
        // la chiamata gia' lunga NON deve essere estesa una seconda volta
        assert!(!out.contains("long__unsigned_long_long_"), "{out}");
    }

    #[test]
    fn rename_ident_noop_se_uguale_o_assente() {
        let code = "void f()
{
}
";
        assert_eq!(rename_ident_everywhere(code, "f", "f"), code);
        assert_eq!(rename_ident_everywhere(code, "g", "h"), code);
        assert_eq!(rename_ident_everywhere(code, "", "x"), code);
    }

    /// Un identificatore che CONTIENE il nome non va toccato.
    #[test]
    fn rename_ident_non_tocca_i_nomi_che_lo_contengono() {
        let code = "void f()
{
    xf_y(); f_z(); my_f();
}
";
        let out = rename_ident_everywhere(code, "f", "QQ");
        // nessuno di questi contiene `f` come PAROLA INTERA
        assert!(out.contains("xf_y()") && out.contains("f_z()") && out.contains("my_f()"), "{out}");
        // solo la definizione, dove `f` e' isolata, viene rinominata
        assert!(out.contains("void QQ()"), "{out}");
    }

    #[test]
    fn sanitize_c_identifier_cleans_symbols() {
        assert_eq!(sanitize_c_identifier("runtime.makechan"), "runtime_makechan");
        assert_eq!(sanitize_c_identifier("type:.eq.internal/cpu.option"), "type__eq_internal_cpu_option");
        assert_eq!(sanitize_c_identifier("sub_140001000"), "sub_140001000");
        assert_eq!(sanitize_c_identifier("9lives"), "_9lives");
    }

    #[test]
    fn sanitize_symbol_names_fixes_go_symbols() {
        // Definition with dotted package-qualified name.
        let d = "__int64 __fastcall runtime.makechan() {\n    return 0;\n}";
        assert!(sanitize_symbol_names(d).contains("runtime_makechan()"), "{}", sanitize_symbol_names(d));
        // Name with ':' and '/' — always illegal in C.
        let c = "__int64 type:.eq.internal/cpu.option() {\n}";
        assert!(sanitize_symbol_names(c).contains("type__eq_internal_cpu_option()"), "{}", sanitize_symbol_names(c));
        // Call site is rewritten to match.
        let s = "int f() {\n    runtime.newobject(a1);\n}";
        assert!(sanitize_symbol_names(s).contains("runtime_newobject(a1)"), "{}", sanitize_symbol_names(s));
        // Struct member function-pointer call through a declared local is LEFT ALONE.
        let m = "int f() {\n    struct S *a1;\n    a1.fn(a1);\n}";
        assert!(sanitize_symbol_names(m).contains("a1.fn(a1)"), "{}", sanitize_symbol_names(m));
        // Control-flow headers are untouched (no separators).
        let k = "int f() {\n    if (a1)\n        while (a2) {}\n}";
        assert_eq!(sanitize_symbol_names(k), k);
    }

    #[test]
    fn store_xmm_as_scalar_extracts_low_bits() {
        // int/mem slot = __m128i → extract scalar.
        let code = "int f() {\n    int v_8;\n    __m128i xmm0;\n    v_8 = xmm0;\n}";
        assert!(store_xmm_as_scalar(code).contains("v_8 = _mm_cvtsi128_si64(xmm0);"), "{}", store_xmm_as_scalar(code));
        // Memory store form.
        let mem = "int f() {\n    __m128i xmm0;\n    *(a1 - 8) = xmm0;\n}";
        assert!(store_xmm_as_scalar(mem).contains("*(a1 - 8) = _mm_cvtsi128_si64(xmm0);"), "{}", store_xmm_as_scalar(mem));
        // xmm = xmm (vector copy) is left alone.
        let vv = "int f() {\n    __m128i xmm0;\n    __m128i xmm1;\n    xmm1 = xmm0;\n}";
        assert_eq!(store_xmm_as_scalar(vv), vv);
    }

    #[test]
    fn normalize_pd_logical_to_si128_swaps_on_m128i() {
        let a = "int f() {\n    __m128i xmm1;\n    __m128i xmm2;\n    xmm1 = _mm_and_pd(xmm1, xmm2);\n}";
        assert!(normalize_pd_logical_to_si128(a).contains("xmm1 = _mm_and_si128(xmm1, xmm2);"), "{}", normalize_pd_logical_to_si128(a));
        let o = "int f() {\n    __m128i xmm7;\n    __m128i xmm1;\n    xmm7 = _mm_or_pd(xmm7, xmm1);\n}";
        assert!(normalize_pd_logical_to_si128(o).contains("xmm7 = _mm_or_si128(xmm7, xmm1);"), "{}", normalize_pd_logical_to_si128(o));
        let n = "int f() {\n    __m128i xmm0;\n    xmm0 = _mm_andnot_pd(xmm0, xmm0);\n}";
        assert!(normalize_pd_logical_to_si128(n).contains("_mm_andnot_si128("), "{}", normalize_pd_logical_to_si128(n));
        // Genuine __m128d destination keeps _pd.
        let d = "int f() {\n    __m128d xmm1;\n    __m128d xmm2;\n    xmm1 = _mm_and_pd(xmm1, xmm2);\n}";
        assert_eq!(normalize_pd_logical_to_si128(d), d);
    }

    #[test]
    fn normalize_sse_zero_matches_dest_type() {
        // __m128i dest → integer zero intrinsic.
        let v = "int f() {\n    __m128i xmm0;\n    xmm0 = _mm_setzero_ps();\n}";
        assert!(normalize_sse_zero(v).contains("xmm0 = _mm_setzero_si128();"), "{}", normalize_sse_zero(v));
        // integer dest → plain 0.
        let i = "int f() {\n    __int64 xmm8;\n    xmm8 = _mm_setzero_ps();\n}";
        assert!(normalize_sse_zero(i).contains("xmm8 = 0;"), "{}", normalize_sse_zero(i));
        // A genuine __m128 float dest is left alone.
        let f = "int f() {\n    __m128 xmm1;\n    xmm1 = _mm_setzero_ps();\n}";
        assert_eq!(normalize_sse_zero(f), f);
        // integer dest sourced from `_mm_setzero_si128()` → plain 0 (the
        // `pxor`-zeroing idiom lifts to si128, not ps, so this must match too).
        let si = "int f() {\n    __int64 xmm1;\n    xmm1 = _mm_setzero_si128();\n}";
        assert!(normalize_sse_zero(si).contains("xmm1 = 0;"), "{}", normalize_sse_zero(si));
    }

    /// The `dot` witness: mulsd/addsd comment-ops over scalar-only xmm raise
    /// to real double arithmetic, loads reinterpret bits, the trailing
    /// `xmm0 = …; return counter;` becomes `return xmm0;` with a double
    /// signature. Vector-used xmm names are untouched.
    #[test]
    fn raise_scalar_double_arith_raises_dot_shape() {
        let code = "__int64 __fastcall dot(__int64 *a1, __int64 a2, __int64 a3) {\n    \
                    __int64 xmm1;\n    __int64 xmm0;\n    __int64 result;\n    \
                    xmm0 = a1[result];\n    \
                    /* mulsd (%a2,%result,8), %xmm0 */;\n    \
                    /* addsd %xmm0, %xmm1 */;\n    \
                    xmm0 = xmm1;\n    return result;\n}";
        let out = raise_scalar_double_arith(code);
        assert!(out.starts_with("double __fastcall dot("), "{out}");
        assert!(out.contains("double xmm1;"), "{out}");
        assert!(out.contains("double xmm0;"), "{out}");
        assert!(out.contains("xmm0 = *(double *)&a1[result];"), "{out}");
        assert!(out.contains("xmm0 = xmm0 * *(double *)(a2 + result*8);"), "{out}");
        assert!(out.contains("xmm1 = xmm1 + xmm0;"), "{out}");
        assert!(out.contains("return xmm0;"), "{out}");
        assert!(!out.contains("/* mulsd"), "{out}");
        // A vector-used xmm disqualifies (stays a comment).
        let vec = "__int64 f() {\n    __m128i xmm6;\n    _mm_store_si128((__m128i *)&v, xmm6);\n    /* mulsd %xmm1, %xmm6 */;\n    return 0;\n}";
        assert_eq!(raise_scalar_double_arith(vec), vec);
    }

    /// int↔double conversions are VALUE conversions, not reinterprets:
    /// `cvtsi2sd %a1, %xmm0` → `xmm0 = (double)a1;`,
    /// `cvttsd2si %xmm2, %a2` → `a2 = (__int64)xmm2;` (C casts truncate,
    /// matching cvttsd2si). A cvt comment must qualify its xmm, not
    /// disqualify it.
    #[test]
    fn raise_scalar_double_arith_handles_int_conversions() {
        let code = "__int64 __fastcall f(__int64 a1, __int64 a2) {\n    \
                    __int64 xmm0;\n    __int64 xmm1;\n    \
                    /* cvtsi2sd %a1, %xmm0 */;\n    \
                    xmm1 = off_1400CE110;\n    \
                    /* mulsd %xmm0, %xmm1 */;\n    \
                    /* cvttsd2si %xmm1, %a2 */;\n    \
                    return a2;\n}";
        let out = raise_scalar_double_arith(code);
        assert!(out.contains("xmm0 = (double)(__int64)a1;"), "{out}");
        assert!(out.contains("xmm1 = *(double *)&off_1400CE110;"), "{out}");
        assert!(out.contains("xmm1 = xmm1 * xmm0;"), "{out}");
        // ENABLED 2026-07-18: the LHS-cast mangler (cast passes casting
        // inside `/*` asm comments) is fixed, so the truncating convert
        // raises to a real C cast.
        assert!(out.contains("a2 = (__int64)xmm1;"), "{out}");
        assert!(out.contains("double xmm0;"), "{out}");
        assert!(out.contains("double xmm1;"), "{out}");
    }

    /// The ss mirror of the `dot` witness: mulss/addss comment-ops raise to
    /// real `float` arithmetic, loads reinterpret bits as `*(float *)`,
    /// cvtsi2ss becomes a value cast, `_mm_loadl_epi64` peels to a float
    /// read, and the signature retypes to `float` when all returns are
    /// raised.
    #[test]
    fn raise_scalar_single_arith_raises_float_shape() {
        let code = "__int64 __fastcall dotf(__int64 *a1, __int64 a2, __int64 a3) {\n    \
                    __int64 xmm1;\n    __int64 xmm0;\n    __int64 result;\n    \
                    xmm0 = _mm_loadl_epi64((__m128i *)(a1 + 8));\n    \
                    /* mulss (%a2,%result,4), %xmm0 */;\n    \
                    /* addss %xmm0, %xmm1 */;\n    \
                    /* cvtsi2ss %a3, %xmm1 */;\n    \
                    xmm0 = xmm1;\n    return result;\n}";
        let out = raise_scalar_single_arith(code);
        assert!(out.starts_with("float __fastcall dotf("), "{out}");
        assert!(out.contains("float xmm1;"), "{out}");
        assert!(out.contains("float xmm0;"), "{out}");
        assert!(out.contains("xmm0 = *(float *)(a1 + 8);"), "{out}");
        assert!(out.contains("xmm0 = xmm0 * *(float *)(a2 + result*4);"), "{out}");
        assert!(out.contains("xmm1 = xmm1 + xmm0;"), "{out}");
        assert!(out.contains("xmm1 = (float)(__int64)a3;"), "{out}");
        assert!(out.contains("return xmm0;"), "{out}");
        assert!(!out.contains("/* mulss"), "{out}");
        // cvttss2si stays a comment (disabled identically to cvttsd2si until
        // the LHS-cast mangler is fixed) and must NOT disqualify its xmm.
        let cvt = "__int64 f(__int64 a1) {\n    __int64 xmm2;\n    \
                   /* cvtsi2ss %a1, %xmm2 */;\n    /* mulss %xmm2, %xmm2 */;\n    \
                   /* cvttss2si %xmm2, %a1 */;\n    return a1;\n}";
        let outc = raise_scalar_single_arith(cvt);
        assert!(outc.contains("float xmm2;"), "{outc}");
        // ENABLED 2026-07-18 alongside cvttsd2si (comment mangler fixed).
        assert!(outc.contains("a1 = (__int64)xmm2;"), "{outc}");
        // A vector-used xmm disqualifies (stays a comment).
        let vec = "__int64 f() {\n    __m128i xmm6;\n    _mm_store_si128((__m128i *)&v, xmm6);\n    /* mulss %xmm1, %xmm6 */;\n    return 0;\n}";
        assert_eq!(raise_scalar_single_arith(vec), vec);
    }

    /// Cross-family gate: an xmm touched by BOTH sd and ss ops must be
    /// raised by NEITHER pass (double != float) — each family sees the other
    /// family's comment as unmodelled flow.
    #[test]
    fn raise_scalar_fp_arith_mixed_sd_ss_disqualifies_both() {
        let code = "__int64 f() {\n    __int64 xmm0;\n    \
                    /* mulsd %xmm0, %xmm0 */;\n    /* addss %xmm0, %xmm0 */;\n    return 0;\n}";
        assert_eq!(raise_scalar_double_arith(code), code);
        assert_eq!(raise_scalar_single_arith(code), code);
        // And running one after the other (pipeline order) changes nothing.
        assert_eq!(
            raise_scalar_single_arith(&raise_scalar_double_arith(code)),
            code
        );
    }

    /// Scalar CROSS-PRECISION convert bridge: a ss-float chain that passes
    /// through a `cvtps2pd` (float→double) and back must raise fully. The
    /// combined `raise_scalar_fp` classifies once so the sd pass owns the
    /// double names and the ss pass owns the float names, and the converts
    /// become real C value casts. Mirrors sample10_cs/sub_14005ef90, including
    /// the in-place `cvtps2pd %xmm0,%xmm0` that must fold into its consumer.
    #[test]
    fn raise_scalar_fp_cross_precision_bridge() {
        let code = "__int64 __fastcall f(__int64 a1) {\n    \
                    __m128i xmm0;\n    __int64 xmm1;\n    __int64 result;\n    \
                    /* cvtsi2ss %a1, %xmm0 */;\n    \
                    /* addss %xmm0, %xmm0 */;\n    \
                    /* cvtps2pd %xmm0, %xmm1 */;\n    \
                    /* mulsd off_1, %xmm1 */;\n    \
                    /* cvtsi2ss %a1, %xmm0 */;\n    \
                    /* cvtps2pd %xmm0, %xmm0 */;\n    \
                    /* divsd %xmm0, %xmm1 */;\n    \
                    /* cvttsd2si %xmm1, %result */;\n    \
                    *dst = result;\n    return result;\n}";
        let out = raise_scalar_fp(code);
        assert!(out.contains("float xmm0;"), "{out}");
        assert!(out.contains("double xmm1;"), "{out}");
        assert!(out.contains("xmm0 = (float)(__int64)a1;"), "{out}");
        assert!(out.contains("xmm0 = xmm0 + xmm0;"), "{out}");
        // cross-register float->double bridge becomes a value cast:
        assert!(out.contains("xmm1 = (double)xmm0;"), "{out}");
        assert!(out.contains("xmm1 = xmm1 * *(double *)&off_1;"), "{out}");
        // in-place cvtps2pd is folded into the divsd consumer as (double):
        assert!(out.contains("xmm1 = xmm1 / (double)xmm0;"), "{out}");
        assert!(out.contains("result = (__int64)xmm1;"), "{out}");
        // NO leaked asm comments remain for the chain.
        assert!(!out.contains("/* cvtps2pd"), "{out}");
        assert!(!out.contains("/* addss"), "{out}");
        assert!(!out.contains("/* divsd"), "{out}");
        assert!(!out.contains("/* mulsd"), "{out}");
        assert!(!out.contains("/* cvtsi2ss"), "{out}");
        // A GENUINE packed use of xmm0 must still disqualify the bridge (the
        // convert stays a comment, nothing is mis-cast).
        let packed = "__int64 f() {\n    __m128i xmm0;\n    __int64 xmm1;\n    \
                      _mm_store_si128((__m128i *)&g, xmm0);\n    \
                      /* cvtps2pd %xmm0, %xmm1 */;\n    /* mulsd %xmm1, %xmm1 */;\n    return 0;\n}";
        let outp = raise_scalar_fp(packed);
        assert!(outp.contains("/* cvtps2pd %xmm0, %xmm1 */"), "{outp}");
    }

    #[test]
    fn retype_scalar_only_xmm_to_int64() {
        // xmm8 only assigned a scalar → becomes __int64.
        let code = "int f() {\n    __m128i xmm8;\n    xmm8 = a1[4];\n    return xmm8;\n}";
        let out = retype_scalar_only_xmm(code);
        assert!(out.contains("__int64 xmm8;"), "{out}");
        assert!(!out.contains("__m128i xmm8;"), "{out}");
        // xmm0 only ever self-zeroed then assigned a scalar → the zeroing
        // idiom alone doesn't count as vector evidence, so it retypes too.
        let scalar_zeroed =
            "int f() {\n    __m128i xmm0;\n    xmm0 = _mm_setzero_ps();\n    xmm0 = a1[4];\n}";
        let out2 = retype_scalar_only_xmm(scalar_zeroed);
        assert!(out2.contains("__int64 xmm0;"), "{out2}");
        // xmm0 self-zeroed but ALSO used with a real packed op → stays __m128i.
        let vec = "int f() {\n    __m128i xmm0;\n    xmm0 = _mm_setzero_ps();\n    xmm0 = _mm_add_epi32(xmm0, xmm1);\n}";
        let out3 = retype_scalar_only_xmm(vec);
        assert!(out3.contains("__m128i xmm0;"), "{out3}");
    }

    #[test]
    fn cast_pointer_unary_minus_casts_negated_pointer() {
        let code = "int f(struct S *a2) {\n    a2 = -a2;\n}";
        assert!(cast_pointer_unary_minus(code).contains("a2 = (struct S *)(-(__int64)a2);"), "{}", cast_pointer_unary_minus(code));
        // Integer LHS + pointer RHS.
        let ir = "int f(struct S *p) {\n    __int64 v;\n    v = -p;\n}";
        assert!(cast_pointer_unary_minus(ir).contains("v = -(__int64)p;"), "{}", cast_pointer_unary_minus(ir));
        // Non-pointer negation untouched.
        let i = "int f() {\n    __int64 v;\n    v = -v;\n}";
        assert_eq!(cast_pointer_unary_minus(i), i);
    }

    #[test]
    fn cast_pointer_bit_complement_casts_complemented_pointer() {
        let code = "int f(struct S *a2) {\n    a2 = ~a2;\n}";
        assert!(cast_pointer_bit_complement(code).contains("a2 = (struct S *)(~(__int64)a2);"), "{}", cast_pointer_bit_complement(code));
        // Integer LHS + pointer RHS.
        let ir = "int f(struct S *p) {\n    __int64 v;\n    v = ~p;\n}";
        assert!(cast_pointer_bit_complement(ir).contains("v = ~(__int64)p;"), "{}", cast_pointer_bit_complement(ir));
        // Non-pointer complement untouched.
        let i = "int f() {\n    __int64 v;\n    v = ~v;\n}";
        assert_eq!(cast_pointer_bit_complement(i), i);
    }

    #[test]
    fn cast_pointer_array_index_casts_pointer_subscript() {
        // `v1[a1]` where a1 is a pointer → `v1[(__int64)a1]`.
        let code = "int f(struct S *a1) {\n    v10 = v1[a1];\n}";
        assert!(cast_pointer_array_index(code).contains("v1[(__int64)a1]"), "{}", cast_pointer_array_index(code));
        // Integer subscript untouched.
        let i = "int f() {\n    __int64 idx;\n    v = arr[idx];\n}";
        assert_eq!(cast_pointer_array_index(i), i);
        // A literal subscript untouched.
        let lit = "int f() {\n    v = arr[3];\n}";
        assert_eq!(cast_pointer_array_index(lit), lit);
    }

    #[test]
    fn cast_pointer_additive_both_operands_gated_on_two_pointers() {
        // ptr + ptr (+ int) → both pointers cast, the int left alone.
        let code = "int f(struct S *ptr2, struct S *a1) {\n    a1 = ptr2 + a1 + 16;\n}";
        let out = cast_pointer_additive_both_operands(code);
        assert!(out.contains("(__int64)ptr2 + (__int64)a1 + 16"), "{out}");
        // ptr - ptr → both cast.
        let sub = "int f(struct S *result, struct S *a2) {\n    result -= a2;\n    v = result - a2;\n}";
        assert!(cast_pointer_additive_both_operands(sub).contains("(__int64)result - (__int64)a2"), "{}", cast_pointer_additive_both_operands(sub));
        // `ptr + int` (only ONE pointer) is VALID → left untouched.
        let pi = "int f(struct S *ptr) {\n    __int64 n;\n    v = ptr + n;\n}";
        assert_eq!(cast_pointer_additive_both_operands(pi), pi);
    }

    #[test]
    fn cast_pointer_bitwise_operands_casts_both_pointers() {
        // Both pointers around `&` → both cast.
        let code = "int f(struct S *result, struct S *a1) {\n    if ((result & a1) == 0) {\n    }\n}";
        let out = cast_pointer_bitwise_operands(code);
        assert!(out.contains("((__int64)result & (__int64)a1)"), "{out}");
        // Pointer LEFT of `>>` with an integer RHS → only the pointer cast.
        let sh = "int f(struct S *a1) {\n    v = a1 >> v9;\n}";
        assert!(cast_pointer_bitwise_operands(sh).contains("(__int64)a1 >> v9"), "{}", cast_pointer_bitwise_operands(sh));
        // `a1 & 1` (pointer & literal) → pointer cast.
        let m = "int f(struct S *a1) {\n    if ((a1 & 1) == 0) {\n    }\n}";
        assert!(cast_pointer_bitwise_operands(m).contains("(__int64)a1 & 1"), "{}", cast_pointer_bitwise_operands(m));
        // Address-of (`&a1`) must NOT be treated as a binary op.
        let addr = "int f(struct S *a1) {\n    p = &a1;\n}";
        assert_eq!(cast_pointer_bitwise_operands(addr), addr);
        // Logical `&&` must NOT trigger.
        let land = "int f(struct S *a1) {\n    if (a1 && v) {\n    }\n}";
        assert_eq!(cast_pointer_bitwise_operands(land), land);
    }

    #[test]
    fn cast_pointer_added_to_pointer_casts_both() {
        // `ptr + ptr` is never valid C.
        let c = "void f() {\n    int *a1;\n    __int64 result;\n    result = a1 + a1;\n}";
        assert!(cast_pointer_added_to_pointer(c).contains("result = (__int64)a1 + (__int64)a1;"),
            "{}", cast_pointer_added_to_pointer(c));
        // `ptr + int` IS valid pointer arithmetic — must be left alone.
        let ok = "void f() {\n    int *a1;\n    __int64 v2;\n    __int64 result;\n    result = a1 + v2;\n}";
        assert_eq!(cast_pointer_added_to_pointer(ok), ok);
        // Two non-pointers are untouched.
        let ints = "void f() {\n    __int64 a1;\n    __int64 result;\n    result = a1 + a1;\n}";
        assert_eq!(cast_pointer_added_to_pointer(ints), ints);
    }

    #[test]
    fn cast_pointer_multiply_operands_casts_pointer_factor() {
        // `a1*4` where a1 is a pointer → `(__int64)a1*4`.
        let code = "int f(struct S *a1) {\n    v2 = *(a1 + a1*4);\n}";
        let out = cast_pointer_multiply_operands(code);
        // Only the `a1*4` factor is cast; the `a1 +` addend is left as-is.
        assert!(out.contains("(a1 + (__int64)a1*4)"), "{out}");
        // A non-pointer local is untouched.
        let i = "int f() {\n    __int64 n;\n    v = n*4;\n}";
        assert_eq!(cast_pointer_multiply_operands(i), i);
        // A dereference `*a1` (star before) is NOT treated as a multiply.
        let d = "int f(struct S *a1) {\n    v = *a1;\n}";
        assert_eq!(cast_pointer_multiply_operands(d), d);
    }

    #[test]
    fn cast_indirect_call_targets_wraps_computed_callees() {
        assert_eq!(cast_indirect_call_targets("    (ptr->field_30)();"),
            "    ((__int64 (*)())(ptr->field_30))();");
        assert_eq!(cast_indirect_call_targets("    (*v2)();"),
            "    ((__int64 (*)())(*v2))();");
        assert_eq!(cast_indirect_call_targets("    (*(v6 + 48))();"),
            "    ((__int64 (*)())(*(v6 + 48)))();");
        // With a result assignment.
        assert_eq!(cast_indirect_call_targets("    x = (ptr->f)(a1);"),
            "    x = ((__int64 (*)())(ptr->f))(a1);");
        // A plain grouping / arithmetic is NOT a call target → untouched.
        assert_eq!(cast_indirect_call_targets("    x = (a + b);"), "    x = (a + b);");
        // A normal function call is untouched.
        assert_eq!(cast_indirect_call_targets("    sub_140001000(a1);"), "    sub_140001000(a1);");
        // A cast expression is untouched.
        assert_eq!(cast_indirect_call_targets("    x = (__int64)a2;"), "    x = (__int64)a2;");
    }

    #[test]
    fn cast_indirect_call_targets_wraps_bare_parenthesized_local() {
        // A redundant-parens bare-identifier callee `(NAME)();` where NAME is
        // a declared local (not a real `sub_X` function) is a computed call
        // target too — previously missed since `is_computed` only checked for
        // `->`/`*`, leaving `(arg_1138)();` as an invalid "not a function or
        // function pointer" C error.
        let code = "void f() {\n    __int64 arg_1138;\n    (arg_1138)();\n}";
        let out = cast_indirect_call_targets(code);
        assert!(out.contains("((__int64 (*)())(arg_1138))();"), "{out}");

        // A real `sub_X(...)` call is never in the type map → untouched.
        let real_call = "void f() {\n    (sub_140001000)();\n}";
        assert_eq!(cast_indirect_call_targets(real_call), real_call);
    }

    #[test]
    fn cast_indirect_call_targets_wraps_bare_variable_after_return() {
        // `return v1(v3, src2);` — a bare-variable computed call target
        // preceded by `return `, not an ` = ` assignment. Previously missed:
        // the prefix-split only recognized `LHS = `, so `is_plain_ident`
        // rejected "return v1" (contains a space) and the call was left
        // uncast — "called object 'v1' is not a function or function
        // pointer".
        let code = "__int64 f(__int64 v3, __int64 *src2) {\n    __int64 v1;\n    v1 = *src2;\n    return v1(v3, src2);\n}";
        let out = cast_indirect_call_targets(code);
        assert!(out.contains("return ((__int64 (*)())v1)(v3, src2);"), "{out}");
    }

    #[test]
    fn cast_indirect_call_targets_wraps_array_subscript_callee() {
        // An indexed function-pointer-table call `(a2[4])();` — another
        // computed-callee shape, same "not a function pointer" error class.
        assert_eq!(cast_indirect_call_targets("    (a2[4])();"),
            "    ((__int64 (*)())(a2[4]))();");
        // A bare VARIABLE call — the callee is a declared local → cast it.
        let var = "int f() {\n    __int64 result;\n    result(str);\n}";
        assert!(cast_indirect_call_targets(var).contains("((__int64 (*)())result)(str);"), "{}", cast_indirect_call_targets(var));
        // But a real `sub_X()` (not a declared local) stays a plain call.
        let real = "int f() {\n    __int64 result;\n    sub_140001000(a1);\n}";
        assert!(cast_indirect_call_targets(real).contains("sub_140001000(a1);"), "{}", cast_indirect_call_targets(real));
    }

